def save_sub2api_snapshot(values: dict[str, Any]) -> None:
    save_json_atomic(SUB2API_SNAPSHOT_FILE, values, 0o600)


def _sub2api_text(value: Any, limit: int = 240) -> str:
    return clip(str(value).strip(), limit) if value is not None else ""


def _sub2api_number(value: Any) -> float | None:
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return float(value)
    match = re.search(r"-?\d[\d,]*(?:\.\d+)?", str(value or ""))
    if not match:
        return None
    try:
        return float(match.group(0).replace(",", ""))
    except ValueError:
        return None


def _sub2api_timestamp(value: Any) -> datetime | None:
    text = str(value or "").strip()
    if not text:
        return None
    normalized = text.replace("Z", "+00:00")
    try:
        parsed = datetime.fromisoformat(normalized)
    except ValueError:
        parsed = None
        for pattern in ("%Y/%m/%d %H:%M", "%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M"):
            try:
                parsed = datetime.strptime(text, pattern)
                break
            except ValueError:
                continue
        if parsed is None:
            return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone(timedelta(hours=8)))
    return parsed.astimezone(timezone.utc)


def _sub2api_quota(value: Any) -> dict[str, Any]:
    raw = _sub2api_text(value, 80)
    numbers = re.findall(r"-?\d[\d,]*(?:\.\d+)?", raw)
    if len(numbers) < 2:
        return {"raw": raw, "used": None, "limit": None, "remaining": None, "used_pct": None, "remaining_pct": None}
    used = float(numbers[0].replace(",", ""))
    limit = float(numbers[1].replace(",", ""))
    remaining = max(0.0, limit - used)
    used_pct = used / limit if limit > 0 else None
    return {
        "raw": raw,
        "used": used,
        "limit": limit,
        "remaining": remaining,
        "used_pct": used_pct,
        "remaining_pct": max(0.0, 1 - used_pct) if used_pct is not None else None,
    }


def _sub2api_key_value(value: Any) -> str:
    text = _sub2api_text(value, 48)
    if text and "..." not in text and "*" not in text and len(text) > 16:
        return "[已隐藏]"
    return text


def sanitize_sub2api_client_snapshot_id(value: Any) -> str:
    """Keep only a non-secret retry identifier generated by the browser."""
    text = str(value or "").strip()[:100]
    if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._:-]{7,99}", text):
        return ""
    return text


def sanitize_sub2api_snapshot(values: dict[str, Any]) -> dict[str, Any]:
    """Keep the browser-sync contract deliberately small and never persist full credentials."""
    source = values if isinstance(values, dict) else {}
    safe: dict[str, Any] = {}
    for key in ("source_url", "dashboard_url", "subscription_url", "checked_at", "fetched_at", "error", "source"):
        if key in source:
            safe[key] = _sub2api_text(source.get(key), 500)
    client_snapshot_id = sanitize_sub2api_client_snapshot_id(source.get("client_snapshot_id"))
    if client_snapshot_id:
        safe["client_snapshot_id"] = client_snapshot_id
    safe["logged_in"] = bool(source.get("logged_in"))
    safe["balance"] = _sub2api_text(source.get("balance"), 80)
    for section in ("today", "total"):
        raw = source.get(section) if isinstance(source.get(section), dict) else {}
        safe[section] = {key: _sub2api_text(raw.get(key), 80) for key in ("requests", "cost", "tokens") if key in raw}
    raw_api_keys = source.get("api_keys") if isinstance(source.get("api_keys"), dict) else {}
    safe["api_keys"] = {key: int(raw_api_keys.get(key) or 0) for key in ("total", "active") if str(raw_api_keys.get(key) or "").strip()}
    raw_subscription = source.get("subscription") if isinstance(source.get("subscription"), dict) else {}
    safe["subscription"] = {
        key: _sub2api_text(raw_subscription.get(key), 160)
        for key in ("name", "provider", "status", "expires_at", "remaining", "weekly_usage", "weekly_reset", "monthly_usage", "monthly_reset")
        if raw_subscription.get(key) is not None
    }
    safe_keys: list[dict[str, Any]] = []
    for raw_key in source.get("keys") or []:
        if not isinstance(raw_key, dict):
            continue
        safe_keys.append(
            {
                "name": _sub2api_text(raw_key.get("name"), 80),
                "masked": _sub2api_key_value(raw_key.get("masked") or raw_key.get("key")),
                "group": _sub2api_text(raw_key.get("group"), 100),
                "concurrency": _sub2api_text(raw_key.get("concurrency"), 40),
                "today_cost": _sub2api_text(raw_key.get("today_cost"), 80),
                "month_cost": _sub2api_text(raw_key.get("month_cost"), 80),
                "expires": _sub2api_text(raw_key.get("expires"), 100),
                "status": _sub2api_text(raw_key.get("status"), 40),
            }
        )
    safe["keys"] = safe_keys[:100]
    return safe


def analyze_sub2api_snapshot(snapshot: dict[str, Any], now: datetime | None = None) -> dict[str, Any]:
    now = now or datetime.now(timezone.utc)
    checked_at = snapshot.get("checked_at") or snapshot.get("fetched_at")
    checked_dt = _sub2api_timestamp(checked_at)
    age_seconds = max(0, int((now - checked_dt).total_seconds())) if checked_dt else None
    if checked_dt is None:
        freshness_status, freshness_label = "unknown", "没有同步时间"
    elif age_seconds is not None and age_seconds <= 6 * 3600:
        freshness_status, freshness_label = "fresh", "数据新鲜"
    elif age_seconds is not None and age_seconds <= 24 * 3600:
        freshness_status, freshness_label = "aging", "数据较旧"
    else:
        freshness_status, freshness_label = "stale", "数据已过期"
    subscription = snapshot.get("subscription") if isinstance(snapshot.get("subscription"), dict) else {}
    weekly = _sub2api_quota(subscription.get("weekly_usage"))
    monthly = _sub2api_quota(subscription.get("monthly_usage"))
    remaining_days = _sub2api_number(subscription.get("remaining"))
    if remaining_days is None:
        expires_dt = _sub2api_timestamp(subscription.get("expires_at"))
        remaining_days = max(0, int((expires_dt - now).total_seconds() // 86400)) if expires_dt else None
    fields = {
        "balance": bool(str(snapshot.get("balance") or "").strip()),
        "weekly_quota": weekly["limit"] is not None,
        "monthly_quota": monthly["limit"] is not None,
        "remaining_time": remaining_days is not None or bool(subscription.get("expires_at")),
        "key_usage": bool(snapshot.get("keys")),
    }
    alerts: list[dict[str, Any]] = []
    if not snapshot.get("logged_in"):
        alerts.append({"key": "not_logged_in", "level": "error", "title": "Sub2API 未确认登录", "message": "无法确认当前浏览器登录状态，请重新打开 API Key 页面同步。"})
    if snapshot.get("error"):
        alerts.append({"key": "sync_error", "level": "error", "title": "Sub2API 同步失败", "message": _sub2api_text(snapshot.get("error"), 240)})
    if freshness_status in {"stale", "unknown"}:
        alerts.append({"key": "stale", "level": "warning", "title": "Sub2API 数据需要重新同步", "message": f"{freshness_label}；上次同步：{checked_at or '未知'}。"})
    for name, quota in (("weekly", weekly), ("monthly", monthly)):
        if quota["remaining_pct"] is not None and quota["remaining_pct"] <= 0.2:
            label = "每周" if name == "weekly" else "每月"
            alerts.append({"key": f"{name}_low", "level": "warning", "title": f"Sub2API {label}额度偏低", "message": f"{quota['raw']}，剩余约 {quota['remaining_pct']:.0%}。"})
    if remaining_days is not None and remaining_days <= 14:
        alerts.append({"key": "expires_soon", "level": "warning", "title": "Sub2API 订阅临近到期", "message": f"预计剩余 {remaining_days} 天，到期时间：{subscription.get('expires_at') or '未知'}。"})
    required_fields = [key for key, present in fields.items() if not present]
    status = "error" if any(item["level"] == "error" for item in alerts) else "warning" if alerts else "ok"
    return {
        "status": status,
        "status_label": {"ok": "账户正常", "warning": "需要关注", "error": "同步异常"}[status],
        "freshness": {"status": freshness_status, "label": freshness_label, "checked_at": checked_at or "", "age_seconds": age_seconds},
        "fields": fields,
        "missing_fields": required_fields,
        "weekly": weekly,
        "monthly": monthly,
        "remaining_days": remaining_days,
        "alerts": alerts,
    }


def sub2api_prediction(history: list[dict[str, Any]]) -> dict[str, Any]:
    """基于历史快照做额度消耗预测（纯计算，无 LLM）。

    取最近几条 weekly_remaining_pct 变化估算日均消耗，外推当前每周额度
    预计剩余天数；样本不足时给出观察提示，不做无依据预测。
    """
    points: list[tuple[float, float]] = []
    for item in history[:8]:
        pct = item.get("weekly_remaining_pct")
        if pct is None:
            continue
        try:
            checked = _sub2api_timestamp(item.get("checked_at") or item.get("created_at"))
        except Exception:  # noqa: BLE001
            continue
        if checked:
            points.append((checked.timestamp(), float(pct)))
    if len(points) < 2:
        return {"available": False, "reason": "历史快照不足（至少需要 2 次带周额度剩余的快照）"}
    points.sort(key=lambda point: point[0])
    first_ts, first_pct = points[0]
    last_ts, last_pct = points[-1]
    span_days = max(0.1, (last_ts - first_ts) / 86400.0)
    consumed = max(0.0, first_pct - last_pct)
    daily_rate = consumed / span_days
    if daily_rate <= 0.001:
        return {"available": True, "trend": "stable", "note": "近期每周额度剩余基本持平，未见明显消耗", "remaining_pct": round(last_pct, 1)}
    days_left = last_pct / daily_rate if last_pct > 0 else 0.0
    label = "fast" if daily_rate >= 5 else "normal" if daily_rate >= 1 else "slow"
    note = f"按近 {span_days:.0f} 天的消耗速度（每日约 {daily_rate:.1f}%），当前每周额度预计约 {days_left:.0f} 天后用完。"
    # 策略建议：按剩余天数和趋势给可执行提示，帮助决定是否调整用量。
    suggestions: list[str] = []
    if days_left <= 2:
        suggestions.append("额度预计两天内用完：建议暂停低频任务，优先保留给 Agent 调度和自动化。")
    elif days_left <= 5:
        suggestions.append("额度偏紧（约 5 天内用完）：建议减少非关键研究任务，或考虑提高备用 Provider 的优先级。")
    else:
        suggestions.append("额度按当前节奏够用；如需长期稳定，可提前准备备用 Provider 的额度。")
    if label == "fast":
        suggestions.append("消耗速度较快：可检查是否有高频自动化或重试任务在持续消耗。")
    elif label == "stable":
        suggestions.append("消耗平稳，按现状使用即可。")
    return {
        "available": True,
        "trend": label,
        "daily_rate_pct": round(daily_rate, 2),
        "days_left": round(days_left, 0),
        "remaining_pct": round(last_pct, 1),
        "span_days": round(span_days, 0),
        "note": note,
        "suggestions": suggestions,
    }


_explain_change_cache: dict[str, Any] = {"key": "", "at": 0.0, "text": ""}


async def explain_sub2api_change(history: list[dict[str, Any]]) -> dict[str, Any]:
    """对比最近两次快照，用 LLM 生成一句话变化解释；10 分钟缓存防重复调用。"""
    if len(history) < 2:
        return {"available": False, "explanation": "历史快照不足，暂时无法解释变化。", "cache": False}
    latest = history[0]
    previous = history[1]
    changes = []
    for field, label in (
        ("weekly_usage", "每周用量"),
        ("monthly_usage", "每月用量"),
        ("remaining", "剩余天数"),
        ("balance", "余额"),
    ):
        old_value = previous.get(field, "")
        new_value = latest.get(field, "")
        if old_value != new_value:
            changes.append(f"{label}：{old_value or '未知'} → {new_value or '未知'}")
    if not changes:
        return {"available": True, "explanation": "最近两次快照各项数值没有变化。", "cache": True}
    cache_key = f"{latest.get('checked_at')}|{latest.get('weekly_usage')}|{latest.get('monthly_usage')}"
    if _explain_change_cache["key"] == cache_key and time.time() - _explain_change_cache["at"] < 600:
        return {"available": True, "explanation": _explain_change_cache["text"], "cache": True}
    changes_text = "；".join(changes)
    try:
        answer = await call_llm(
            [
                {"role": "system", "content": "你是 Sub2API 用量分析师。用一句话（不超过 60 字）解释用户 API 账户快照变化，说明可能原因（如业务增长、自动化任务、额度重置等），不确定就说明是推测。"},
                {"role": "user", "content": f"最近两次快照变化：{changes_text}。请给出通俗解释。"},
            ],
            max_tokens=200,
            temperature=0.3,
        )
        text = str(answer or "").strip()
        if not text or len(text) < 4:
            text = f"快照变化：{changes_text}。"
    except Exception:  # noqa: BLE001
        text = f"快照变化：{changes_text}。"
    _explain_change_cache.update({"key": cache_key, "at": time.time(), "text": text})
    return {"available": True, "explanation": text, "cache": False, "changes": changes}


def _panel_unwrap(data: Any) -> Any:
    """Strip the panel's standard {"code":0,"message":"success","data":{...}} wrapper."""
    if isinstance(data, dict) and isinstance(data.get("data"), dict):
        return data["data"]
    return data


def _panel_money(value: Any) -> str:
    try:
        return f"${float(value or 0):.2f}"
    except (TypeError, ValueError):
        return str(value or "")


def _panel_tokens(value: Any) -> str:
    try:
        number = float(value or 0)
    except (TypeError, ValueError):
        return str(value or "")
    if number >= 1_000_000:
        return f"{number / 1_000_000:.1f}M"
    if number >= 1_000:
        return f"{number / 1_000:.1f}K"
    return str(int(number))


def _panel_remaining_days(expires_at: Any) -> str:
    try:
        parsed = _sub2api_timestamp(str(expires_at))
        if parsed:
            days = (parsed - datetime.now(timezone.utc)).days
            return f"{days} 天" if days >= 0 else "已到期"
    except Exception:
        pass
    return ""


def _panel_usage_aggregate(usage: Any) -> tuple[dict[str, Any], dict[str, Any]]:
    """Aggregate the panel's per-request usage rows into today / total.

    /usage returns {"code":0,"data":{"items":[{model, input_tokens,
    output_tokens, total_cost, actual_cost, created_at, ...}]}}; every row is
    one request. "Today" is matched against the Beijing calendar day because
    the panel timestamps are in +08:00.
    """
    data = _panel_unwrap(usage)
    rows = data.get("items") if isinstance(data, dict) else None
    if not isinstance(rows, list):
        return {}, {}
    try:
        import zoneinfo
        today_marker = datetime.now(zoneinfo.ZoneInfo("Asia/Shanghai")).strftime("%Y-%m-%d")
    except Exception:
        today_marker = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    today = {"requests": 0, "cost": 0.0, "tokens": 0}
    total = {"requests": len(rows), "cost": 0.0, "tokens": 0}
    for row in rows:
        if not isinstance(row, dict):
            continue
        try:
            cost = float(row.get("total_cost") or row.get("actual_cost") or 0)
        except (TypeError, ValueError):
            cost = 0.0
        try:
            tokens = int(row.get("input_tokens") or 0) + int(row.get("output_tokens") or 0)
        except (TypeError, ValueError):
            tokens = 0
        total["cost"] += cost
        total["tokens"] += tokens
        if str(row.get("created_at") or "")[:10] == today_marker:
            today["requests"] += 1
            today["cost"] += cost
            today["tokens"] += tokens
    return (
        {"requests": today["requests"], "cost": _panel_money(today["cost"]), "tokens": _panel_tokens(today["tokens"])},
        {"requests": total["requests"], "cost": _panel_money(total["cost"]), "tokens": _panel_tokens(total["tokens"])},
    )


def _panel_keys_list(keys: Any) -> list[dict[str, Any]]:
    """Normalize panel key rows (data.items) into the snapshot keys shape."""
    data = _panel_unwrap(keys)
    rows = data.get("items") if isinstance(data, dict) else None
    if not isinstance(rows, list):
        rows = data if isinstance(data, list) else []
    normalized: list[dict[str, Any]] = []
    for row in rows[:100]:
        if not isinstance(row, dict):
            continue
        normalized.append(
            {
                "name": str(row.get("name") or ""),
                "masked": _sub2api_key_value(row.get("key") or row.get("masked") or row.get("sk") or row.get("api_key")),
                "group": str(row.get("group") or row.get("group_name") or ""),
                "concurrency": str(row.get("current_concurrency") or row.get("concurrency") or ""),
                "today_cost": str(row.get("today_cost") or ""),
                "month_cost": str(row.get("month_cost") or ""),
                "expires": str(row.get("expires_at") or row.get("expires") or ""),
                "status": str(row.get("status") or ""),
            }
        )
    return normalized


def sub2api_cost_breakdown(snapshot: dict[str, Any]) -> dict[str, Any]:
    """Aggregate numeric costs by the panel's already-sanitized group label."""
    groups: dict[str, dict[str, Any]] = {}
    unpriced_count = 0
    keys = snapshot.get("keys") if isinstance(snapshot.get("keys"), list) else []
    for raw_key in keys[:100]:
        if not isinstance(raw_key, dict):
            continue
        label = _sub2api_text(raw_key.get("group"), 80) or "未分组"
        entry = groups.setdefault(label, {"group": label, "key_count": 0, "today": 0.0, "month": 0.0, "today_count": 0, "month_count": 0})
        entry["key_count"] += 1
        today = _sub2api_number(raw_key.get("today_cost"))
        month = _sub2api_number(raw_key.get("month_cost"))
        if today is None:
            unpriced_count += 1
        else:
            entry["today"] += today
            entry["today_count"] += 1
        if month is not None:
            entry["month"] += month
            entry["month_count"] += 1
    rows = [
        {
            "group": entry["group"],
            "key_count": entry["key_count"],
            "today_cost": round(entry["today"], 6) if entry["today_count"] else None,
            "month_cost": round(entry["month"], 6) if entry["month_count"] else None,
            "priced_today": entry["today_count"],
            "priced_month": entry["month_count"],
        }
        for entry in groups.values()
    ]
    rows.sort(key=lambda item: (item["month_cost"] if item["month_cost"] is not None else -1, item["group"]), reverse=True)
    return {
        "available": bool(rows),
        "groups": rows,
        "totals": {
            "today_cost": round(sum(item["today_cost"] or 0 for item in rows), 6) if any(item["today_cost"] is not None for item in rows) else None,
            "month_cost": round(sum(item["month_cost"] or 0 for item in rows), 6) if any(item["month_cost"] is not None for item in rows) else None,
            "key_count": sum(item["key_count"] for item in rows),
        },
        "unpriced_count": unpriced_count,
        "policy": "只按已脱敏快照中的 Provider/分组和成本字段聚合；缺失成本不按 0 处理，不保存完整 Key。",
    }


def parse_sub2api_panel_raw(raw: dict[str, Any]) -> dict[str, Any]:
    """Turn the Sub2API panel API payloads into the standard snapshot shape.

    Panel responses are wrapped as {"code":0,"message":"success","data":{...}}.
    Endpoints consumed by the server-side sync:
      /auth/me                → user (balance, email)
      /subscriptions/summary  → data.subscriptions[0] (weekly/monthly usage)
      /keys                   → data.items (API keys, masked on save)
      /usage                  → data.items (per-request rows, aggregated)
    """
    me = _panel_unwrap(raw.get("me"))
    if not isinstance(me, dict):
        me = {}
    subs = _panel_unwrap(raw.get("subscriptions") or raw.get("summary") or raw.get("active"))
    sub_list = subs.get("subscriptions") if isinstance(subs, dict) and isinstance(subs.get("subscriptions"), list) else []
    sub = sub_list[0] if sub_list else (subs if isinstance(subs, dict) and "group_name" in subs else {})

    today, total = _panel_usage_aggregate(raw.get("usage"))
    keys = _panel_keys_list(raw.get("keys"))

    subscription: dict[str, Any] = {}
    if sub:
        expires_raw = str(sub.get("expires_at") or "")
        subscription = {
            "name": str(sub.get("group_name") or sub.get("name") or ""),
            "provider": str(sub.get("provider") or ""),
            "status": str(sub.get("status") or ""),
            "expires_at": expires_raw[:16].replace("T", " ") if expires_raw else "",
            "remaining": _panel_remaining_days(expires_raw),
            "weekly_usage": f"{_panel_money(sub.get('weekly_used_usd'))} / {_panel_money(sub.get('weekly_limit_usd'))}",
            "weekly_reset": "",
            "monthly_usage": f"{_panel_money(sub.get('monthly_used_usd'))} / {_panel_money(sub.get('monthly_limit_usd'))}",
            "monthly_reset": "",
        }

    balance = me.get("balance") if "balance" in me else ""
    snapshot: dict[str, Any] = {
        "logged_in": True,
        "checked_at": now_iso(),
        "balance": _panel_money(balance) if isinstance(balance, (int, float)) else str(balance or ""),
        "api_keys": {"total": len(keys), "active": sum(1 for key in keys if str(key.get("status")) == "active")},
        "today": today,
        "total": total,
        "subscription": subscription,
        "keys": keys,
    }
    for key in ("source_url", "dashboard_url", "subscription_url"):
        if raw.get(key):
            snapshot[key] = str(raw.get(key))[:500]
    return snapshot

SUB2API_PANEL_SETTINGS_FILE = DATA_DIR / "sub2api_panel_settings.json"


def load_sub2api_panel_settings() -> dict[str, Any]:
    try:
        values = json.loads(SUB2API_PANEL_SETTINGS_FILE.read_text(encoding="utf-8"))
        return values if isinstance(values, dict) else {}
    except (OSError, json.JSONDecodeError):
        return {}


def save_sub2api_panel_settings(values: dict[str, Any]) -> None:
    save_json_atomic(SUB2API_PANEL_SETTINGS_FILE, values, 0o600)


def sub2api_sync_state() -> dict[str, Any]:
    """Expose a safe, actionable sync status without returning credentials."""
    settings = load_sub2api_panel_settings()
    has_refresh_token = bool(str(settings.get("refresh_token") or "").strip())
    raw = settings.get("sync_state") if isinstance(settings.get("sync_state"), dict) else {}
    if not raw:
        return {
            "status": "connected" if has_refresh_token or settings.get("access_token") else "not_configured",
            "label": "已连接，等待同步" if has_refresh_token else "已登录，需浏览器同步" if settings.get("access_token") else "尚未连接面板",
            "last_attempt_at": "",
            "last_success_at": "",
            "last_error": "",
            "next_action": "点击立即同步一次" if has_refresh_token else "面板未提供可续期凭证，请使用浏览器书签同步或重新登录" if settings.get("access_token") else "登录并连接面板",
        }
    status = str(raw.get("status") or "unknown")
    credential_invalid = bool(raw.get("credential_invalid")) or (
        status == "failed" and any(marker in str(raw.get("last_error") or "") for marker in ("凭证", "token", "登录", "401", "403"))
    )
    labels = {"succeeded": "最近同步成功", "failed": "最近同步失败", "connected": "已连接，等待同步", "not_configured": "尚未连接面板"}
    if credential_invalid:
        labels["failed"] = "面板凭证已失效"
    if status == "connected" and not has_refresh_token and settings.get("access_token"):
        labels["connected"] = "已登录，需浏览器同步"
    if status == "succeeded" and not has_refresh_token:
        labels["succeeded"] = "最近同步成功（需浏览器续传）"
    return {
        "status": status,
        "label": labels.get(status, "同步状态未知"),
        "credential_invalid": credential_invalid,
        "last_attempt_at": str(raw.get("last_attempt_at") or ""),
        "last_success_at": str(raw.get("last_success_at") or ""),
        "last_error": clip(str(raw.get("last_error") or ""), 500),
        "source": str(raw.get("source") or ""),
        "next_action": str(raw.get("next_action") or "点击立即同步一次"),
    }


def update_sub2api_sync_state(status: str, *, source: str = "", error: str = "") -> dict[str, Any]:
    """Persist only operational sync metadata; access/refresh tokens stay untouched."""
    settings = load_sub2api_panel_settings()
    previous = settings.get("sync_state") if isinstance(settings.get("sync_state"), dict) else {}
    timestamp = now_iso()
    error_text = clip(str(error or ""), 500)
    has_refresh_token = bool(str(settings.get("refresh_token") or "").strip())
    credential_invalid = status == "failed" and any(marker in error_text for marker in ("凭证", "token", "登录", "401", "403"))
    if status == "failed":
        if any(marker in error_text for marker in ("凭证", "token", "登录", "401", "403")):
            next_action = "回到上方重新登录并连接面板"
        else:
            next_action = "点击立即同步一次重试；仍失败时重新登录"
    elif status == "succeeded":
        next_action = "服务器会继续按约 30 分钟周期自动同步" if has_refresh_token else "可继续浏览器同步；需要自动同步请重新登录并确认面板提供续期凭证"
    elif status == "connected":
        next_action = "点击立即同步一次" if has_refresh_token else "面板未提供可续期凭证，请使用浏览器书签同步或重新登录"
    elif status == "not_configured":
        next_action = "登录并连接面板"
    else:
        next_action = "点击立即同步一次"
    state = {
        "status": status,
        "last_attempt_at": timestamp,
        "last_success_at": timestamp if status == "succeeded" else str(previous.get("last_success_at") or ""),
        "last_error": error_text,
        "credential_invalid": credential_invalid,
        "source": clip(source, 80),
        "next_action": next_action,
    }
    settings["sync_state"] = state
    try:
        save_sub2api_panel_settings(settings)
    except Exception:
        # Sync status is helpful diagnostics, never a reason to fail a valid snapshot.
        pass
    return sub2api_sync_state()


def sub2api_panel_base_url() -> str:
    return os.getenv("SUB2API_PANEL_BASE_URL", "https://sub.chengsir.asia").strip().rstrip("/")

async def panel_refresh_access_token(force_refresh: bool = False) -> str:
    """Return a valid access token for the panel, refreshing it when needed.

    Uses the panel's refresh_token (obtained once at login) to mint a fresh
    access_token via POST /api/v1/auth/refresh; tokens are stored locally so
    the server can keep syncing automatically.
    """
    settings = load_sub2api_panel_settings()
    refresh_token = str(settings.get("refresh_token") or "").strip()
    if not refresh_token:
        raise RuntimeError("未配置面板登录凭证（refresh_token）")
    access = str(settings.get("access_token") or "").strip()
    if access and not force_refresh:
        return access
    base = sub2api_panel_base_url().rstrip("/") + "/api/v1"
    try:
        async with httpx.AsyncClient(timeout=20, trust_env=True) as client:
            response = await client.post(base + "/auth/refresh", json={"refresh_token": refresh_token})
    except httpx.HTTPError as exc:
        raise RuntimeError(f"面板登录凭证刷新失败：{type(exc).__name__}：{str(exc)[:120]}") from exc
    try:
        body = response.json()
    except Exception:
        body = {}
    data = body.get("data") if isinstance(body.get("data"), dict) else body
    new_access = str(data.get("access_token") or data.get("token") or "").strip()
    new_refresh = str(data.get("refresh_token") or "").strip() or refresh_token
    if response.status_code not in (200, 201) or not new_access:
        raise RuntimeError("面板登录凭证已失效，请在 Sub2API 页面重新登录并连接")
    settings["access_token"] = new_access
    settings["refresh_token"] = new_refresh
    save_sub2api_panel_settings(settings)
    return new_access


async def fetch_sub2api_panel_admin() -> dict[str, Any]:
    """Fetch the panel server-side using the saved login token (no browser needed).

    User endpoints come first (a normal account can read them); admin-only
    endpoints are tried last and their 403s never block a successful sync.
    """
    try:
        access = await panel_refresh_access_token()
    except RuntimeError:
        raise
    base = sub2api_panel_base_url().rstrip("/") + "/api/v1"
    headers = {
        "Authorization": f"Bearer {access}",
        "X-Admin-UI-Request": "true",
        "Accept": "application/json",
    }
    endpoints = [
        "/auth/me",
        "/subscriptions/summary",
        "/subscriptions/active",
        "/keys",
        "/usage",
        "/admin/dashboard/stats",
        "/admin/dashboard/snapshot-v2",
        "/admin/usage/stats",
    ]
    results: dict[str, Any] = {}
    payload: dict[str, Any] = {}
    denied_any = False
    async with httpx.AsyncClient(timeout=20, trust_env=True) as client:
        for attempt in (0, 1):
            for path in endpoints:
                try:
                    response = await client.get(base + path, headers=headers)
                    body_text = response.text[:400]
                    is_denied = response.status_code in (401, 403) or "INVALID_TOKEN" in body_text or "UNAUTHORIZED" in body_text.upper()
                    if is_denied:
                        results[path] = {"status": "denied", "detail": f"HTTP {response.status_code}"}
                        denied_any = True
                        continue
                    if response.status_code == 200 and response.headers.get("content-type", "").startswith("application/json"):
                        try:
                            data = response.json()
                        except Exception:
                            data = None
                        if isinstance(data, dict):
                            payload.setdefault(path.split("/")[-1], data)
                            results[path] = {"status": "ok", "detail": f"{len(data)} 字段"}
                        else:
                            results[path] = {"status": "skip", "detail": "响应非 JSON 对象"}
                    elif response.status_code == 404:
                        results[path] = {"status": "skip", "detail": "端点不存在"}
                    else:
                        results[path] = {"status": "skip", "detail": f"HTTP {response.status_code}"}
                except httpx.HTTPError as exc:
                    results[path] = {"status": "error", "detail": f"{type(exc).__name__}: {str(exc)[:120]}"}
            if not denied_any or attempt == 1:
                break
            try:
                access = await panel_refresh_access_token(force_refresh=True)
                headers["Authorization"] = f"Bearer {access}"
                denied_any = False
            except RuntimeError:
                break
    if not any(item.get("status") == "ok" for item in results.values()):
        denied = [path for path, info in results.items() if info.get("status") == "denied"]
        detail = "登录凭证被面板拒绝" if denied else "；".join(f"{path}={info.get('status')}" for path, info in results.items())
        raise RuntimeError(f"面板接口未返回有效数据（{detail}）")
    payload["source_url"] = f"{sub2api_panel_base_url()}/keys"
    payload["dashboard_url"] = f"{sub2api_panel_base_url()}/dashboard"
    payload["subscription_url"] = f"{sub2api_panel_base_url()}/subscriptions"
    return {"payload": payload, "endpoints": results}


async def auto_sync_sub2api_panel() -> dict[str, Any]:
    """Server-side automatic sync: fetch panel with the saved token and store."""
    try:
        fetched = await fetch_sub2api_panel_admin()
        snapshot, analysis, artifact = record_sub2api_snapshot(
            parse_sub2api_panel_raw(fetched["payload"]), source="panel_admin_auto"
        )
        return {"ok": True, "snapshot": snapshot, "analysis": analysis, "artifact": artifact, "endpoints": fetched["endpoints"], "sync_state": sub2api_sync_state()}
    except Exception as exc:
        state = update_sub2api_sync_state("failed", source="panel_admin_auto", error=str(exc))
        try:
            previous = load_sub2api_snapshot()
            previous.update({"error": str(exc)[:500], "last_sync_error_at": state.get("last_attempt_at", now_iso())})
            save_sub2api_snapshot(previous)
        except Exception:
            pass
        raise


async def sub2api_auto_sync_loop() -> None:
    """Periodically sync the panel while the process is alive (best effort).

    When no panel credential is saved yet, the loop idles instead of failing;
    on failure the existing healthy snapshot is preserved (only a separate
    ``error`` field is recorded) so a transient error never marks good data
    as stale/error.
    """
    interval = float(os.getenv("SUB2API_AUTO_SYNC_INTERVAL", "1800"))  # seconds, default 30 min
    if interval <= 0:
        return
    while True:
        lease = worker_lease("sync-worker", status="running", metadata={"loop": "sub2api_auto_sync"})
        if lease.get("status") == "held_by_other_instance":
            await asyncio.sleep(min(interval, 60))
            continue
        settings = load_sub2api_panel_settings()
        sync_state = sub2api_sync_state()
        if settings.get("refresh_token") and not sync_state.get("credential_invalid"):
            try:
                await auto_sync_sub2api_panel()
            except Exception as exc:
                try:
                    previous = load_sub2api_snapshot()
                    previous.update({"error": str(exc)[:500], "last_sync_error_at": now_iso()})
                    save_sub2api_snapshot(previous)
                except Exception:
                    pass
        await asyncio.sleep(interval)




def record_sub2api_snapshot(values: dict[str, Any], source: str = "browser_session", client_snapshot_id: str = "") -> tuple[dict[str, Any], dict[str, Any], dict[str, Any] | None]:
    snapshot = sanitize_sub2api_snapshot(values)
    snapshot["source"] = _sub2api_text(source, 80) or "browser_session"
    client_snapshot_id = sanitize_sub2api_client_snapshot_id(client_snapshot_id or snapshot.get("client_snapshot_id"))
    if client_snapshot_id:
        snapshot["client_snapshot_id"] = client_snapshot_id
    snapshot.setdefault("checked_at", now_iso())
    snapshot["synced_at"] = now_iso()
    analysis = analyze_sub2api_snapshot(snapshot)
    connection = db_connection()
    try:
        if client_snapshot_id:
            rows = connection.execute("SELECT snapshot_json FROM sub2api_snapshots ORDER BY id DESC LIMIT 100").fetchall()
            for row in rows:
                try:
                    previous = json.loads(row["snapshot_json"] or "{}")
                except (TypeError, json.JSONDecodeError):
                    previous = {}
                if sanitize_sub2api_client_snapshot_id(previous.get("client_snapshot_id")) == client_snapshot_id:
                    existing = sanitize_sub2api_snapshot(previous)
                    existing["_deduplicated"] = True
                    return existing, analyze_sub2api_snapshot(existing), None
        save_sub2api_snapshot(snapshot)
        update_sub2api_sync_state("succeeded", source=source)
        cursor = connection.execute(
            "INSERT INTO sub2api_snapshots (checked_at, status, snapshot_json, created_at) VALUES (?, ?, ?, ?)",
            (snapshot.get("checked_at", ""), analysis["status"], json.dumps(snapshot, ensure_ascii=False), now_iso()),
        )
        connection.commit()
        history_id = cursor.lastrowid
    finally:
        connection.close()
    artifact = register_artifact_safely(
        project_id="sub2api",
        name="sub2api_snapshot.json",
        path=str(SUB2API_SNAPSHOT_FILE),
        kind="sub2api_snapshot",
        metadata={"history_id": history_id, "checked_at": snapshot.get("checked_at"), "status": analysis["status"], "source": snapshot.get("source")},
    )
    return snapshot, analysis, artifact


def list_sub2api_history(limit: int = 30) -> list[dict[str, Any]]:
    connection = db_connection()
    try:
        rows = connection.execute("SELECT * FROM sub2api_snapshots ORDER BY id DESC LIMIT ?", (max(1, min(limit, 100)),)).fetchall()
    finally:
        connection.close()
    history = []
    for row in rows:
        try:
            snapshot = json.loads(row["snapshot_json"] or "{}")
        except json.JSONDecodeError:
            snapshot = {}
        analysis = analyze_sub2api_snapshot(snapshot)
        subscription = snapshot.get("subscription") or {}
        history.append({"id": row["id"], "checked_at": row["checked_at"], "created_at": row["created_at"], "status": row["status"], "weekly_usage": subscription.get("weekly_usage", ""), "monthly_usage": subscription.get("monthly_usage", ""), "remaining": subscription.get("remaining", ""), "expires_at": subscription.get("expires_at", ""), "weekly_remaining_pct": analysis["weekly"].get("remaining_pct"), "monthly_remaining_pct": analysis["monthly"].get("remaining_pct"), "remaining_days": analysis.get("remaining_days")})
    return history


def evaluate_sub2api_alerts(snapshot: dict[str, Any] | None = None, create_records: bool = False) -> dict[str, Any]:
    snapshot = snapshot or load_sub2api_snapshot()
    analysis = analyze_sub2api_snapshot(snapshot)
    created: list[dict[str, Any]] = []
    existing_items = list_work_items("all", "inbox") if create_records else []
    latest_artifact = list_artifacts("sub2api")[0] if list_artifacts("sub2api") else None
    # 恢复闭环：账户恢复正常后，仍挂着的旧告警自动标 done（不重复打扰）
    active_keys = {f"sub2api:{alert['key']}" for alert in analysis["alerts"]}
    restored: list[dict[str, Any]] = []
    for item in list_work_items("all", "sub2api"):
        metadata = item.get("metadata") if isinstance(item.get("metadata"), dict) else {}
        alert_key = str(metadata.get("alert_key") or "")
        if alert_key.startswith("sub2api:") and item.get("status") in {"open", "running", "blocked"} and alert_key not in active_keys:
            update_work_item_record(item["id"], {"status": "done", "resolved_at": now_iso(), "resolved_by": "sub2api_health_recovery"})
            restored.append({"alert_key": alert_key, "work_item_id": item["id"]})
    for alert in analysis["alerts"]:
        alert_key = f"sub2api:{alert['key']}"
        existing = next((item for item in existing_items if item.get("metadata", {}).get("alert_key") == alert_key and item.get("status") in {"open", "running", "blocked"}), None)
        if existing:
            created.append({"alert": alert, "work_item": existing, "created": False})
            continue
        if not create_records:
            created.append({"alert": alert, "created": False})
            continue
        priority = "urgent" if alert["level"] == "error" else "high"
        item = create_work_item_record(
            title=alert["title"],
            description=f"{alert['message']} 数据时间：{analysis['freshness'].get('checked_at') or '未知'}。",
            kind="alert",
            priority=priority,
            source_project="sub2api",
            target_project="inbox",
            metadata={"alert_key": alert_key, "notification_project": "sub2api", "checked_at": analysis["freshness"].get("checked_at", ""), "source": "sub2api_agent"},
        )
        relation = None
        if latest_artifact:
            relation = create_relation_record(from_type="artifact", from_id=str(latest_artifact["id"]), to_type="work_item", to_id=str(item["id"]), relation_type="alert_from_snapshot", metadata={"alert_key": alert_key})
        existing_items.append(item)
        created.append({"alert": alert, "work_item": item, "relation": relation, "created": True})
    return {"analysis": analysis, "alerts": analysis["alerts"], "created": created, "restored": restored}


def load_json_file(path: Path, fallback: Any) -> Any:
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return fallback


def load_market_watchlist() -> list[dict[str, str]]:
    values = load_json_file(MARKET_WATCHLIST_FILE, [])
    if not isinstance(values, list):
        return []
    return [item for item in values if isinstance(item, dict) and item.get("symbol")]


# Historical sampling is deliberately opt-in and bounded to a small, known
# set of intervals.  It reuses the existing market_refresh automation handler
# so the API-owned scheduler and the external sync worker share one execution
# path, while the source marker keeps this rule distinguishable from any
# manually-created market refresh rule.
MARKET_SAMPLING_INTERVALS: dict[int, str] = {
    300: "每 5 分钟",
    1800: "每 30 分钟",
    3600: "每 1 小时",
    86400: "每天",
}
MARKET_SAMPLING_SOURCE = "market_sampling"
MARKET_SAMPLING_RULE_NAME = "量化历史样本采集"


def market_sampling_rule() -> dict[str, Any] | None:
    """Return the one rule owned by the explicit market sampling control."""
    candidates = []
    for rule in automation_rules():
        config = rule.get("config") if isinstance(rule.get("config"), dict) else {}
        if (
            str(rule.get("kind") or "") == "market_refresh"
            and str(rule.get("project_id") or "") == "market"
            and str(config.get("source") or "") == MARKET_SAMPLING_SOURCE
        ):
            candidates.append(rule)
    return max(candidates, key=lambda item: int(item.get("id") or 0), default=None)


def market_history_count() -> int:
    """Read the full persisted sample count without the UI's display limit."""
    connection = db_connection()
    try:
        row = connection.execute("SELECT COUNT(*) AS count FROM market_snapshots").fetchone()
        return int(row["count"] or 0) if row else 0
    finally:
        connection.close()


def load_market_snapshot() -> dict[str, Any]:
    values = load_json_file(MARKET_SNAPSHOT_FILE, {})
    if not isinstance(values, dict):
        values = {}
    # The editable watchlist is the source of truth.  A quote snapshot may be
    # older than the latest edit, so never let removed symbols leak back into
    # today's cards, AI summaries, or portfolio counts.
    watchlist = load_market_watchlist()
    allowed_symbols = {
        normalize_market_symbol(str(item.get("symbol") or ""))
        for item in watchlist
        if isinstance(item, dict)
    }
    allowed_symbols.discard("")
    quotes = [
        item for item in (values.get("quotes") or [])
        if isinstance(item, dict)
        and normalize_market_symbol(str(item.get("symbol") or "")) in allowed_symbols
    ]
    values["watchlist"] = watchlist
    values["quotes"] = quotes
    if not watchlist:
        values.update({"checked_at": "", "status": "empty", "missing_symbols": []})
    return values


def load_server_monitor_snapshot() -> dict[str, Any]:
    values = load_json_file(SERVER_MONITOR_SNAPSHOT_FILE, {})
    return values if isinstance(values, dict) else {}


def load_aihot_snapshot() -> dict[str, Any]:
    values = load_json_file(AIHOT_SNAPSHOT_FILE, {})
    return values if isinstance(values, dict) else {"items": []}


def save_aihot_snapshot(values: dict[str, Any]) -> None:
    save_json_atomic(AIHOT_SNAPSHOT_FILE, values, 0o600)


def parse_aihot_items(html: str) -> list[dict[str, Any]]:
    """Read the public SSR data from aiHot's Next.js page.

    We intentionally consume only the public initialNewsData payload. This
    avoids copying the site's UI and keeps the workbench's wrapper focused on
    filtering, provenance and Agent conversation.
    """
    pattern = r'self\.__next_f\.push\(\[1,"((?:\\.|[^"\\])*)"\]\)'
    chunks = []
    for match in re.finditer(pattern, html):
        try:
            chunks.append(json.loads('"' + match.group(1) + '"'))
        except json.JSONDecodeError:
            continue
    payload = "\n".join(chunks)
    marker = '"initialNewsData":'
    start = payload.find(marker)
    if start < 0:
        return []
    start += len(marker)
    try:
        parsed, _ = json.JSONDecoder().raw_decode(payload[start:].lstrip())
    except json.JSONDecodeError:
        return []
    if not isinstance(parsed, list):
        return []
    items = []
    for raw in parsed:
        if not isinstance(raw, dict) or not raw.get("id"):
            continue
        published_at = str(raw.get("published_at") or "").removeprefix("$D")
        tags = [tag.strip() for tag in str(raw.get("tag") or "").split(",") if tag.strip()]
        items.append(
            {
                "id": str(raw.get("id")),
                "title": raw.get("title_trans") or raw.get("title") or "未命名资讯",
                "description": raw.get("des_trans") or raw.get("des") or "",
                "source": raw.get("sources") or "未知来源",
                "tags": tags,
                "published_at": published_at,
                "link": raw.get("link") or "",
                "importance": int(raw.get("importance") or 0),
                "business_opportunity": raw.get("business_opportunity") or "",
                "layer": raw.get("layer") or "",
                "value": raw.get("value") or "",
                "impact": raw.get("impact") or "",
            }
        )
    return dedupe_aihot_items(items)


def normalized_aihot_title(title: str) -> str:
    """Make translated/source title variants comparable for feed de-duplication."""
    normalized = unicodedata.normalize("NFKC", str(title or "")).lower()
    return re.sub(r"[^0-9a-z\u4e00-\u9fff]+", "", normalized)


def canonical_aihot_link(link: str) -> str:
    value = str(link or "").strip()
    if not value:
        return ""
    parsed = urlparse(value)
    if not parsed.netloc:
        return value.lower().rstrip("/")
    return f"{parsed.netloc.lower()}{parsed.path.rstrip('/').lower()}"


def parse_rss_items(xml_text: str, source_name: str) -> list[dict[str, Any]]:
    """Parse RSS 2.0 / Atom feeds into the same shape as `parse_aihot_items`.

    Uses only the standard library so the workbench has no extra install cost.
    Stories without a title or link are dropped; importance / business_opportunity
    default to 0 / "" so the dedupe pass keeps the richer record when the same
    story shows up on multiple sources.
    """
    from xml.etree import ElementTree as ET
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError:
        return []
    items: list[dict[str, Any]] = []
    hash_inputs: list[str] = []
    for entry in root.iter("item"):
        title = (entry.findtext("title") or "").strip()
        link = (entry.findtext("link") or "").strip()
        desc = (entry.findtext("description") or "").strip()
        pub = (entry.findtext("pubDate") or "").strip()
        if not title or not link:
            continue
        hash_inputs.append(link)
        items.append({
            "id": f"rss:{hashlib.md5(link.encode('utf-8')).hexdigest()[:12]}",
            "title": title,
            "description": _strip_html(desc)[:300],
            "source": source_name,
            "tags": [],
            "published_at": pub,
            "link": link,
            "importance": 0,
            "business_opportunity": "",
            "layer": "",
        })
    if not items:
        ns = {"atom": "http://www.w3.org/2005/Atom"}
        for entry in root.findall("atom:entry", ns):
            title = (entry.findtext("atom:title", default="", namespaces=ns) or "").strip()
            link_el = entry.find("atom:link", ns)
            link = link_el.get("href", "") if link_el is not None else ""
            desc = (entry.findtext("atom:summary", default="", namespaces=ns) or entry.findtext("atom:content", default="", namespaces=ns) or "").strip()
            pub = (entry.findtext("atom:updated", default="", namespaces=ns) or entry.findtext("atom:published", default="", namespaces=ns) or "").strip()
            if not title or not link:
                continue
            items.append({
                "id": f"rss:{hashlib.md5(link.encode('utf-8')).hexdigest()[:12]}",
                "title": title,
                "description": _strip_html(desc)[:300],
                "source": source_name,
                "tags": [],
                "published_at": pub,
                "link": link,
                "importance": 0,
                "business_opportunity": "",
                "layer": "",
            })
    return items


def _strip_html(value: str) -> str:
    from html.parser import HTMLParser as _HTMLParser
    class _Stripper(_HTMLParser):
        def __init__(self):
            super().__init__()
            self._buf: list[str] = []
        def handle_data(self, data):
            self._buf.append(data)
    if not value:
        return ""
    parser = _Stripper()
    try:
        parser.feed(value)
    except Exception:
        return value
    return " ".join("".join(parser._buf).split())


def dedupe_aihot_items(items: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Collapse repeated stories from multiple sources while keeping the best record."""
    result: list[dict[str, Any]] = []
    key_to_index: dict[str, int] = {}
    for item in items:
        keys = []
        link_key = canonical_aihot_link(item.get("link", ""))
        title_key = normalized_aihot_title(item.get("title", ""))
        if link_key:
            keys.append(f"link:{link_key}")
        if title_key:
            keys.append(f"title:{title_key}")
        existing_index = next((key_to_index[key] for key in keys if key in key_to_index), None)
        if existing_index is None:
            existing_index = len(result)
            result.append(item)
        else:
            current = result[existing_index]
            current_score = (
                int(current.get("importance") or 0),
                bool(current.get("business_opportunity")),
                len(str(current.get("description") or "")),
                str(current.get("published_at") or ""),
            )
            item_score = (
                int(item.get("importance") or 0),
                bool(item.get("business_opportunity")),
                len(str(item.get("description") or "")),
                str(item.get("published_at") or ""),
            )
            if item_score > current_score:
                result[existing_index] = item
        for key in keys:
            key_to_index[key] = existing_index
    return result


def list_aihot_feedback(item_ids: list[str] | None = None) -> dict[str, dict[str, Any]]:
    """Read local-only feedback used to personalize the signal list."""
    connection = db_connection()
    try:
        if item_ids:
            normalized = [str(item_id) for item_id in item_ids if str(item_id).strip()]
            if not normalized:
                return {}
            placeholders = ",".join("?" for _ in normalized)
            rows = connection.execute(
                f"SELECT * FROM aihot_feedback WHERE item_id IN ({placeholders})", normalized
            ).fetchall()
        else:
            rows = connection.execute("SELECT * FROM aihot_feedback").fetchall()
        return {
            str(row["item_id"]): {
                "item_id": str(row["item_id"]),
                "vote": row["vote"],
                "note": row["note"],
                "created_at": row["created_at"],
                "updated_at": row["updated_at"],
            }
            for row in rows
        }
    finally:
        connection.close()


def save_aihot_feedback(item_id: str, vote: str, note: str = "") -> dict[str, Any]:
    timestamp = now_iso()
    connection: sqlite3.Connection | None = None
    try:
        connection = db_connection()
        connection.execute(
            """INSERT INTO aihot_feedback (item_id, vote, note, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?)
            ON CONFLICT(item_id) DO UPDATE SET vote = excluded.vote, note = excluded.note, updated_at = excluded.updated_at""",
            (str(item_id), vote, clip(note.strip(), 1_000), timestamp, timestamp),
        )
        connection.commit()
        row = connection.execute("SELECT * FROM aihot_feedback WHERE item_id = ?", (str(item_id),)).fetchone()
        return {
            "item_id": str(row["item_id"]),
            "vote": row["vote"],
            "note": row["note"],
            "created_at": row["created_at"],
            "updated_at": row["updated_at"],
        }
    finally:
        connection.close()


def cid_snapshot_row(row: sqlite3.Row) -> dict[str, Any]:
    snapshot = decode_json_column(row["snapshot_json"])
    return {
        "id": row["id"],
        "repo": row["repo"],
        "source_url": row["source_url"],
        "fetched_at": row["fetched_at"],
        "project_count": row["project_count"],
        "snapshot": snapshot,
        "created_at": row["created_at"],
    }


def refresh_cid_opportunity_status(repo: str, projects: list[dict[str, Any]], fetched_at: str) -> int:
    """登记过的机会卡项目在新快照里状态/描述有变化时，刷新卡片并通知。

    只更新已登记机会（opportunity work_item + artifact），不自动创建新机会。
    返回更新的机会卡数量；没有变化或没有登记时返回 0。
    """
    if not projects:
        return 0
    by_key = {str(item.get("key") or ""): item for item in projects if item.get("key")}
    if not by_key:
        return 0
    updated = 0
    for item in list_work_items("all", "cid-dashboard"):
        meta = item.get("metadata") or {}
        opportunity_key = str(meta.get("opportunity_key") or "")
        if not opportunity_key or not opportunity_key.startswith("cid:"):
            continue
        project_key = str(meta.get("project_key") or "")
        current = by_key.get(project_key)
        if not current:
            continue
        status = str(current.get("status") or "")
        name = str(current.get("name") or "")
        desc = clip(str(current.get("desc") or ""), 1_000)
        signal = meta.get("signal") if isinstance(meta.get("signal"), dict) else {}
        old_status = str(signal.get("status") or meta.get("project_status") or "")
        old_name = str(signal.get("name") or meta.get("project_name") or "")
        if status == old_status and name == old_name:
            continue
        new_signal = {**signal, "status": status, "name": name, "status_changed_from": old_status or "未知", "last_refreshed_at": now_iso()}
        new_meta = {**meta, "signal": new_signal, "project_status": status, "project_name": name, "last_refreshed_at": now_iso(), "status_changed_from": old_status or "未知"}
        update_work_item_record(
            item["id"],
            {
                "description": clip(f"看板项目 {name} 状态更新为 {status or '未知'}（{fetched_at}）。原描述：{desc or '无'}", 1_500),
                "metadata": new_meta,
            },
        )
        try:
            create_notification_record(
                title=f"看板机会更新：{name}",
                body=f"登记过的看板项目状态变化：{old_status or '未知'} → {status or '未知'}（数据时间 {fetched_at}）。",
                project_id="cid-dashboard",
                kind="agent_action",
                level="info",
                href="/projects/cid-dashboard",
                event_key=f"cid-opportunity-update:{item['id']}:{fetched_at}",
                dedupe_seconds=0,
            )
        except Exception:  # noqa: BLE001
            pass
        updated += 1
    return updated


def save_cid_dashboard_snapshot(payload: dict[str, Any]) -> dict[str, Any]:
    """Persist a bounded, non-sensitive snapshot from the CID dashboard."""
    repo = clip(str(payload.get("repo") or ""), 180).strip()
    if not repo or "/" not in repo:
        raise ValueError("看板数据源必须是 owner/repo")
    source_url = clip(str(payload.get("source_url") or ""), 1_000).strip()
    fetched_at = clip(str(payload.get("fetched_at") or now_iso()), 80).strip()
    raw = payload.get("snapshot") if isinstance(payload.get("snapshot"), dict) else {}
    def safe_count(value: Any) -> int:
        try:
            return max(0, min(int(value or 0), 100_000))
        except (TypeError, ValueError):
            return 0

    raw_status_counts = raw.get("status_counts") if isinstance(raw.get("status_counts"), dict) else {}
    raw_top_tags = raw.get("top_tags") if isinstance(raw.get("top_tags"), list) else []
    snapshot = {
        "status_counts": {clip(str(key), 80): safe_count(value) for key, value in list(raw_status_counts.items())[:20]},
        "top_tags": [[clip(str(pair[0]), 80), safe_count(pair[1])] for pair in raw_top_tags[:20] if isinstance(pair, (list, tuple)) and len(pair) >= 2],
        "projects": [],
    }
    projects = raw.get("projects") if isinstance(raw.get("projects"), list) else []
    safe_projects = []
    for project in projects[:160]:
        if not isinstance(project, dict):
            continue
        safe_projects.append(
            {
                "key": clip(str(project.get("key") or ""), 240),
                "name": clip(str(project.get("name") or ""), 240),
                "url": clip(str(project.get("url") or ""), 1_000),
                "desc": clip(str(project.get("desc") or ""), 1_000),
                "dev": clip(str(project.get("dev") or ""), 160),
                "status": clip(str(project.get("status") or ""), 40),
                "tags": [clip(str(tag), 80) for tag in (project.get("tags") or [])[:8]],
                "group": clip(str(project.get("group") or project.get("groupLabel") or ""), 160),
            }
        )
    snapshot["projects"] = safe_projects
    snapshot["project_count"] = max(0, min(int(payload.get("project_count") or len(safe_projects)), 100_000))
    snapshot_json = json.dumps(snapshot, ensure_ascii=False, sort_keys=True)
    connection = db_connection()
    try:
        previous = connection.execute(
            "SELECT * FROM cid_dashboard_snapshots WHERE repo = ? ORDER BY id DESC LIMIT 1", (repo,)
        ).fetchone()
        if previous:
            previous_snapshot = decode_json_column(previous["snapshot_json"])
            previous_snapshot.pop("saved_at", None)
            if previous["source_url"] == source_url and previous_snapshot == snapshot:
                return cid_snapshot_row(previous)
        cursor = connection.execute(
            """INSERT INTO cid_dashboard_snapshots
            (repo, source_url, fetched_at, project_count, snapshot_json, created_at)
            VALUES (?, ?, ?, ?, ?, ?)""",
            (repo, source_url, fetched_at, snapshot["project_count"], snapshot_json, now_iso()),
        )
        connection.commit()
        row = connection.execute("SELECT * FROM cid_dashboard_snapshots WHERE id = ?", (cursor.lastrowid,)).fetchone()
        saved = cid_snapshot_row(row)
    finally:
        connection.close()

    # 机会卡状态自动刷新：已登记的机会项目在新快照里状态/描述有变化时，
    # 更新机会卡描述并登记一条通知，让登记过的机会保持最新。
    try:
        refresh_cid_opportunity_status(repo, safe_projects, fetched_at)
    except Exception:  # noqa: BLE001
        pass
    return saved


def list_cid_dashboard_snapshots(repo: str = "", limit: int = 20) -> list[dict[str, Any]]:
    connection = db_connection()
    try:
        if repo:
            rows = connection.execute(
                "SELECT * FROM cid_dashboard_snapshots WHERE repo = ? ORDER BY created_at DESC LIMIT ?",
                (repo, max(1, min(limit, 50))),
            ).fetchall()
        else:
            rows = connection.execute(
                "SELECT * FROM cid_dashboard_snapshots ORDER BY created_at DESC LIMIT ?",
                (max(1, min(limit, 50)),),
            ).fetchall()
        return [cid_snapshot_row(row) for row in rows]
    finally:
        connection.close()


def cid_opportunity_for_project(opportunity_key: str) -> dict[str, Any] | None:
    for work_item in list_work_items("all", "cid-dashboard"):
        metadata = work_item.get("metadata") if isinstance(work_item.get("metadata"), dict) else {}
        if metadata.get("opportunity_key") == opportunity_key:
            return work_item
    return None


def aihot_opportunity_for_item(item_id: str) -> dict[str, Any] | None:
    key = f"aihot:{str(item_id)}"
    for work_item in list_work_items("all", "aihot"):
        metadata = work_item.get("metadata") if isinstance(work_item.get("metadata"), dict) else {}
        if metadata.get("opportunity_key") == key:
            return work_item
    return None


def enrich_aihot_items(items: list[dict[str, Any]]) -> list[dict[str, Any]]:
    feedback = list_aihot_feedback([str(item.get("id")) for item in items])
    opportunities = {
        str(item.get("metadata", {}).get("opportunity_key")): item
        for item in list_work_items("all", "aihot")
        if isinstance(item.get("metadata"), dict) and item.get("metadata", {}).get("opportunity_key")
    }
    enriched = []
    for raw_item in items:
        item = dict(raw_item)
        item_feedback = feedback.get(str(item.get("id")))
        opportunity = opportunities.get(f"aihot:{item.get('id')}")
        item["feedback"] = item_feedback or {"item_id": str(item.get("id")), "vote": "", "note": ""}
        item["opportunity_work_item_id"] = opportunity.get("id") if opportunity else None
        item["opportunity_status"] = opportunity.get("status") if opportunity else ""
        item["opportunity_score"] = opportunity_score(item, item["feedback"])
        enriched.append(item)
    return enriched


async def fetch_aihot_snapshot(*, force: bool = False) -> dict[str, Any]:
    current = load_aihot_snapshot()
    fetched_at = current.get("fetched_at")
    fresh = False
    if fetched_at and not force:
        try:
            fresh = (datetime.now(timezone.utc) - datetime.fromisoformat(fetched_at)).total_seconds() < 300
        except ValueError:
            fresh = False
    if fresh and current.get("items"):
        return current
    async def fetch_one(client: httpx.AsyncClient, url: str) -> tuple[str, list[dict[str, Any]]]:
        try:
            response = await client.get(url, headers={"User-Agent": "Workbench/0.2"})
            response.raise_for_status()
            body = response.text
        except Exception as exc:
            return (url, [{"_error": str(exc)}])
        if "aihot.today" in url:
            return (url, parse_aihot_items(body))
        return (url, parse_rss_items(body, _hostname(url)))
    try:
        async with httpx.AsyncClient(timeout=20, trust_env=False, headers={"User-Agent": "Workbench/0.2"}) as client:
            results = await asyncio.gather(*(fetch_one(client, url) for url in AIHOT_SOURCES), return_exceptions=False)
        items: list[dict[str, Any]] = []
        errors: list[str] = []
        for _url, batch in results:
            for entry in batch:
                if "_error" in entry:
                    errors.append(str(entry["_error"]))
                elif _aihot_relevant(entry):
                    items.append(entry)
        if not items:
            raise RuntimeError(f"AI 热点多源均未读到数据 ({'; '.join(errors)[:200]})")
        snapshot = {
            "source": " + ".join(_hostname(url) for url in AIHOT_SOURCES),
            "source_url": AIHOT_SOURCES[0],
            "sources": list(AIHOT_SOURCES),
            "fetched_at": now_iso(),
            "items": items,
            "previous_items": [
                {"id": item.get("id"), "title": item.get("title"), "link": item.get("link"), "published_at": item.get("published_at")}
                for item in dedupe_aihot_items(list(current.get("items") or []))[:200]
                if isinstance(item, dict)
            ],
            "stale": False,
            "error": " | ".join(errors)[:500] if errors else "",
        }
        save_aihot_snapshot(snapshot)
        register_artifact_safely(
            project_id="aihot",
            name="aihot_snapshot.json",
            path=str(AIHOT_SNAPSHOT_FILE),
            kind="aihot_feed",
            metadata={"item_count": len(items), "source_count": len(AIHOT_SOURCES)},
        )
        return snapshot
    except Exception as exc:
        if current.get("items"):
            current["stale"] = True
            current["error"] = str(exc)
            return current
        raise HTTPException(502, f"AI 热点同步失败：{exc}") from exc


def _hostname(url: str) -> str:
    from urllib.parse import urlparse as _urlparse
    try:
        return _urlparse(url).netloc or url
    except ValueError:
        return url


def select_aihot_items(snapshot: dict[str, Any], mode: str = "useful", query: str = "", limit: int = 40) -> list[dict[str, Any]]:
    items = dedupe_aihot_items(list(snapshot.get("items") or []))
    query = query.strip().lower()
    if query:
        items = [item for item in items if query in json.dumps(item, ensure_ascii=False).lower()]
    feedback = list_aihot_feedback([str(item.get("id")) for item in items])
    # 变化检测：对比上一次快照（previous_items），标记新出现的热点
    previous = snapshot.get("previous_items") or []
    previous_ids = {str(item.get("id")) for item in previous if isinstance(item, dict)}
    previous_titles = {normalized_aihot_title(str(item.get("title") or "")) for item in previous if isinstance(item, dict)}

    def change_label(item: dict[str, Any]) -> str:
        if str(item.get("id") or "") in previous_ids:
            return ""
        return "" if normalized_aihot_title(str(item.get("title") or "")) in previous_titles else "new"

    # 来源质量评分：基于该来源下所有条目的用户反馈。
    # 细化：同时统计有用/不相关样本量，按“有用率 + 样本量”加权，
    # 有足够样本的来源分数更可信，样本少时向基准 3 分收缩。
    source_votes: dict[str, int] = {}
    source_used: dict[str, int] = {}
    source_total: dict[str, int] = {}
    for item in items:
        src = str(item.get("source") or "未知来源")
        vote = str(feedback.get(str(item.get("id")), {}).get("vote", ""))
        if vote == "useful":
            source_votes[src] = source_votes.get(src, 0) + 1
            source_used[src] = source_used.get(src, 0) + 1
            source_total[src] = source_total.get(src, 0) + 1
        elif vote == "not_useful":
            source_votes[src] = source_votes.get(src, 0) - 1
            source_total[src] = source_total.get(src, 0) + 1
    for index, raw_item in enumerate(items):
        updated = dict(raw_item)
        updated["change"] = change_label(updated)
        src = str(updated.get("source") or "未知来源")
        votes = source_votes.get(src, 0)
        total = source_total.get(src, 0)
        # 有用率加权：样本越多，越向“有用率”靠；样本少时回到基准 3 分。
        if total >= 5:
            usefulness = source_used.get(src, 0) / total
            score = 1 + usefulness * 4
        elif total >= 2:
            usefulness = source_used.get(src, 0) / total
            score = 3 + (usefulness - 0.5) * 2
        else:
            score = 3 + votes
        updated["source_score"] = max(0, min(5, round(score, 2)))
        updated["source_votes"] = votes
        updated["source_sample_size"] = total
        items[index] = updated

    def preference_score(item: dict[str, Any]) -> int:
        vote = str(feedback.get(str(item.get("id")), {}).get("vote", ""))
        return 5 if vote == "useful" else -8 if vote == "not_useful" else 0

    def ranked_key(item: dict[str, Any]) -> tuple[int, int, str]:
        return (int(item.get("importance") or 0) + preference_score(item) + item.get("source_score", 3) - 3, 1 if item.get("change") == "new" else 0, str(item.get("published_at") or ""))

    if mode == "useful":
        items.sort(key=ranked_key, reverse=True)
    elif mode == "opportunity":
        opportunity_items = [item for item in items if item.get("business_opportunity") or any(tag in {"Product", "Company", "Industry", "Agent"} for tag in item.get("tags", []))]
        items = opportunity_items or items
        items.sort(key=ranked_key, reverse=True)
    else:
        items.sort(key=lambda item: item.get("published_at", ""), reverse=True)
    return enrich_aihot_items(items[: max(1, min(limit, 100))])


def save_json_atomic(path: Path, values: Any, mode: int | None = None) -> None:
    DATA_DIR.mkdir(exist_ok=True)
    temporary = path.with_name(f".{path.name}.tmp-{os.getpid()}")
    temporary.write_text(json.dumps(values, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    if mode is not None:
        try:
            temporary.chmod(mode)
        except OSError:
            pass
    os.replace(temporary, path)


def load_integrations() -> dict[str, dict[str, Any]]:
    values = load_json_file(INTEGRATIONS_FILE, {})
    return values if isinstance(values, dict) else {}


def _integration_values(integration_id: str) -> tuple[dict[str, str], str, dict[str, Any]]:
    definition = INTEGRATION_DEFINITIONS.get(integration_id)
    if not definition:
        raise HTTPException(404, "集成不存在")
    saved = load_integrations().get(integration_id)
    saved = saved if isinstance(saved, dict) else {}
    saved_values = saved.get("values") if isinstance(saved.get("values"), dict) else {}
    values: dict[str, str] = {}
    source = ""
    env_keys = INTEGRATION_ENV_KEYS.get(integration_id, {})
    for field in definition["fields"]:
        env_name = env_keys.get(field, "")
        env_value = os.getenv(env_name, "").strip() if env_name else ""
        saved_value = str(saved_values.get(field) or "").strip()
        if env_value:
            values[field] = env_value
            source = "env"
        elif saved_value:
            values[field] = saved_value
            source = source or "saved"
        else:
            values[field] = str((definition.get("defaults") or {}).get(field) or "")
    return values, source, saved


def github_repository_parts(values: dict[str, str]) -> tuple[str, str]:
    """Validate the repository path before putting user input into a URL."""
    owner = str(values.get("owner") or "").strip()
    repo = str(values.get("repo") or "").strip()
    if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.-]{0,99}", owner) or not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.-]{0,99}", repo):
        raise HTTPException(400, "GitHub：用户名/组织和仓库名只能包含字母、数字、点、下划线或短横线")
    return owner, repo


def integration_status(integration_id: str) -> dict[str, Any]:
    definition = INTEGRATION_DEFINITIONS.get(integration_id)
    if not definition:
        raise HTTPException(404, "集成不存在")
    values, source, saved = _integration_values(integration_id)
    required = definition.get("required") or list(definition["fields"])
    configured = all(str(values.get(field) or "").strip() for field in required)
    public_values = {field: value for field, value in values.items() if field not in definition["secret_fields"]}
    secret_state = {f"has_{field}": bool(values.get(field)) for field in definition["secret_fields"]}
    return {
        "id": integration_id,
        "name": definition["name"],
        "repo": definition["repo"],
        "kind": definition["kind"],
        "description": definition["description"],
        "configuration_cost": definition.get("configuration_cost") or "按需配置服务地址；密钥由用户自行提供",
        "data_boundary": definition.get("data_boundary") or "只读读取；导入前需要人工勾选，不自动写回第三方服务",
        "next_step": definition.get("next_step") or "配置后测试连接，再读取最新条目并人工选择导入",
        "fields": definition["fields"],
        "values": public_values,
        **secret_state,
        "configured": configured,
        "enabled": bool(saved.get("enabled", True)) if source != "env" else True,
        "source": source or "未配置",
        "last_test_at": str(saved.get("last_test_at") or ""),
        "last_test_status": str(saved.get("last_test_status") or ""),
        "last_error": str(saved.get("last_error") or ""),
    }


def save_integration_config(integration_id: str, values: dict[str, Any], enabled: bool = True) -> dict[str, Any]:
    definition = INTEGRATION_DEFINITIONS.get(integration_id)
    if not definition:
        raise HTTPException(404, "集成不存在")
    all_values = load_integrations()
    previous = all_values.get(integration_id) if isinstance(all_values.get(integration_id), dict) else {}
    previous_values = previous.get("values") if isinstance(previous.get("values"), dict) else {}
    normalized: dict[str, str] = {}
    for field in definition["fields"]:
        supplied = values.get(field)
        # Secret inputs are intentionally blank when the UI already has a
        # saved value.  Blank means “keep it”, while an explicit clear can be
        # added later without ever echoing the secret back to the browser.
        if field in definition["secret_fields"] and (supplied is None or not str(supplied).strip()) and previous_values.get(field):
            supplied = previous_values.get(field)
        normalized[field] = str(supplied if supplied is not None else "").strip()
    if normalized.get("base_url") and not valid_http_url(normalized["base_url"]):
        raise HTTPException(400, "集成地址必须是 http/https URL")
    all_values[integration_id] = {**previous, "enabled": bool(enabled), "values": normalized, "updated_at": now_iso()}
    save_json_atomic(INTEGRATIONS_FILE, all_values, 0o600)
    return integration_status(integration_id)


def update_integration_test(integration_id: str, status: str, error: str = "") -> None:
    all_values = load_integrations()
    saved = all_values.get(integration_id) if isinstance(all_values.get(integration_id), dict) else {}
    all_values[integration_id] = {**saved, "last_test_at": now_iso(), "last_test_status": status, "last_error": clip(error, 500)}
    save_json_atomic(INTEGRATIONS_FILE, all_values, 0o600)


def integration_url(integration_id: str, path: str = "") -> str:
    values, _source, _saved = _integration_values(integration_id)
    base_url = str(values.get("base_url") or "").strip().rstrip("/")
    if not base_url or not valid_http_url(base_url):
        raise HTTPException(400, f"{INTEGRATION_DEFINITIONS[integration_id]['name']}：请先填写合法的服务地址")
    return f"{base_url}/{path.lstrip('/')}" if path else base_url


def integration_headers(integration_id: str, values: dict[str, str] | None = None) -> dict[str, str]:
    values = values or _integration_values(integration_id)[0]
    headers = {"User-Agent": f"Workbench/{WORKBENCH_VERSION or '0.3'}"}
    if integration_id == "github":
        headers["Accept"] = "application/vnd.github+json"
        headers["X-GitHub-Api-Version"] = "2022-11-28"
        if values.get("token"):
            headers["Authorization"] = f"Bearer {values['token']}"
    elif integration_id == "miniflux" and values.get("api_token"):
        headers["Authorization"] = f"Bearer {values['api_token']}"
    elif integration_id == "zotero" and values.get("api_key"):
        headers["Zotero-API-Key"] = values["api_key"]
        headers["Zotero-API-Version"] = "3"
    elif integration_id == "ntfy" and values.get("token"):
        headers["Authorization"] = f"Bearer {values['token']}"
    elif integration_id in {"linkding", "paperless"} and values.get("token"):
        headers["Authorization"] = f"Token {values['token']}"
    elif integration_id == "vikunja" and values.get("api_token"):
        headers["Authorization"] = f"Bearer {values['api_token']}"
    elif integration_id == "wallabag" and values.get("access_token"):
        headers["Authorization"] = f"Bearer {values['access_token']}"
    if integration_id == "searxng":
        headers["Accept"] = "application/json"
    return headers


def integration_http_error(integration_id: str, exc: Exception) -> HTTPException:
    definition = INTEGRATION_DEFINITIONS.get(integration_id, {})
    response = getattr(exc, "response", None)
    status_code = getattr(response, "status_code", None)
    if status_code in {401, 403}:
        message = "凭据无效或没有访问权限"
    elif status_code == 404:
        message = "服务地址或 API 路径不存在"
    elif status_code == 429:
        message = "第三方服务限流，请稍后重试"
    elif isinstance(exc, httpx.TimeoutException):
        message = "连接超时，请确认线上服务可从服务器访问"
    elif isinstance(exc, httpx.RequestError):
        message = "网络不可达，请确认服务地址、DNS 或代理配置"
    else:
        message = "第三方服务返回了无法处理的响应"
    return HTTPException(502, f"{definition.get('name', integration_id)}：{message}")


async def test_integration_connection(integration_id: str) -> dict[str, Any]:
    values, _source, _saved = _integration_values(integration_id)
    definition = INTEGRATION_DEFINITIONS[integration_id]
    required = definition.get("required") or list(definition["fields"])
    missing = [field for field in required if not values.get(field)]
    if missing:
        raise HTTPException(400, f"{definition['name']}：还缺少 {', '.join(definition['fields'].get(field, field) for field in missing)}")
    if integration_id == "github":
        owner, repo = github_repository_parts(values)
        url = integration_url(integration_id, f"/repos/{owner}/{repo}")
    elif integration_id == "ntfy":
        url = integration_url(integration_id, "/v1/health")
    elif integration_id == "miniflux":
        url = integration_url(integration_id, "/v1/me")
    elif integration_id == "activitywatch":
        url = integration_url(integration_id, "/api/0/buckets")
    elif integration_id == "linkding":
        url = integration_url(integration_id, "/api/bookmarks/?limit=1")
    elif integration_id == "paperless":
        url = integration_url(integration_id, "/api/documents/?page_size=1")
    elif integration_id == "vikunja":
        url = integration_url(integration_id, "/api/v1/info")
    elif integration_id == "searxng":
        url = integration_url(integration_id, "/search")
        params = {"q": "workbench", "format": "json", "categories": values.get("categories") or "general"}
    elif integration_id == "wallabag":
        url = integration_url(integration_id, "/api/entries.json")
        params = {"archive": 0, "perPage": 1}
    else:
        user_id = re.sub(r"[^A-Za-z0-9_-]", "", values.get("user_id", ""))
        if not user_id:
            raise HTTPException(400, "Zotero：用户 ID 格式无效")
        url = integration_url(integration_id, f"/users/{user_id}/items?limit=1&format=json")
    started = time.perf_counter()
    try:
        async with httpx.AsyncClient(timeout=15, trust_env=True, follow_redirects=True, headers=integration_headers(integration_id, values)) as client:
            response = await client.get(url, params=params if "params" in locals() else None)
            response.raise_for_status()
            if integration_id in {"searxng", "wallabag"} and not isinstance(response.json(), (dict, list)):
                raise ValueError("响应不是 JSON 对象或数组")
    except HTTPException:
        raise
    except (httpx.HTTPError, ValueError) as exc:
        error = integration_http_error(integration_id, exc)
        update_integration_test(integration_id, "failed", str(error.detail))
        raise error from exc
    latency_ms = round((time.perf_counter() - started) * 1000)
    update_integration_test(integration_id, "succeeded")
    return {"ok": True, "status_code": response.status_code, "latency_ms": latency_ms}


def _plain_external_text(value: Any, limit: int = 500) -> str:
    text = re.sub(r"<[^>]+>", " ", str(value or ""))
    text = re.sub(r"\s+", " ", text).strip()
    return clip(text, limit)


def _activitywatch_buckets(payload: Any) -> list[dict[str, Any]]:
    """Normalize ActivityWatch's map/list bucket responses without retaining raw events."""
    candidates: list[dict[str, Any]] = []
    if isinstance(payload, dict):
        for key, value in payload.items():
            if not isinstance(value, dict):
                continue
            bucket = dict(value)
            bucket.setdefault("id", key)
            candidates.append(bucket)
    elif isinstance(payload, list):
        candidates = [dict(value) for value in payload if isinstance(value, dict)]
    normalized = []
    for bucket in candidates:
        bucket_id = str(bucket.get("id") or "").strip()
        if not bucket_id:
            continue
        normalized.append({
            "id": bucket_id,
            "name": str(bucket.get("name") or bucket.get("type") or bucket_id).strip()[:160],
            "type": str(bucket.get("type") or "").strip()[:80],
            "client": str(bucket.get("client") or "").strip()[:80],
        })
    return normalized


def _activitywatch_events(payload: Any) -> list[dict[str, Any]]:
    if isinstance(payload, list):
        return [event for event in payload if isinstance(event, dict)]
    if isinstance(payload, dict) and isinstance(payload.get("events"), list):
        return [event for event in payload["events"] if isinstance(event, dict)]
    return []


def _activitywatch_duration(events: list[dict[str, Any]]) -> float:
    total = 0.0
    for event in events:
        try:
            duration = float(event.get("duration") or 0)
        except (TypeError, ValueError):
            duration = 0.0
        if math.isfinite(duration) and duration > 0:
            total += duration
    return round(total, 3)


async def fetch_integration_items(integration_id: str, limit: int = 20) -> list[dict[str, Any]]:
    values, _source, _saved = _integration_values(integration_id)
    definition = INTEGRATION_DEFINITIONS[integration_id]
    required = definition.get("required") or list(definition["fields"])
    missing = [field for field in required if not values.get(field)]
    if missing:
        raise HTTPException(400, f"{definition['name']}：请先完成配置")
    limit = max(1, min(int(limit), 50))
    if integration_id == "github":
        owner, repo = github_repository_parts(values)
        url = integration_url(integration_id, f"/repos/{owner}/{repo}/issues?state=open&per_page={limit}")
    elif integration_id == "ntfy":
        raise HTTPException(400, "ntfy 是通知出口，不提供可导入条目")
    elif integration_id == "miniflux":
        url = integration_url(integration_id, f"/v1/entries?status=unread&limit={limit}")
    elif integration_id == "activitywatch":
        url = integration_url(integration_id, "/api/0/buckets")
    elif integration_id == "linkding":
        url = integration_url(integration_id, f"/api/bookmarks/?limit={limit}")
    elif integration_id == "paperless":
        url = integration_url(integration_id, f"/api/documents/?page_size={limit}&ordering=-added")
    elif integration_id == "vikunja":
        project_id = str(values.get("project_id") or "").strip()
        if project_id:
            url = integration_url(integration_id, f"/api/v1/projects/{quote(project_id, safe='')}/tasks?per_page={limit}&sort_by=due_date&order_by=asc")
        else:
            url = integration_url(integration_id, f"/api/v1/tasks?per_page={limit}&sort_by=due_date&order_by=asc")
    elif integration_id == "searxng":
        url = integration_url(integration_id, "/search")
        params = {
            "q": str(values.get("query") or "").strip(),
            "format": "json",
            "categories": str(values.get("categories") or "general").strip() or "general",
            "pageno": 1,
        }
    elif integration_id == "wallabag":
        url = integration_url(integration_id, "/api/entries.json")
        params = {"archive": 0, "perPage": limit}
    else:
        user_id = re.sub(r"[^A-Za-z0-9_-]", "", values.get("user_id", ""))
        if not user_id:
            raise HTTPException(400, "Zotero：用户 ID 格式无效")
        url = integration_url(integration_id, f"/users/{user_id}/items?limit={limit}&format=json&sort=dateAdded&direction=desc")
    try:
        async with httpx.AsyncClient(timeout=20, trust_env=True, follow_redirects=True, headers=integration_headers(integration_id, values)) as client:
            response = await client.get(url, params=params if "params" in locals() else None)
            response.raise_for_status()
            payload = response.json()
            if integration_id == "activitywatch":
                buckets = _activitywatch_buckets(payload)
                configured_bucket = str(values.get("bucket_id") or "").strip()
                if configured_bucket:
                    buckets = [bucket for bucket in buckets if bucket["id"] == configured_bucket]
                window_end = datetime.now(timezone.utc)
                window_start = window_end - timedelta(days=7)
                window_start_text = window_start.isoformat()
                window_end_text = window_end.isoformat()
                bucket_limit = min(limit, 10)
                activity_items: list[dict[str, Any]] = []
                for bucket in buckets[:bucket_limit]:
                    bucket_url = integration_url("activitywatch", f"/api/0/buckets/{quote(bucket['id'], safe='')}/events")
                    event_response = await client.get(bucket_url, params={"start": window_start_text, "end": window_end_text})
                    event_response.raise_for_status()
                    events = _activitywatch_events(event_response.json())
                    total_seconds = _activitywatch_duration(events)
                    hours = round(total_seconds / 3600, 1)
                    activity_items.append({
                        "id": f"activitywatch:{bucket['id']}:{window_start.date().isoformat()}",
                        "title": f"{bucket['name']} · 近 7 天效率观察",
                        "summary": f"近 7 天记录 {len(events)} 个事件，共 {hours} 小时。仅保留聚合时长，不保存窗口标题或网页 URL。",
                        "url": integration_url("activitywatch"),
                        "published_at": window_end_text,
                        "source": f"ActivityWatch · {bucket['name']}",
                        "metadata": {
                            "remote_id": bucket["id"],
                            "kind": "time_summary",
                            "bucket_id": bucket["id"],
                            "bucket_type": bucket.get("type", ""),
                            "client": bucket.get("client", ""),
                            "event_count": len(events),
                            "total_seconds": total_seconds,
                            "range_start": window_start_text,
                            "range_end": window_end_text,
                            "source_updated_at": window_end_text,
                            "privacy": "aggregated_duration_only",
                        },
                    })
                return sorted(activity_items, key=lambda item: item["metadata"].get("total_seconds", 0), reverse=True)[:limit]
    except (httpx.HTTPError, ValueError, json.JSONDecodeError) as exc:
        raise integration_http_error(integration_id, exc) from exc

    normalized: list[dict[str, Any]] = []
    if integration_id == "github":
        owner, repo = github_repository_parts(values)
        raw_items = payload if isinstance(payload, list) else []
        for raw in raw_items:
            if not isinstance(raw, dict) or not raw.get("number"):
                continue
            number = str(raw.get("number"))
            is_pr = isinstance(raw.get("pull_request"), dict)
