def now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


def clip(value: str | None, limit: int) -> str:
    value = value or ""
    if len(value) <= limit:
        return value
    return value[:limit] + "\n\n[…内容已截断…]"


def clip_for_llm(value: str | None, limit: int) -> str:
    value = value or ""
    if len(value) <= limit:
        return value
    head = int(limit * 0.72)
    tail = limit - head
    return value[:head] + "\n\n[…中间内容已压缩…]\n\n" + value[-tail:]


