def idea_validation_plan(session_id: str) -> dict[str, Any]:
    decisions = list_idea_decisions(session_id)
    latest_version = int(decisions[0]["version"]) if decisions else 0
    all_hypotheses = list_idea_hypotheses(session_id)
    all_tasks = list_idea_validation_tasks(session_id)
    latest_hypotheses = list_idea_hypotheses(session_id, latest_version) if latest_version else all_hypotheses
    latest_tasks = list_idea_validation_tasks(session_id, latest_version) if latest_version else all_tasks
    if latest_version and not latest_hypotheses and all_hypotheses:
        latest_hypotheses = all_hypotheses
    if latest_version and not latest_tasks and all_tasks:
        latest_tasks = all_tasks
    return {
        "session_id": session_id,
        "version": latest_version,
        "hypotheses": latest_hypotheses,
        "tasks": latest_tasks,
        "decisions": decisions,
        "history": {"hypotheses": all_hypotheses, "tasks": all_tasks},
    }


