MEMORY_STATUSES = {"candidate", "confirmed", "rejected", "superseded"}
MEMORY_SECRET_MARKERS = (
    "password", "passwd", "api key", "apikey", "access token", "refresh token", "bearer ",
    "cookie", "authorization", "private key", "secret", "密码", "口令", "密钥", "令牌",
    "身份证", "银行卡", "信用卡", "手机号", "家庭住址",
)


def memory_item_row(row: sqlite3.Row) -> dict[str, Any]:
    item = {key: row[key] for key in row.keys()}
    item["value"] = decode_json_column(item.pop("value_json", "{}"))
    item["pinned"] = bool(item.get("pinned"))
    item["scope_label"] = "全局" if item.get("scope") == "global" else "项目"
    item["kind_label"] = {
        "preference": "偏好",
        "constraint": "边界",
        "routine": "习惯",
        "decision": "决策",
        "profile": "个人信息",
    }.get(str(item.get("kind") or ""), str(item.get("kind") or "记忆"))
    item["status_label"] = {
        "candidate": "待确认",
        "confirmed": "已确认",
        "rejected": "已忽略",
        "superseded": "已更新",
    }.get(str(item.get("status") or ""), str(item.get("status") or "未知"))
    return item


def _memory_is_secret_like(content: str) -> bool:
    normalized = str(content or "").lower()
    if any(marker in normalized for marker in MEMORY_SECRET_MARKERS):
        return True
    return bool(re.search(r"\b(?:sk|rk|pk)-[a-z0-9_-]{12,}\b|-----BEGIN [A-Z ]*PRIVATE KEY-----", normalized, re.IGNORECASE))


def _memory_event(
    connection: sqlite3.Connection,
    memory_id: str,
    event_type: str,
    *,
    source_type: str = "",
    source_id: str = "",
    payload: dict[str, Any] | None = None,
) -> None:
    connection.execute(
        "INSERT INTO memory_events(memory_id, event_type, source_type, source_id, payload_json, created_at) VALUES (?, ?, ?, ?, ?, ?)",
        (memory_id, event_type, clip(source_type, 80), clip(source_id, 160), json.dumps(payload or {}, ensure_ascii=False), now_iso()),
    )


def get_memory_item(memory_id: str) -> dict[str, Any] | None:
    connection = db_connection()
    try:
        row = connection.execute("SELECT * FROM memory_items WHERE id = ? AND owner_id = ?", (memory_id, MEMORY_OWNER_ID)).fetchone()
        return memory_item_row(row) if row else None
    finally:
        connection.close()


def create_memory_item(
    *,
    content: str,
    scope: str = "global",
    project_id: str = "",
    kind: str = "preference",
    memory_key: str = "",
    value: dict[str, Any] | None = None,
    status: str = "candidate",
    confidence: float = 0.5,
    pinned: bool = False,
    source_type: str = "",
    source_id: str = "",
    evidence_text: str = "",
) -> dict[str, Any]:
    clean_content = re.sub(r"\s+", " ", str(content or "")).strip()
    if len(clean_content) < 2:
        raise ValueError("记忆内容太短")
    if _memory_is_secret_like(clean_content):
        raise ValueError("这段内容可能包含凭据或敏感个人信息，不会保存为记忆")
    clean_scope = scope if scope in MEMORY_SCOPES else "global"
    clean_project_id = clip(project_id.strip(), 80) if clean_scope == "project" else ""
    if clean_scope == "project" and not clean_project_id:
        clean_project_id = "workbench"
    clean_kind = kind if kind in MEMORY_KINDS else "preference"
    clean_status = status if status in {"candidate", "confirmed"} else "candidate"
    clean_key = clip(memory_key.strip(), 160)
    clean_confidence = max(0.0, min(float(confidence), 1.0))
    timestamp = now_iso()
    connection = db_connection()
    try:
        existing = None
        if clean_key:
            existing = connection.execute(
                """SELECT * FROM memory_items
                WHERE owner_id = ? AND memory_key = ? AND status IN ('candidate', 'confirmed')
                ORDER BY updated_at DESC LIMIT 1""",
                (MEMORY_OWNER_ID, clean_key),
            ).fetchone()
        if not existing:
            existing = connection.execute(
                """SELECT * FROM memory_items
                WHERE owner_id = ? AND scope = ? AND project_id = ? AND kind = ? AND content = ?
                  AND status IN ('candidate', 'confirmed')
                ORDER BY updated_at DESC LIMIT 1""",
                (MEMORY_OWNER_ID, clean_scope, clean_project_id, clean_kind, clean_content),
            ).fetchone()
        if existing and str(existing["content"]) == clean_content:
            memory_id = str(existing["id"])
            next_status = "confirmed" if clean_status == "confirmed" or existing["status"] == "confirmed" else "candidate"
            next_confidence = max(float(existing["confidence"] or 0), clean_confidence)
            connection.execute(
                """UPDATE memory_items SET status = ?, confidence = ?, pinned = ?, updated_at = ?,
                source_type = CASE WHEN source_type = '' THEN ? ELSE source_type END,
                source_id = CASE WHEN source_id = '' THEN ? ELSE source_id END
                WHERE id = ?""",
                (next_status, next_confidence, int(bool(existing["pinned"]) or pinned), timestamp, clip(source_type, 80), clip(source_id, 160), memory_id),
            )
            _memory_event(connection, memory_id, "reinforced", source_type=source_type, source_id=source_id, payload={"status": next_status, "confidence": next_confidence})
            connection.commit()
            row = connection.execute("SELECT * FROM memory_items WHERE id = ?", (memory_id,)).fetchone()
            return {**memory_item_row(row), "created": False}
        if existing and clean_key and clean_status == "confirmed":
            connection.execute("UPDATE memory_items SET status = 'superseded', updated_at = ? WHERE id = ?", (timestamp, existing["id"]))
            _memory_event(connection, str(existing["id"]), "superseded", source_type=source_type, source_id=source_id)
        memory_id = uuid.uuid4().hex[:16]
        connection.execute(
            """INSERT INTO memory_items
            (id, owner_id, scope, project_id, kind, memory_key, content, value_json, status, confidence,
             sensitivity, pinned, source_type, source_id, evidence_text, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'normal', ?, ?, ?, ?, ?, ?)""",
            (
                memory_id, MEMORY_OWNER_ID, clean_scope, clean_project_id, clean_kind, clean_key, clip(clean_content, 1_000),
                json.dumps(value or {}, ensure_ascii=False), clean_status, clean_confidence, int(pinned), clip(source_type, 80),
                clip(source_id, 160), clip(evidence_text, 1_000), timestamp, timestamp,
            ),
        )
        _memory_event(connection, memory_id, "created", source_type=source_type, source_id=source_id, payload={"status": clean_status})
        connection.commit()
        row = connection.execute("SELECT * FROM memory_items WHERE id = ?", (memory_id,)).fetchone()
        return {**memory_item_row(row), "created": True}
    finally:
        connection.close()


def list_memory_items(*, status: str = "all", project_id: str = "", limit: int = 200) -> list[dict[str, Any]]:
    clauses = ["owner_id = ?"]
    values: list[Any] = [MEMORY_OWNER_ID]
    if status in MEMORY_STATUSES:
        clauses.append("status = ?")
        values.append(status)
    elif status == "active":
        clauses.append("status IN ('candidate', 'confirmed')")
    if project_id:
        clauses.append("(scope = 'global' OR project_id = ?)")
        values.append(project_id)
    values.append(max(1, min(int(limit), 500)))
    connection = db_connection()
    try:
        rows = connection.execute(
            f"SELECT * FROM memory_items WHERE {' AND '.join(clauses)} ORDER BY pinned DESC, updated_at DESC LIMIT ?",
            values,
        ).fetchall()
        return [memory_item_row(row) for row in rows]
    finally:
        connection.close()


def update_memory_item(memory_id: str, updates: dict[str, Any]) -> dict[str, Any] | None:
    current = get_memory_item(memory_id)
    if not current:
        return None
    content = re.sub(r"\s+", " ", str(updates.get("content", current["content"]))).strip()
    if len(content) < 2:
        raise ValueError("记忆内容太短")
    if _memory_is_secret_like(content):
        raise ValueError("这段内容可能包含凭据或敏感个人信息，不会保存为记忆")
    scope = updates.get("scope") if updates.get("scope") in MEMORY_SCOPES else current["scope"]
    project_id = str(updates.get("project_id", current["project_id"])).strip() if scope == "project" else ""
    if scope == "project" and not project_id:
        project_id = current.get("project_id") or "workbench"
    kind = updates.get("kind") if updates.get("kind") in MEMORY_KINDS else current["kind"]
    confidence = max(0.0, min(float(updates.get("confidence", current["confidence"])), 1.0))
    pinned = bool(updates.get("pinned", current["pinned"]))
    value = updates.get("value") if isinstance(updates.get("value"), dict) else current.get("value", {})
    changed_fields = [key for key, old, new in (
        ("content", current["content"], content), ("scope", current["scope"], scope),
        ("project_id", current["project_id"], project_id), ("kind", current["kind"], kind),
        ("confidence", current["confidence"], confidence), ("pinned", current["pinned"], pinned),
        ("value", current.get("value", {}), value),
    ) if old != new]
    connection = db_connection()
    try:
        connection.execute(
            """UPDATE memory_items SET content = ?, scope = ?, project_id = ?, kind = ?, value_json = ?,
            confidence = ?, pinned = ?, updated_at = ? WHERE id = ? AND owner_id = ?""",
            (clip(content, 1_000), scope, clip(project_id, 80), kind, json.dumps(value, ensure_ascii=False), confidence, int(pinned), now_iso(), memory_id, MEMORY_OWNER_ID),
        )
        _memory_event(connection, memory_id, "corrected", source_type="user", payload={"changed_fields": changed_fields})
        connection.commit()
    finally:
        connection.close()
    return get_memory_item(memory_id)


def set_memory_status(memory_id: str, status: str) -> dict[str, Any] | None:
    if status not in {"confirmed", "rejected"}:
        raise ValueError("不支持的记忆状态")
    connection = db_connection()
    try:
        row = connection.execute("SELECT * FROM memory_items WHERE id = ? AND owner_id = ?", (memory_id, MEMORY_OWNER_ID)).fetchone()
        if not row:
            return None
        confidence = max(float(row["confidence"] or 0), 0.9) if status == "confirmed" else float(row["confidence"] or 0)
        connection.execute("UPDATE memory_items SET status = ?, confidence = ?, updated_at = ? WHERE id = ?", (status, confidence, now_iso(), memory_id))
        _memory_event(connection, memory_id, status, source_type="user")
        connection.commit()
    finally:
        connection.close()
    return get_memory_item(memory_id)


def delete_memory_item(memory_id: str) -> bool:
    connection = db_connection()
    try:
        row = connection.execute("SELECT id FROM memory_items WHERE id = ? AND owner_id = ?", (memory_id, MEMORY_OWNER_ID)).fetchone()
        if not row:
            return False
        connection.execute("DELETE FROM memory_events WHERE memory_id = ?", (memory_id,))
        connection.execute("DELETE FROM memory_items WHERE id = ? AND owner_id = ?", (memory_id, MEMORY_OWNER_ID))
        connection.commit()
        return True
    finally:
        connection.close()


def memory_summary() -> dict[str, Any]:
    connection = db_connection()
    try:
        rows = connection.execute("SELECT status, COUNT(*) AS count FROM memory_items WHERE owner_id = ? GROUP BY status", (MEMORY_OWNER_ID,)).fetchall()
        counts = {str(row["status"]): int(row["count"] or 0) for row in rows}
        global_count = int(connection.execute("SELECT COUNT(*) FROM memory_items WHERE owner_id = ? AND scope = 'global' AND status = 'confirmed'", (MEMORY_OWNER_ID,)).fetchone()[0] or 0)
        project_count = int(connection.execute("SELECT COUNT(*) FROM memory_items WHERE owner_id = ? AND scope = 'project' AND status = 'confirmed'", (MEMORY_OWNER_ID,)).fetchone()[0] or 0)
    finally:
        connection.close()
    return {"confirmed": counts.get("confirmed", 0), "candidate": counts.get("candidate", 0), "rejected": counts.get("rejected", 0), "superseded": counts.get("superseded", 0), "global": global_count, "project": project_count}


def _memory_kind_for_text(text: str) -> str:
    if any(word in text for word in ("必须", "不要", "不能", "别再", "不接受", "务必")):
        return "constraint"
    if any(word in text for word in ("每次", "习惯", "通常", "总是")):
        return "routine"
    if any(word in text for word in ("我是", "我在", "我的身份")):
        return "profile"
    return "preference"


def learn_memories_from_message(message: str, *, project_id: str, source_type: str, source_id: str) -> list[dict[str, Any]]:
    """Extract only durable, user-authored signals; assistant text is never learned."""
    text = clip(str(message or "").strip(), 2_000)
    if not text:
        return []
    patterns: tuple[tuple[re.Pattern[str], bool, str], ...] = (
        (re.compile(r"^(?:请)?记住(?:了)?[：,:，\s]*(.+)$"), True, "用户明确要求记住"),
        (re.compile(r"^(?:以后|今后)(?:都|一直|请)?[：,:，\s]*(.+)$"), True, "用户明确指定长期规则"),
        (re.compile(r"^(?:每次|始终|一直)(?:都|请)?[：,:，\s]*(.+)$"), True, "用户明确指定重复习惯"),
        (re.compile(r"^(我(?:更)?(?:喜欢|偏好|习惯|不喜欢|讨厌).+)$"), False, "从用户表达中发现偏好"),
        (re.compile(r"^((?:别再|永远不要|我不接受).+)$"), True, "用户明确指定边界"),
    )
    learned: list[dict[str, Any]] = []
    seen: set[str] = set()
    sentences = [part.strip(" \t\r\n，,：:") for part in re.split(r"[。！？!?;；\n]+", text) if part.strip()]
    for sentence in sentences[:8]:
        for pattern, explicit, reason in patterns:
            match = pattern.match(sentence)
            if not match:
                continue
            content = re.sub(r"\s+", " ", match.group(1).strip(" ，,：:\"'“”"))
            if len(content) < 3 or content in seen or _memory_is_secret_like(content):
                break
            seen.add(content)
            project_specific = any(marker in sentence for marker in ("这个项目", "当前项目", "这个页面", "在这里"))
            scope = "project" if project_specific else "global"
            memory_project_id = project_id if scope == "project" else ""
            digest = hashlib.sha256(f"{scope}\n{memory_project_id}\n{content}".encode("utf-8", errors="ignore")).hexdigest()[:20]
            item = create_memory_item(
                content=content,
                scope=scope,
                project_id=memory_project_id,
                kind=_memory_kind_for_text(sentence),
                memory_key=f"learned:{digest}",
                value={"learning_reason": reason},
                status="confirmed" if explicit else "candidate",
                confidence=1.0 if explicit else 0.72,
                pinned=explicit,
                source_type=source_type,
                source_id=source_id,
                evidence_text=sentence,
            )
            item["learning_reason"] = reason
            learned.append(item)
            break
    return learned


def sync_cid_preferences_to_memories(preferences: dict[str, Any]) -> None:
    for field, polarity in (("preferred_tags", "preferred"), ("avoid_tags", "avoid")):
        tags = [value.strip() for value in str(preferences.get(field) or "").split(",") if value.strip()]
        for tag in tags[:40]:
            normalized = re.sub(r"\s+", "-", tag.lower())[:80]
            content = f"独立开发机会中{'偏好' if polarity == 'preferred' else '避开'}赛道标签：{tag}"
            try:
                create_memory_item(
                    content=content,
                    scope="project",
                    project_id="cid-dashboard",
                    kind="preference" if polarity == "preferred" else "constraint",
                    memory_key=f"cid-tag:{normalized}",
                    value={"tag": tag, "polarity": polarity},
                    status="confirmed",
                    confidence=1.0,
                    source_type="cid_preferences",
                )
            except ValueError:
                continue


def ensure_legacy_cid_memories() -> None:
    connection = db_connection()
    try:
        imported = connection.execute(
            "SELECT 1 FROM memory_events WHERE memory_id = 'system:cid-legacy' AND event_type = 'legacy_import_completed' LIMIT 1"
        ).fetchone()
    finally:
        connection.close()
    if imported:
        return
    sync_cid_preferences_to_memories(load_cid_preferences())
    connection = db_connection()
    try:
        _memory_event(connection, "system:cid-legacy", "legacy_import_completed", source_type="cid_preferences")
        connection.commit()
    finally:
        connection.close()


def retrieve_memories(
    query: str,
    *,
    project_id: str,
    limit: int = MAX_MEMORY_CONTEXT_ITEMS,
    core_only: bool = False,
) -> list[dict[str, Any]]:
    """Return a small prompt window, never the whole durable memory store."""
    if project_id == "cid-dashboard":
        ensure_legacy_cid_memories()
    connection = db_connection()
    try:
        rows = connection.execute(
            """SELECT * FROM memory_items
            WHERE owner_id = ? AND status = 'confirmed'
              AND sensitivity = 'normal'
              AND (scope = 'global' OR (scope = 'project' AND project_id = ?))
              AND (expires_at = '' OR expires_at > ?)
            ORDER BY pinned DESC, updated_at DESC LIMIT 300""",
            (MEMORY_OWNER_ID, project_id, now_iso()),
        ).fetchall()
        terms = query_terms(query)
        pinned: list[tuple[float, sqlite3.Row]] = []
        matched: list[tuple[float, sqlite3.Row]] = []
        for row in rows:
            haystack = f"{row['memory_key']} {row['content']} {row['value_json']}".lower()
            matches = sum(1 for term in terms if term in haystack)
            score = (34 if row["scope"] == "project" else 16)
            score += float(row["confidence"] or 0) * 20 + min(int(row["use_count"] or 0), 5) + matches * 12
            if row["pinned"]:
                pinned.append((score, row))
            elif matches:
                matched.append((score, row))
        sort_key = lambda pair: (pair[0], str(pair[1]["updated_at"]))
        pinned.sort(key=sort_key, reverse=True)
        matched.sort(key=sort_key, reverse=True)
        maximum = max(1, min(int(limit), MAX_MEMORY_CONTEXT_ITEMS))
        selected_rows = [row for _, row in pinned[: min(MAX_MEMORY_PINNED_ITEMS, maximum)]]
        if not core_only:
            matched_limit = min(MAX_MEMORY_MATCHED_ITEMS, maximum - len(selected_rows))
            selected_rows.extend(row for _, row in matched[:matched_limit])
        return [memory_item_row(row) for row in selected_rows]
    finally:
        connection.close()


def memory_context_for_llm(project_id: str, message: str, *, core_only: bool = False) -> dict[str, Any]:
    candidates = retrieve_memories(message, project_id=project_id, core_only=core_only)
    empty_stats = {
        "items": 0,
        "chars": 0,
        "pinned": 0,
        "matched": 0,
        "calls": 0,
        "max_items": MAX_MEMORY_CONTEXT_ITEMS,
        "max_chars": MAX_MEMORY_CONTEXT_CHARS,
        "core_only": bool(core_only),
    }
    if not candidates:
        return {"text": "", "items": [], "refs": [], "stats": empty_stats}
    header = [
        "以下是用户已确认且与本轮相关的少量长期记忆，只用于调整表达、排序和执行偏好；不能代替当前项目数据或外部事实。",
        "本轮明确要求与旧记忆冲突时，以本轮为准。",
    ]
    lines = list(header)
    packed: list[dict[str, Any]] = []
    for item in candidates:
        content = str(item.get("content") or "")
        if len(content) > MAX_MEMORY_ITEM_CONTEXT_CHARS:
            content = content[: MAX_MEMORY_ITEM_CONTEXT_CHARS - 1].rstrip() + "…"
        scope_label = "全局" if item["scope"] == "global" else f"项目:{item['project_id']}"
        line = f"- [{scope_label}/{item['kind_label']}] {content}"
        if len("\n".join([*lines, line])) > MAX_MEMORY_CONTEXT_CHARS:
            continue
        lines.append(line)
        packed.append(item)
    items = packed
    if not items:
        return {"text": "", "items": [], "refs": [], "stats": empty_stats}
    text = "\n".join(lines)
    timestamp = now_iso()
    connection = db_connection()
    try:
        connection.executemany(
            "UPDATE memory_items SET last_used_at = ?, use_count = use_count + 1 WHERE id = ?",
            [(timestamp, item["id"]) for item in items],
        )
        connection.commit()
    finally:
        connection.close()
    refs = [
        {"id": item["id"], "content": str(item["content"])[:MAX_MEMORY_ITEM_CONTEXT_CHARS], "scope": item["scope"], "project_id": item["project_id"], "kind": item["kind"], "confidence": item["confidence"], "pinned": bool(item["pinned"])}
        for item in items
    ]
    stats = {
        **empty_stats,
        "items": len(items),
        "chars": len(text),
        "pinned": sum(1 for item in items if item.get("pinned")),
        "matched": sum(1 for item in items if not item.get("pinned")),
        "calls": 1,
    }
    return {"text": text, "items": items, "refs": refs, "stats": stats}


def workbuddy_memory_preview() -> list[dict[str, Any]]:
    path = ROOT / ".workbuddy" / "memory" / "MEMORY.md"
    try:
        lines = path.read_text(encoding="utf-8").splitlines()
    except OSError:
        return []
    in_preferences = False
    candidates: list[dict[str, Any]] = []
    for line in lines:
        stripped = line.strip()
        if stripped == "## 用户偏好":
            in_preferences = True
            continue
        if in_preferences and stripped.startswith("## "):
            break
        if in_preferences and stripped.startswith("- "):
            content = stripped[2:].strip()
            if content and not _memory_is_secret_like(content):
                candidates.append({"content": clip(content, 1_000), "kind": _memory_kind_for_text(content), "source": str(path)})
    return candidates[:30]


def import_workbuddy_memories() -> list[dict[str, Any]]:
    imported = []
    for candidate in workbuddy_memory_preview():
        digest = hashlib.sha256(candidate["content"].encode("utf-8", errors="ignore")).hexdigest()[:20]
        imported.append(create_memory_item(
            content=candidate["content"], scope="global", kind=candidate["kind"], memory_key=f"workbuddy:{digest}",
            status="confirmed", confidence=1.0, source_type="workbuddy", source_id="MEMORY.md",
        ))
    return imported


def create_agent_action_record(
    *,
    project_id: str,
    name: str,
    tool: str,
    arguments: dict[str, Any] | None = None,
    risk: str = "low",
    requires_confirmation: bool = False,
    run_id: str = "",
) -> dict[str, Any]:
    action_id = uuid.uuid4().hex[:12]
    timestamp = now_iso()
    connection = db_connection()
    try:
        connection.execute(
            """INSERT INTO agent_actions
            (id, project_id, name, tool, status, risk, requires_confirmation, arguments_json, result_json, run_id, created_at, updated_at)
            VALUES (?, ?, ?, ?, 'pending', ?, ?, ?, '{}', ?, ?, ?)""",
            (
                action_id,
                project_id,
                name,
                tool,
                risk,
                int(requires_confirmation),
                json.dumps(arguments or {}, ensure_ascii=False),
                run_id,
                timestamp,
                timestamp,
            ),
        )
        connection.commit()
        row = connection.execute("SELECT * FROM agent_actions WHERE id = ?", (action_id,)).fetchone()
        action = agent_action_row(row)
    finally:
        connection.close()
    if requires_confirmation:
        try:
            create_notification_record(
                title=f"Agent 待确认：{name}",
                body=f"{agent_display_name(project_id)} 请求执行 {tool}",
                project_id=project_id,
                kind="agent_action",
                level="warning",
                href=f"/projects/{project_id}" if project_id != "workbench" else "/",
                event_key=f"agent-action:{action_id}",
                dedupe_seconds=0,
            )
        except Exception:
            pass
    return action


def get_agent_action_record(action_id: str) -> dict[str, Any] | None:
    connection = db_connection()
    try:
        row = connection.execute("SELECT * FROM agent_actions WHERE id = ?", (action_id,)).fetchone()
        return agent_action_row(row) if row else None
    finally:
        connection.close()


def update_agent_action_record(
    action_id: str,
    *,
    status: str | None = None,
    result: dict[str, Any] | None = None,
    run_id: str | None = None,
) -> dict[str, Any] | None:
    updates: list[tuple[str, Any]] = [("updated_at", now_iso())]
    if status is not None:
        updates.append(("status", status))
    if result is not None:
        updates.append(("result_json", json.dumps(result, ensure_ascii=False)))
    if run_id is not None:
        updates.append(("run_id", run_id))
    connection = db_connection()
    try:
        assignments = ", ".join(f"{key} = ?" for key, _ in updates)
        cursor = connection.execute(
            f"UPDATE agent_actions SET {assignments} WHERE id = ?",
            [value for _, value in updates] + [action_id],
        )
        connection.commit()
        if cursor.rowcount == 0:
            return None
        row = connection.execute("SELECT * FROM agent_actions WHERE id = ?", (action_id,)).fetchone()
        return agent_action_row(row)
    finally:
        connection.close()


def list_artifacts(project_id: str = "") -> list[dict[str, Any]]:
    connection = db_connection()
    try:
        if project_id:
            rows = connection.execute(
                "SELECT * FROM artifacts WHERE project_id = ? ORDER BY created_at DESC LIMIT 200", (project_id,)
            ).fetchall()
        else:
            rows = connection.execute("SELECT * FROM artifacts ORDER BY created_at DESC LIMIT 200").fetchall()
        return [artifact_row(row) for row in rows]
    finally:
        connection.close()


def get_artifact_record(artifact_id: int) -> dict[str, Any] | None:
    connection = db_connection()
    try:
        row = connection.execute("SELECT * FROM artifacts WHERE id = ?", (int(artifact_id),)).fetchone()
        return artifact_row(row) if row else None
    finally:
        connection.close()


DOCUMENT_FACTORY_SOURCE_SUFFIXES = {".txt", ".md", ".markdown", ".csv", ".json", ".pdf", ".docx", ".xlsx", ".xlsm", ".pptx", ".html", ".htm"}


def document_factory_allowed_roots() -> list[Path]:
    """Only expose files already inside Workbench-managed material roots.

    Artifact metadata can come from multiple projects. The document Agent may
    read their registered files, but it must not turn an arbitrary database
    row into an unrestricted filesystem reader.
    """
    roots: list[Path] = []
    for root in (OUTPUTS_DIR, KNOWLEDGE_DIR, OBSIDIAN_VAULT_DIR, DATA_DIR):
        try:
            resolved = root.expanduser().resolve()
        except OSError:
            continue
        if resolved not in roots:
            roots.append(resolved)
    return roots


def artifact_source_path(artifact: dict[str, Any]) -> tuple[Path | None, str]:
    raw_path = str(artifact.get("path") or "").strip()
    if not raw_path:
        return None, "这个 Artifact 没有登记文件路径"
    try:
        candidate = Path(raw_path).expanduser()
        if not candidate.is_absolute():
            candidate = ROOT / candidate
        resolved = candidate.resolve()
    except OSError:
        return None, "Artifact 文件路径无法解析"
    if resolved.suffix.lower() not in DOCUMENT_FACTORY_SOURCE_SUFFIXES:
        return None, f"暂不支持读取 {resolved.suffix or '该'} 文件格式"
    data_root = DATA_DIR.expanduser().resolve()
    is_data_file = resolved == data_root or data_root in resolved.parents
    if is_data_file and str(artifact.get("project_id") or "") not in {"aihot", "market", "server"}:
        return None, "账户和系统配置快照可能包含敏感字段，不作为文档材料读取"
    if not any(resolved == root or root in resolved.parents for root in document_factory_allowed_roots()):
        return None, "出于安全边界，只能读取工作台已管理目录中的文件"
    if not resolved.is_file():
        return None, "登记的文件已经不存在"
    return resolved, ""


MINERU_COMMAND = os.getenv("WORKBENCH_MINERU_CMD", "mineru").strip() or "mineru"
MINERU_TIMEOUT_SECONDS = max(60, int(os.getenv("WORKBENCH_MINERU_TIMEOUT_SECONDS", "600") or 600))
MINERU_SUFFIXES = {".pdf", ".png", ".jpg", ".jpeg", ".webp"}


def mineru_status() -> dict[str, Any]:
    """Report the optional MinerU adapter.

    MinerU is markedly better than pypdf/MarkItDown on Chinese PDFs, scanned
    documents, formulas and complex tables, but it is heavy and slow. It stays
    strictly optional: when the binary is absent the existing chain is used
    unchanged.
    """
    executable = shutil.which(MINERU_COMMAND)
    if not executable:
        return {"available": False, "label": "MinerU 未安装", "version": "", "mode": "off"}
    try:
        probe = subprocess.run([executable, "--version"], capture_output=True, text=True, timeout=20, check=False)
        version = (probe.stdout or probe.stderr or "").strip().splitlines()[0] if probe.returncode == 0 else "已安装"
    except (OSError, subprocess.SubprocessError):
        version = "已安装"
    return {"available": True, "label": "MinerU 可用", "version": clip(version, 60), "mode": "preferred", "path": executable}


def extract_with_mineru(raw: bytes, filename: str) -> str:
    """Run MinerU in a temp dir and return the Markdown it produced.

    Returns "" on any failure so the caller falls through to MarkItDown and
    then the native parsers. MinerU runs as a subprocess rather than an import
    so a heavy optional dependency never lives inside the API process, and a
    hung run cannot outlive its timeout.
    """
    suffix = Path(filename).suffix.lower()
    if suffix not in MINERU_SUFFIXES:
        return ""
    executable = shutil.which(MINERU_COMMAND)
    if not executable:
        return ""
    import tempfile

    try:
        with tempfile.TemporaryDirectory(prefix="workbench-mineru-") as workspace:
            root = Path(workspace)
            source = root / f"input{suffix}"
            source.write_bytes(raw)
            output = root / "out"
            output.mkdir(parents=True, exist_ok=True)
            completed = subprocess.run(
                [executable, "-p", str(source), "-o", str(output)],
                capture_output=True,
                text=True,
                timeout=MINERU_TIMEOUT_SECONDS,
                check=False,
                start_new_session=True,
            )
            if completed.returncode != 0:
                return ""
            markdowns = sorted(output.rglob("*.md"), key=lambda path: path.stat().st_size, reverse=True)
            for candidate in markdowns:
                try:
                    text = candidate.read_text(encoding="utf-8").strip()
                except (OSError, UnicodeDecodeError):
                    continue
                if text:
                    return text
    except (OSError, subprocess.SubprocessError, ValueError):
        return ""
    return ""


def markitdown_status() -> dict[str, Any]:
    """Report the optional Microsoft MarkItDown adapter without making it required.

    MarkItDown improves table, slide and mixed-document extraction when it is
    installed. The native parsers remain the deterministic fallback so a
    missing optional package never blocks the document factory.
    """
    try:
        import markitdown  # type: ignore

        version = str(getattr(markitdown, "__version__", "") or "已安装")
        return {"available": True, "label": "MarkItDown 可用", "version": version, "mode": "optional"}
    except ImportError:
        return {"available": False, "label": "内置解析器", "version": "", "mode": "fallback"}
    except Exception as exc:
        return {"available": False, "label": "内置解析器", "version": "", "mode": "fallback", "detail": clip(str(exc), 120)}


def extract_with_markitdown(raw: bytes, filename: str) -> str:
    """Try MarkItDown for rich office/PDF/HTML extraction, returning empty on fallback."""
    suffix = Path(filename).suffix.lower()
    if suffix in {".txt", ".md", ".markdown", ".csv", ".json"}:
        return ""
    try:
        from markitdown import MarkItDown  # type: ignore
    except ImportError:
        return ""
    try:
        converter = MarkItDown()
        stream = io.BytesIO(raw)
        result = None
        try:
            from markitdown import StreamInfo  # type: ignore

            result = converter.convert_stream(stream, stream_info=StreamInfo(file_extension=suffix))
        except (ImportError, TypeError):
            stream.seek(0)
            result = converter.convert_stream(stream)
        text = str(getattr(result, "text_content", "") or "").strip()
        return text
    except Exception:
        # The native parser below is intentionally the compatibility path for
        # older MarkItDown releases and files that the optional adapter cannot
        # decode.
        return ""


def document_extraction_engine(filename: str) -> str:
    suffix = Path(filename).suffix.lower()
    if suffix in {".txt", ".md", ".markdown", ".csv", ".json"}:
        return "内置文本解析器"
    if suffix in MINERU_SUFFIXES and mineru_status()["available"]:
        return "MinerU（优先）→ MarkItDown → 内置解析器"
    return "MarkItDown（可选）或内置解析器"


def extract_document_bytes(raw: bytes, filename: str) -> str:
    suffix = Path(filename).suffix.lower()
    if suffix in {".txt", ".md", ".markdown", ".csv", ".json"}:
        return raw.decode("utf-8", errors="replace")
    # MinerU first for PDFs and images: it handles Chinese layout, scans,
    # formulas and merged tables that the other parsers silently mangle.
    # Everything below stays as the fallback chain.
    mineru_text = extract_with_mineru(raw, filename)
    if mineru_text:
        return mineru_text
    enhanced = extract_with_markitdown(raw, filename)
    if enhanced:
        return enhanced
    if suffix == ".pdf":
        from pypdf import PdfReader

        reader = PdfReader(io.BytesIO(raw))
        return "\n\n".join(page.extract_text() or "" for page in reader.pages)
    if suffix == ".docx":
        from docx import Document

        document = Document(io.BytesIO(raw))
        return "\n\n".join(paragraph.text for paragraph in document.paragraphs)
    if suffix in {".xlsx", ".xlsm"}:
        from openpyxl import load_workbook

        workbook = load_workbook(io.BytesIO(raw), read_only=True, data_only=True)
        sheets = []
        for sheet in workbook.worksheets:
            rows = [" | ".join("" if value is None else str(value) for value in row) for row in sheet.iter_rows(values_only=True)]
            sheets.append(f"## {sheet.title}\n" + "\n".join(rows))
        return "\n\n".join(sheets)
    if suffix in {".pptx", ".html", ".htm"}:
        raise ValueError("这类文件需要安装可选的 MarkItDown 才能读取；也可以先导出为 PDF 或 Markdown")
    raise ValueError("暂不支持该文件格式，请上传 Markdown、TXT、CSV、JSON、PDF、DOCX、XLSX 或 PPTX")


def read_artifact_source(artifact: dict[str, Any]) -> tuple[str, str]:
    path, error = artifact_source_path(artifact)
    if error or not path:
        return "", error or "Artifact 文件不可读"
    try:
        if path.stat().st_size > 15 * 1024 * 1024:
            return "", "文件超过 15 MB，暂不作为文档材料读取"
        content = extract_document_bytes(path.read_bytes(), path.name).strip()
    except Exception as exc:
        return "", f"读取失败：{clip(str(exc), 180)}"
    if not content:
        return "", "文件中没有可提取的文本"
    return clip(content, 100_000), ""


def document_factory_source_descriptors(limit: int = 100) -> list[dict[str, Any]]:
    projects = {str(item.get("id")): item for item in load_projects()}
    descriptors = []
    seen_paths: set[str] = set()
    for artifact in list_artifacts():
        source_key = str(artifact.get("path") or f"artifact:{artifact.get('id')}")
        if source_key in seen_paths:
            continue
        seen_paths.add(source_key)
        path, path_error = artifact_source_path(artifact)
        metadata = artifact.get("metadata") if isinstance(artifact.get("metadata"), dict) else {}
        project_id = str(artifact.get("project_id") or "")
        descriptors.append(
            {
                "id": artifact.get("id"),
                "project_id": project_id,
                "project_name": agent_display_name(project_id) or projects.get(project_id, {}).get("title", project_id),
                "name": artifact.get("name", "未命名 Artifact"),
                "kind": artifact.get("kind", "file"),
                "created_at": artifact.get("created_at", ""),
                "title": metadata.get("title") or artifact.get("name", ""),
                "version": metadata.get("version"),
                "source_name": metadata.get("source_name") or artifact.get("name", ""),
                "readable": bool(path),
                "unavailable_reason": path_error,
            }
        )
    return descriptors[: max(1, min(limit, 200))]


def collect_document_factory_materials(request: DocumentFactoryRequest) -> dict[str, Any]:
    requested_ids = list(dict.fromkeys(int(value) for value in request.artifact_ids))
    materials: list[dict[str, Any]] = []
    errors: list[str] = []
    for artifact_id in requested_ids:
        artifact = get_artifact_record(artifact_id)
        if not artifact:
            errors.append(f"Artifact #{artifact_id} 不存在")
            continue
        content, error = read_artifact_source(artifact)
        if error:
            errors.append(f"{artifact.get('name', f'Artifact #{artifact_id}')}：{error}")
            continue
        metadata = artifact.get("metadata") if isinstance(artifact.get("metadata"), dict) else {}
        materials.append(
            {
                "artifact_id": artifact_id,
                "project_id": artifact.get("project_id", ""),
                "project_name": agent_display_name(str(artifact.get("project_id") or "")),
                "name": artifact.get("name", f"Artifact #{artifact_id}"),
                "kind": artifact.get("kind", "file"),
                "version": metadata.get("version"),
                "source_name": metadata.get("source_name") or artifact.get("name", ""),
                "content": content,
            }
        )
    if request.source_text.strip():
        materials.insert(
            0,
            {
                "artifact_id": None,
                "project_id": "inline",
                "project_name": "本次输入",
                "name": request.source_name.strip() or "粘贴材料",
                "kind": "inline_material",
                "version": None,
                "source_name": request.source_name.strip() or "粘贴材料",
                "content": request.source_text.strip(),
            },
        )
    combined_parts = []
    for index, material in enumerate(materials, start=1):
        artifact_label = f"Artifact #{material['artifact_id']}" if material.get("artifact_id") else "本次输入"
        version_label = f" · v{material['version']}" if material.get("version") else ""
        combined_parts.append(
            f"### 来源 {index} · {artifact_label} · {material['project_name']} · {material['name']}{version_label}\n"
            f"来源文件：{material['source_name']}\n\n{clip_for_llm(material['content'], 24_000)}"
        )
    return {
        "materials": materials,
        "errors": errors,
        "combined_text": clip_for_llm("\n\n".join(combined_parts), 80_000),
        "source_artifact_ids": [item["artifact_id"] for item in materials if item.get("artifact_id")],
    }


def document_factory_citation_coverage(document_text: str, source_materials: dict[str, Any]) -> dict[str, Any]:
    """Estimate paragraph-level source coverage without pretending to prove facts.

    The document Agent is asked to retain source markers, but a marker count is
    too weak: one marker can sit beside several unsupported paragraphs. This
    lightweight check compares lexical evidence against the registered source
    materials and reports a review signal. It never edits the document or
    upgrades an unsupported claim into a fact.
    """
    materials = source_materials.get("materials") if isinstance(source_materials, dict) else []
    source_tokens = set()
    for material in materials or []:
        if isinstance(material, dict):
            source_tokens.update(knowledge_tokens(material.get("content", "")))
    paragraphs = []
    for raw in re.split(r"\n\s*\n", str(document_text or "")):
        text = re.sub(r"^\s{0,3}(?:#{1,6}|[-*+]|•|\d+[.)])\s*", "", raw.strip(), flags=re.MULTILINE)
        text = re.sub(r"\[[^\]]{1,160}\]", "", text).strip()
        tokens = knowledge_tokens(text)
        if len(text) >= 18 and len(tokens) >= 2:
            marker = bool(re.search(r"\[\s*来源[：:]", raw, flags=re.IGNORECASE))
            overlap = len(tokens & source_tokens) / max(1, len(tokens)) if source_tokens else 0.0
            paragraphs.append({"text": clip(text, 180), "marked": marker, "overlap": round(overlap, 3), "supported": overlap >= 0.18})
    supported = [item for item in paragraphs if item["supported"]]
    marked_supported = [item for item in supported if item["marked"]]
    return {
        "paragraph_count": len(paragraphs),
        "source_supported_paragraphs": len(supported),
        "marked_supported_paragraphs": len(marked_supported),
        "coverage": round(len(marked_supported) / len(supported), 3) if supported else None,
        "marked_paragraphs": sum(1 for item in paragraphs if item["marked"]),
        "unmarked_supported_examples": [item["text"] for item in supported if not item["marked"]][:5],
        "policy": "基于词汇重叠和来源标记的人工复核提示，不是事实一致性证明。",
    }


def document_factory_review_checks(document_text: str, metadata: dict[str, Any], source_materials: dict[str, Any]) -> dict[str, Any]:
    source_ids = [int(value) for value in metadata.get("source_artifact_ids", []) if str(value).isdigit()]
    source_count = len(source_ids)
    source_markers = len(re.findall(r"\[来源[：:]", document_text))
    sensitive_hits = sorted(
        set(
            match.group(0).lower()
            for match in re.finditer(r"(?:api[_ -]?key|authorization|bearer\s+[a-z0-9._-]+|password|cookie|secret)", document_text, flags=re.IGNORECASE)
        )
    )
    citation_coverage = document_factory_citation_coverage(document_text, source_materials)
    coverage = citation_coverage.get("coverage")
    coverage_status = "warn" if source_count and (coverage is None or float(coverage) < 0.6) else "pass" if source_count else "warn"
    coverage_detail = (
        f"来源支持段落 {citation_coverage['source_supported_paragraphs']} 段，已带来源标记 {citation_coverage['marked_supported_paragraphs']} 段，覆盖率 {float(coverage) * 100:.0f}%"
        if coverage is not None
        else "没有足够的来源词汇重叠来评估段落覆盖，建议人工核对"
    )
    checks = [
        {
            "id": "document_nonempty",
            "label": "产物内容可读取",
            "status": "pass" if document_text.strip() else "fail",
            "detail": "已读取生成的 Markdown" if document_text.strip() else "产物为空",
        },
        {
            "id": "source_manifest",
            "label": "来源清单存在",
            "status": "pass" if source_count else "warn",
            "detail": f"登记了 {source_count} 份 Artifact 来源" if source_count else "这份产物没有登记 Artifact 来源",
        },
        {
            "id": "citation_coverage",
            "label": "段落级引用覆盖",
            "status": coverage_status,
            "detail": coverage_detail if source_count else "没有登记来源，无法进行段落级引用覆盖检查",
        },
        {
            "id": "sensitive_scan",
            "label": "敏感信息扫描",
            "status": "fail" if sensitive_hits else "pass",
            "detail": f"发现疑似敏感词：{'、'.join(sensitive_hits)}" if sensitive_hits else "未发现常见 Key、Cookie、密码或授权头模式",
        },
        {
            "id": "source_readability",
            "label": "来源文件仍可读取",
            "status": "pass" if source_count and not source_materials.get("errors") else "warn" if source_count else "warn",
            "detail": "来源文件均可重新读取" if source_count and not source_materials.get("errors") else "部分来源已不可读取，无法完成完整复核" if source_materials.get("errors") else "没有可复核的 Artifact 来源",
        },
    ]
    return {
        "checks": checks,
        "source_artifact_ids": source_ids,
        "source_markers": source_markers,
        "citation_coverage": citation_coverage,
        "sensitive_hits": sensitive_hits,
        "errors": [item["detail"] for item in checks if item["status"] == "fail"],
        "warnings": [item["detail"] for item in checks if item["status"] == "warn"],
    }


def create_artifact_record(
    *, project_id: str, name: str, path: str = "", kind: str = "file", metadata: dict[str, Any] | None = None
) -> dict[str, Any]:
    connection = db_connection()
    try:
        cursor = connection.execute(
            """INSERT INTO artifacts
            (project_id, name, path, kind, metadata_json, created_at)
            VALUES (?, ?, ?, ?, ?, ?)""",
            (project_id, name.strip(), path.strip(), kind.strip() or "file", json.dumps(metadata or {}, ensure_ascii=False), now_iso()),
        )
        connection.commit()
        row = connection.execute("SELECT * FROM artifacts WHERE id = ?", (cursor.lastrowid,)).fetchone()
        return artifact_row(row)
    finally:
        connection.close()


def register_artifact_safely(
    *, project_id: str, name: str, path: str = "", kind: str = "file", metadata: dict[str, Any] | None = None
) -> dict[str, Any] | None:
    try:
        return create_artifact_record(project_id=project_id, name=name, path=path, kind=kind, metadata=metadata)
    except Exception:
        # Artifact indexing must never make the primary project operation fail.
        return None


def list_work_items(status: str = "all", project_id: str = "") -> list[dict[str, Any]]:
    connection = db_connection()
    try:
        clauses: list[str] = []
        values: list[str] = []
        if status and status != "all":
            clauses.append("status = ?")
            values.append(status)
        if project_id:
            clauses.append("(source_project = ? OR target_project = ?)")
            values.extend([project_id, project_id])
        where = f" WHERE {' AND '.join(clauses)}" if clauses else ""
        rows = connection.execute(
            f"SELECT * FROM work_items{where} ORDER BY updated_at DESC, id DESC LIMIT 200", values
        ).fetchall()
        return [work_item_row(row) for row in rows]
    finally:
        connection.close()


def get_work_item_record(item_id: int) -> dict[str, Any] | None:
    connection = db_connection()
    try:
        row = connection.execute("SELECT * FROM work_items WHERE id = ?", (item_id,)).fetchone()
        return work_item_row(row) if row else None
    finally:
        connection.close()


def create_work_item_record(
    *,
    title: str,
    description: str = "",
    kind: str = "task",
    status: str = "open",
    priority: str = "normal",
    source_project: str = "workbench",
    target_project: str = "",
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    timestamp = now_iso()
    connection = db_connection()
    try:
        cursor = connection.execute(
            """INSERT INTO work_items
            (title, description, kind, status, priority, source_project, target_project, metadata_json, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
            (
                title.strip(),
                description.strip(),
                kind.strip() or "task",
                status.strip() or "open",
                priority.strip() or "normal",
                source_project.strip() or "workbench",
                target_project.strip(),
                json.dumps(metadata or {}, ensure_ascii=False),
                timestamp,
                timestamp,
            ),
        )
        connection.commit()
        row = connection.execute("SELECT * FROM work_items WHERE id = ?", (cursor.lastrowid,)).fetchone()
        item = work_item_row(row)
    finally:
        connection.close()
    # Agent dispatches get one result notification after the orchestrator finishes.
    # Emitting a second "task created" notification here made the in-app center
    # noisy and left the user without the actual result.
    if kind != "agent_dispatch" and (kind == "alert" or priority in {"high", "urgent"}):
        try:
            item_metadata = item.get("metadata") if isinstance(item.get("metadata"), dict) else {}
            notification_project = item_metadata.get("notification_project") or target_project or source_project or "workbench"
            create_notification_record(
                title=item["title"],
                body=item.get("description", ""),
                project_id=notification_project,
                kind=kind,
                level="critical" if priority == "urgent" else "warning" if priority == "high" else "info",
                href="/" if notification_project == "workbench" else f"/projects/{notification_project}",
                event_key=f"work-item:{item['id']}",
                dedupe_seconds=0,
            )
        except Exception:
            # Notification delivery must never make creation of the primary work item fail.
            pass
    return item


def update_work_item_record(item_id: int, values: dict[str, Any]) -> dict[str, Any] | None:
    allowed = {"status", "priority", "description", "target_project", "metadata_json", "claimed_at", "claimed_run_id", "result_json", "completed_at", "last_error"}
    updates = [(key, value) for key, value in values.items() if key in allowed]
    if not updates:
        return next((item for item in list_work_items() if item["id"] == item_id), None)
    updates.append(("updated_at", now_iso()))
    connection = db_connection()
    try:
        assignments = ", ".join(f"{key} = ?" for key, _ in updates)
        cursor = connection.execute(
            f"UPDATE work_items SET {assignments} WHERE id = ?",
            [value for _, value in updates] + [item_id],
        )
        connection.commit()
        if cursor.rowcount == 0:
            return None
        row = connection.execute("SELECT * FROM work_items WHERE id = ?", (item_id,)).fetchone()
        return work_item_row(row)
    finally:
        connection.close()


def create_relation_record(
    *, from_type: str, from_id: str, to_type: str, to_id: str, relation_type: str, metadata: dict[str, Any] | None = None
) -> dict[str, Any]:
    connection = db_connection()
    try:
        cursor = connection.execute(
            """INSERT INTO relations
            (from_type, from_id, to_type, to_id, relation_type, metadata_json, created_at)
            VALUES (?, ?, ?, ?, ?, ?, ?)""",
            (from_type, str(from_id), to_type, str(to_id), relation_type, json.dumps(metadata or {}, ensure_ascii=False), now_iso()),
        )
        connection.commit()
        row = connection.execute("SELECT * FROM relations WHERE id = ?", (cursor.lastrowid,)).fetchone()
        return relation_row(row)
    finally:
        connection.close()


def list_relations(entity_id: str = "") -> list[dict[str, Any]]:
    connection = db_connection()
    try:
        if entity_id:
            rows = connection.execute(
                "SELECT * FROM relations WHERE from_id = ? OR to_id = ? ORDER BY created_at DESC LIMIT 200",
                (str(entity_id), str(entity_id)),
            ).fetchall()
        else:
            rows = connection.execute("SELECT * FROM relations ORDER BY created_at DESC LIMIT 200").fetchall()
        return [relation_row(row) for row in rows]
    finally:
        connection.close()


def list_inbox(status: str = "all") -> list[dict[str, Any]]:
    connection = db_connection()
    try:
        order = """
            ORDER BY
              CASE priority WHEN 'urgent' THEN 0 WHEN 'high' THEN 1 WHEN 'normal' THEN 2 WHEN 'low' THEN 3 ELSE 4 END,
              CASE WHEN status = 'inbox' AND due_at <> '' AND due_at < date('now') THEN 0 ELSE 1 END,
              CASE WHEN due_at = '' THEN 1 ELSE 0 END,
              due_at ASC,
              created_at DESC
        """
        if status == "all":
            rows = connection.execute(f"SELECT * FROM inbox {order}").fetchall()
        else:
            rows = connection.execute(
                f"SELECT * FROM inbox WHERE status = ? {order}", (status,)
            ).fetchall()
        return [inbox_row(row) for row in rows]
    finally:
        connection.close()


def inbox_summary() -> dict[str, int]:
    connection = db_connection()
    try:
        rows = connection.execute("SELECT status, COUNT(*) AS count FROM inbox GROUP BY status").fetchall()
        summary = {"inbox": 0, "done": 0, "archived": 0, "all": 0}
        for row in rows:
            summary[str(row["status"])] = int(row["count"])
            summary["all"] += int(row["count"])
        return summary
    finally:
        connection.close()


def create_inbox_record(*, content: str, kind: str = "note", tags: str = "", priority: str = "normal", source: str = "") -> dict[str, Any]:
    priority = priority.strip() or "normal"
    if priority not in {"urgent", "high", "normal", "low"}:
        priority = "normal"
    timestamp = now_iso()
    source = clip(source.strip(), 500)
    connection = db_connection()
    try:
        cursor = connection.execute(
            "INSERT INTO inbox (content, kind, tags, status, priority, source, created_at, updated_at) VALUES (?, ?, ?, 'inbox', ?, ?, ?, ?)",
            (clip(content.strip(), 20_000), kind.strip() or "note", tags.strip(), priority, source, timestamp, timestamp),
        )
        connection.commit()
        item_id = int(cursor.lastrowid)
    finally:
        connection.close()
    try:
        return triage_inbox_record(item_id)
    except Exception:
        # Triage is an enhancement to capture, not a reason to lose the user's input.
        return get_inbox_record(item_id) or {"id": item_id, "content": content, "kind": kind, "tags": tags, "status": "inbox"}


def normalized_inbox_text(value: str) -> str:
    return re.sub(r"[^a-z0-9\u4e00-\u9fff]+", "", (value or "").lower())


def extract_inbox_due(content: str) -> dict[str, str]:
    text = str(content or "")
    now = datetime.now(timezone.utc)
    due: datetime | None = None
    label = ""
    if "今天" in text:
        due = now
        label = "今天"
    elif "明天" in text:
        due = now + timedelta(days=1)
        label = "明天"
    elif "后天" in text:
        due = now + timedelta(days=2)
        label = "后天"
    else:
        relative = re.search(r"(\d{1,3})\s*[天日]\s*(?:内|以内|后)", text)
        if relative:
            days = int(relative.group(1))
            due = now + timedelta(days=days)
            label = f"{days} 天内" if "内" in relative.group(0) else f"{days} 天后"
    if due is None:
        full_date = re.search(r"(20\d{2})\s*[年./-]\s*(\d{1,2})\s*[月./-]\s*(\d{1,2})\s*日?", text)
        short_date = re.search(r"(?<!\d)(\d{1,2})\s*[月/]\s*(\d{1,2})\s*日?", text)
        try:
            if full_date:
                due = datetime(int(full_date.group(1)), int(full_date.group(2)), int(full_date.group(3)), tzinfo=timezone.utc)
                label = f"{full_date.group(1)}-{int(full_date.group(2)):02d}-{int(full_date.group(3)):02d}"
            elif short_date:
                month, day = int(short_date.group(1)), int(short_date.group(2))
                due = datetime(now.year, month, day, tzinfo=timezone.utc)
                if due.date() < now.date():
                    due = due.replace(year=now.year + 1)
                label = f"{month}月{day}日"
        except ValueError:
            due = None
    if due is None and "本周" in text:
        due = now + timedelta(days=6 - now.weekday())
        label = "本周"
    if due is None and "下周" in text:
        due = now + timedelta(days=7 - now.weekday() + 6)
        label = "下周"
    return {"due_at": due.date().isoformat(), "due_label": label} if due else {"due_at": "", "due_label": ""}


def extract_inbox_next_steps(content: str, classification: str = "note") -> dict[str, Any]:
    """Turn a captured note into small, reviewable next-step suggestions.

    This is deliberately deterministic.  It may split explicit bullets and
    imperative clauses, and otherwise supplies a conservative checklist for
    the detected kind.  It never executes a step or pretends that a guessed
    step came from the user.
    """
    text = str(content or "").strip()
    candidates: list[str] = []
    for raw_line in re.split(r"\r?\n", text):
        line = re.sub(r"^\s*(?:[-*•]|\d+[.)、])\s*", "", raw_line).strip()
        if not line:
            continue
        for part in re.split(r"[。！？!?；;]+", line):
            part = re.sub(r"^\s*(?:下一步|接下来|然后|再|并且|以及)[:：]?\s*", "", part).strip()
            if 3 <= len(part) <= 160:
                candidates.append(part)

    # A single sentence often contains a useful sequence: “先…再…”。
    if len(candidates) <= 1:
        sequence = re.split(r"\s*(?:先|然后|接着|再|之后)\s*", text)
        for part in sequence:
            part = part.strip(" ，,：:。！？!?；;")
            if 3 <= len(part) <= 160:
                candidates.append(part)

    imperative_leads = ("确认", "补充", "查看", "打开", "记录", "明确", "整理", "交给", "检查", "先", "需要", "请", "跟进", "联系", "验证", "研究", "学习", "阅读", "设计", "写")
    explicit = [item for item in candidates if item.startswith(imperative_leads)]
    steps: list[str] = []
    for item in explicit:
        normalized = re.sub(r"\s+", " ", item).strip()
        if normalized and normalized not in steps:
            steps.append(normalized)
        if len(steps) >= 3:
            break

    if steps:
        return {"steps": steps, "source": "captured_text"}

    defaults = {
        "task": ["确认负责人和截止时间", "完成后回写结果或阻塞原因"],
        "research": ["明确研究问题和时间范围", "补充来源并记录结论与不确定性"],
        "document": ["确认交付对象和格式", "补齐材料并检查来源覆盖"],
        "link": ["打开来源并判断是否值得保留", "记录要点或交给知识库沉淀"],
        "alert": ["确认影响范围和数据时间", "查看来源并记录处理结果"],
        "idea": ["写清关键假设", "选择一个最小验证动作"],
    }
    return {"steps": defaults.get(classification, ["补充这条记录的背景和期望结果"]), "source": "conservative_template"}


def inbox_duplicate_match(item_id: int, content: str) -> dict[str, Any]:
    normalized = normalized_inbox_text(content)
    if len(normalized) < 8:
        return {"id": 0, "score": 0, "reason": ""}
    connection = db_connection()
    try:
        rows = connection.execute(
            "SELECT id, content FROM inbox WHERE id <> ? AND status = 'inbox' ORDER BY id DESC LIMIT 120",
            (item_id,),
        ).fetchall()
    finally:
        connection.close()
    best: tuple[float, int, str] = (0, 0, "")
    for row in rows:
        other = normalized_inbox_text(row["content"])
        if not other:
            continue
        score = difflib.SequenceMatcher(None, normalized, other).ratio()
        if score > best[0]:
            best = (score, int(row["id"]), str(row["content"]))
    threshold = 0.88 if len(normalized) < 30 else 0.74
    return {"id": best[1] if best[0] >= threshold else 0, "score": round(best[0], 3), "reason": best[2] if best[0] >= threshold else ""}


def inbox_learned_classification(content: str, item_id: int = 0) -> dict[str, Any] | None:
    """Use confirmed local labels as a soft hint; keyword rules remain the fallback."""
    tokens = knowledge_tokens(content)
    if len(tokens) < 2:
        return None
    connection = db_connection()
    try:
        rows = connection.execute(
            """SELECT f.accepted, i.content FROM inbox_classification_feedback f
            JOIN inbox i ON i.id = f.inbox_id WHERE f.inbox_id <> ? ORDER BY f.created_at DESC LIMIT 120""",
            (item_id,),
        ).fetchall()
    finally:
        connection.close()
    best: tuple[float, str] = (0.0, "")
    for row in rows:
        other_tokens = knowledge_tokens(str(row["content"] or ""))
        score = len(tokens.intersection(other_tokens)) / max(1, len(tokens.union(other_tokens)))
        if score > best[0]:
            best = (score, str(row["accepted"] or ""))
    if best[0] < 0.18 or best[1] not in {"note", "task", "link", "idea", "alert", "document", "research"}:
        return None
    return {"classification": best[1], "confidence": round(min(0.92, 0.58 + best[0] * 0.7), 3), "similarity": round(best[0], 3), "source": "confirmed_history"}


def infer_inbox_triage(content: str, kind: str, tags: str, item_id: int) -> dict[str, Any]:
    text = str(content or "").strip()
    lowered = text.lower()
    explicit_kind = kind if kind in {"note", "task", "link", "idea"} else "note"
    kind_rules = [
        ("alert", ("告警", "异常", "报错", "宕机", "服务器", "磁盘", "内存", "nginx", "余额", "额度", "到期")),
        ("document", ("prd", "文档", "报告", "方案", "周报", "会议纪要", "pdf", "word", "ppt")),
        ("research", ("研究", "调研", "查一下", "资料", "竞品", "对比", "爬", "抓取", "来源")),
        ("idea", ("想法", "商机", "创业", "靠谱不靠谱", "做点事", "可行性", "机会")),
        ("task", ("待办", "任务", "截止", "完成", "处理", "跟进", "提醒", "需要")),
        ("link", ("http://", "https://", "www.")),
    ]
    classification = explicit_kind
    confidence = 0.76 if explicit_kind != "note" else 0.46
    evidence: list[str] = []
    if explicit_kind == "note":
        for candidate, words in kind_rules:
            matched = [word for word in words if word.lower() in lowered]
            if matched:
                classification = candidate
                confidence = min(0.94, 0.62 + 0.06 * len(matched))
                evidence = matched[:4]
                break
        learned = inbox_learned_classification(text, item_id)
        if learned and learned["confidence"] > confidence:
            classification = learned["classification"]
            confidence = learned["confidence"]
            evidence = [f"历史确认相似度 {learned['similarity']}"]
    due = extract_inbox_due(text)
    duplicate = inbox_duplicate_match(item_id, text)
    next_steps = extract_inbox_next_steps(text, classification)
    allowed_targets = {edge["to"] for edge in PROJECT_LINKS if edge["from"] == "inbox"}
    route_specs = {
        "knowledge": ("note_capture", "这条内容更适合沉淀为可检索笔记。", ("知识", "笔记", "沉淀", "方法", "总结")),
        "crawl4ai": ("research_task", "这条内容需要外部资料或来源证据。", ("研究", "调研", "资料", "竞品", "爬", "抓取", "网页")),
        "idea-analysis": ("idea_review", "这条内容包含想法或商机，需要做可行性和最小验证。", ("想法", "商机", "创业", "机会", "靠谱不靠谱", "可行性")),
        "doc-factory": ("document_task", "这条内容指向文档、报告或 PRD 交付。", ("prd", "文档", "报告", "方案", "周报", "纪要")),
        "server": ("incident_to_task", "这条内容可能是服务器或服务异常，交给运维 Agent 排查。", ("服务器", "主机", "磁盘", "内存", "nginx", "宕机", "部署")),
        "sub2api": ("quota_alert", "这条内容可能涉及账户额度、余额或到期风险。", ("sub2api", "余额", "额度", "订阅", "key", "到期")),
        "market": ("market_research", "这条内容涉及股票、行情或量化研究。", ("股票", "行情", "量化", "选股", "涨跌", "因子")),
    }
    routes: list[dict[str, Any]] = []
    for target, (route_kind, reason, words) in route_specs.items():
        if target not in allowed_targets:
            continue
        score = 0.0
        if classification == "note" and target == "knowledge": score += 0.58
        if classification == "research" and target == "crawl4ai": score += 0.66
        if classification == "idea" and target == "idea-analysis": score += 0.70
        if classification == "document" and target == "doc-factory": score += 0.70
        if classification == "alert" and target in {"server", "sub2api"}: score += 0.58
        if classification == "task" and target in {"doc-factory", "crawl4ai"}: score += 0.18
        matches = [word for word in words if word.lower() in lowered]
        # A single note can have two downstream stages (for example, research
        # first and document delivery second). Keep both candidates instead of
        # forcing the classifier to throw away the second intent.
        if target == "crawl4ai" and any(word in lowered for word in ("研究", "调研", "竞品", "资料", "网页", "抓取")):
            score += 0.36
        if target == "doc-factory" and any(word in lowered for word in ("报告", "文档", "prd", "方案", "周报", "纪要")):
            score += 0.36
        score += min(0.30, len(matches) * 0.10)
        if score >= 0.28:
            routes.append({"target_project": target, "route_kind": route_kind, "reason": reason, "confidence": round(min(score, 0.98), 3), "matched": matches[:5]})
    routes.sort(key=lambda item: item["confidence"], reverse=True)
    classification_label = {
        "task": "待办",
        "idea": "想法",
        "research": "研究",
        "document": "文档",
        "alert": "告警",
        "link": "链接",
        "note": "笔记",
    }.get(classification, classification)
    return {
        "classification": classification,
        "classification_confidence": round(confidence, 3),
        "classification_label": classification_label,
        "evidence": evidence,
        "due_at": due["due_at"],
        "due_label": due["due_label"],
        "duplicate_of": duplicate["id"],
        "duplicate_score": duplicate["score"],
        "duplicate_preview": clip(duplicate["reason"], 180) if duplicate["id"] else "",
        "next_steps": next_steps["steps"],
        "next_steps_source": next_steps["source"],
        "routes": routes[:3],
        "summary": f"判断为{classification_label}" + (f"，{due['due_label']}前处理" if due["due_label"] else ""),
        "tags": [tag.strip() for tag in re.split(r"[,，\s]+", tags or "") if tag.strip()][:12],
    }


def analyze_inbox_record(item_id: int, *, triage_run_id: str = "") -> dict[str, Any]:
    item = get_inbox_record(item_id)
    if not item:
        raise HTTPException(404, "收件箱条目不存在")
    analysis = infer_inbox_triage(item["content"], item.get("kind", "note"), item.get("tags", ""), item_id)
    now = now_iso()
    connection = db_connection()
    try:
        connection.execute("DELETE FROM inbox_route_candidates WHERE inbox_id = ? AND status = 'suggested'", (item_id,))
        existing = {
            row["target_project"]: row["status"]
            for row in connection.execute(
                "SELECT target_project, status FROM inbox_route_candidates WHERE inbox_id = ?", (item_id,)
            ).fetchall()
        }
        for route in analysis["routes"]:
            if route["target_project"] in existing:
                continue
            connection.execute(
                """INSERT INTO inbox_route_candidates
                (inbox_id, target_project, route_kind, reason, confidence, status, metadata_json, created_at, updated_at)
                VALUES (?, ?, ?, ?, ?, 'suggested', ?, ?, ?)""",
                (item_id, route["target_project"], route["route_kind"], route["reason"], route["confidence"], json.dumps({"matched": route.get("matched", [])}, ensure_ascii=False), now, now),
            )
        accepted = connection.execute(
            "SELECT COUNT(*) FROM inbox_route_candidates WHERE inbox_id = ? AND status = 'accepted'", (item_id,)
        ).fetchone()[0]
        route_status = "accepted" if accepted else "suggested" if analysis["routes"] else "none"
        connection.execute(
            """UPDATE inbox SET due_at = ?, classification = ?, classification_confidence = ?, duplicate_of = ?,
            analysis_json = ?, analyzed_at = ?, route_status = ?, triage_run_id = ?, updated_at = ? WHERE id = ?""",
            (analysis["due_at"], analysis["classification"], analysis["classification_confidence"], analysis["duplicate_of"], json.dumps(analysis, ensure_ascii=False), now, route_status, triage_run_id, now, item_id),
        )
        connection.commit()
    finally:
        connection.close()
    return get_inbox_record(item_id) or item


def triage_inbox_record(item_id: int) -> dict[str, Any]:
    item = get_inbox_record(item_id)
    if not item:
        raise HTTPException(404, "收件箱条目不存在")
    run = create_agent_run_record(
        project_id="inbox",
        kind="triage",
        title=f"整理收件箱：{clip(item['content'], 90)}",
        request={"inbox_id": item_id, "content": item["content"], "kind": item.get("kind", "note")},
        max_attempts=2,
    )
    update_agent_run_record(run["id"], status="running")
    add_agent_run_event(run["id"], "started", "收件箱 Agent 开始分类、提取截止时间、检查重复和生成交接候选。")
    try:
        result = analyze_inbox_record(item_id, triage_run_id=run["id"])
        run_result = {"inbox_id": item_id, "classification": result.get("classification"), "routes": result.get("routes", []), "duplicate_of": result.get("duplicate_of", 0), "due_at": result.get("due_at", ""), "next_steps": result.get("next_steps", []), "next_steps_source": result.get("next_steps_source", "")}
        updated = update_agent_run_record(run["id"], status="succeeded", result=run_result, error="") or run
        add_agent_run_event(run["id"], "succeeded", "收件箱 Agent 已完成整理。", level="success", metadata=run_result)
        # 低风险自动归档：高置信度、纯记录、无截止时间、无交接路由、无重复的
        # 条目直接完成，避免琐碎记录长期占用待办；其余保留待人工处理。
        confidence = float(result.get("classification_confidence") or 0)
        if (
            confidence >= 0.9
            and str(result.get("classification") or "note") == "note"
            and not result.get("due_at")
            and not result.get("routes")
            and not result.get("duplicate_of")
        ):
            connection = db_connection()
            try:
                connection.execute(
                    "UPDATE inbox SET status = 'done', metadata = json_set(COALESCE(metadata, '{}'), '$.auto_archived', json_object('reason', 'high_confidence_note', 'confidence', ?, 'at', ?)) WHERE id = ?",
                    (confidence, now_iso(), item_id),
                )
                connection.commit()
            finally:
                connection.close()
            add_agent_run_event(run["id"], "auto_archived", "高置信度纯记录，已自动完成归档。", level="info", metadata={"confidence": confidence})
            result["auto_archived"] = True
        return result
    except Exception as exc:
        update_agent_run_record(run["id"], status="failed", error=str(exc))
        add_agent_run_event(run["id"], "failed", f"收件箱整理失败：{exc}", level="error")
        raise


def safe_filename(value: str, fallback: str = "output") -> str:
    cleaned = re.sub(r"[^\w\-\u4e00-\u9fff]+", "-", value, flags=re.UNICODE).strip("-")
    return (cleaned or fallback)[:80]


def knowledge_files() -> list[Path]:
    return sorted(KNOWLEDGE_DIR.rglob("*.md"), key=lambda path: path.stat().st_mtime, reverse=True)


def knowledge_search(query: str = "") -> list[dict[str, Any]]:
    results = []
    terms = [term for term in re.findall(r"[a-zA-Z0-9][a-zA-Z0-9_-]{1,}|[\u4e00-\u9fff]{2,}", query.lower())]
    for path in knowledge_files():
        try:
            content = path.read_text(encoding="utf-8")
        except (OSError, UnicodeDecodeError):
            continue
        haystack = f"{path.stem}\n{content}".lower()
        score = sum(haystack.count(term) for term in terms) if terms else 0
        if terms and not score:
            continue
        first_line = next((line.lstrip("# ").strip() for line in content.splitlines() if line.strip()), path.stem)
        results.append({
            "name": path.stem,
            "path": str(path.relative_to(KNOWLEDGE_DIR)),
            "title": first_line,
            "preview": clip(content, 420),
            "chars": len(content),
            "updated_at": datetime.fromtimestamp(path.stat().st_mtime, tz=timezone.utc).isoformat(),
            "score": score,
        })
    results.sort(key=lambda item: (item["score"], item["updated_at"]), reverse=True)
    return results[:50]


# ---------- 语义向量检索（embedding 服务经本机反向隧道调用） ----------
EMBEDDING_URL = os.getenv("WORKBENCH_EMBEDDING_URL", "").strip()
_embedding_health: dict[str, Any] = {"ok": False, "checked_at": 0.0, "last_error": ""}


def embedding_available() -> bool:
    """embedding 服务是否可用（30 秒内缓存探测结果）。"""
    if not EMBEDDING_URL:
        return False
    now = time.time()
    if now - float(_embedding_health.get("checked_at", 0.0)) < 30:
        return bool(_embedding_health.get("ok"))
    try:
        with httpx.Client(timeout=5) as client:
            response = client.get(f"{EMBEDDING_URL}/health")
        _embedding_health["ok"] = response.status_code == 200
    except Exception as exc:  # noqa: BLE001
        _embedding_health["ok"] = False
        _embedding_health["last_error"] = str(exc)
    _embedding_health["checked_at"] = now
    return bool(_embedding_health.get("ok"))


def embed_texts(texts: list[str]) -> list[list[float]] | None:
    """调用本机 embedding 服务；失败返回 None（调用方降级关键词）。"""
    if not texts:
        return []
    try:
        with httpx.Client(timeout=40) as client:
            response = client.post(f"{EMBEDDING_URL}/embed", json={"texts": texts})
        if response.status_code != 200:
            return None
        return response.json().get("vectors")
    except Exception:  # noqa: BLE001
        return None


def _ensure_knowledge_vectors_table() -> None:
    connection = db_connection()
    try:
        connection.execute(
            """CREATE TABLE IF NOT EXISTS knowledge_vectors (
                path TEXT PRIMARY KEY,
                dim INTEGER NOT NULL DEFAULT 512,
                vector BLOB NOT NULL,
                text_hash TEXT NOT NULL DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT ''
            )"""
        )
        connection.commit()
    finally:
        connection.close()


def _embedding_text_for_note(path: Path, content: str) -> str:
    title = next((line.lstrip("# ").strip() for line in content.splitlines() if line.strip()), path.stem)
    body = re.sub(r"\s+", " ", content)[:1600]
    return f"{path.stem}\n{title}\n{body}"


def ensure_knowledge_vectors(force: bool = False) -> dict[str, Any]:
    """为缺少向量（或内容变化）的知识文件生成向量，批量调 embedding 服务。"""
    if not embedding_available():
        return {"ok": False, "indexed": 0, "reason": "embedding 服务不可用"}
    _ensure_knowledge_vectors_table()
    paths = knowledge_files()
    connection = db_connection()
    indexed = skipped = 0
    try:
        for path in paths:
            try:
                content = path.read_text(encoding="utf-8")
            except (OSError, UnicodeDecodeError):
                continue
            text = _embedding_text_for_note(path, content)
            digest = hashlib.sha256(text.encode("utf-8")).hexdigest()
            row = connection.execute("SELECT text_hash FROM knowledge_vectors WHERE path = ?", (str(path),)).fetchone()
            if not force and row and row["text_hash"] == digest:
                skipped += 1
                continue
            vectors = embed_texts([text]) or []
            if not vectors:
                break  # embedding 服务暂不可用，停止本次索引
            vector_bytes = json.dumps(vectors[0]).encode("utf-8")
            connection.execute(
                """INSERT INTO knowledge_vectors(path, dim, vector, text_hash, updated_at)
                   VALUES(?, ?, ?, ?, ?)
                   ON CONFLICT(path) DO UPDATE SET vector=excluded.vector, text_hash=excluded.text_hash, updated_at=excluded.updated_at""",
                (str(path), len(vectors[0]), vector_bytes, digest, now_iso()),
            )
            indexed += 1
        connection.commit()
    finally:
        connection.close()
    return {"ok": True, "indexed": indexed, "skipped": skipped, "total": len(paths)}


def _cosine_similarity(a: list[float], b: list[float]) -> float:
    if not a or len(a) != len(b):
        return 0.0
    dot = sum(x * y for x, y in zip(a, b))
    norm_a = math.sqrt(sum(x * x for x in a))
    norm_b = math.sqrt(sum(y * y for y in b))
    if norm_a == 0.0 or norm_b == 0.0:
        return 0.0
    return dot / (norm_a * norm_b)


def knowledge_semantic_scores(query: str) -> dict[str, float]:
    """返回 {绝对路径: 余弦相似度}。query 语义向量 vs 库内全部向量。"""
    if not embedding_available():
        return {}
    query_vectors = embed_texts([query])
    if not query_vectors:
        return {}
    query_vector = query_vectors[0]
    _ensure_knowledge_vectors_table()
    connection = db_connection()
    scores: dict[str, float] = {}
    try:
        rows = connection.execute("SELECT path, vector FROM knowledge_vectors").fetchall()
        for row in rows:
            try:
                stored = json.loads(row["vector"])
            except (json.JSONDecodeError, TypeError):
                continue
            if len(stored) != len(query_vector):
                continue
            scores[str(row["path"])] = _cosine_similarity(query_vector, stored)
    finally:
        connection.close()
    return scores


def knowledge_hybrid_search(query: str = "", limit: int = 50) -> list[dict[str, Any]]:
    """关键词 + 语义向量混合检索；embedding 不可用时退化为纯关键词。"""
    keyword = knowledge_search(query)
    if not query.strip() or not embedding_available():
        return keyword[:limit]
    ensure_knowledge_vectors()
    semantic = knowledge_semantic_scores(query)
    if not semantic:
        return keyword[:limit]
    max_sim = max(semantic.values()) or 1.0
    merged: dict[str, dict[str, Any]] = {}
    for note in keyword:
        absolute = str(KNOWLEDGE_DIR / note["path"])
        merged[absolute] = {**note, "__semantic": semantic.get(absolute, 0.0)}
    for path_str, sim in semantic.items():
        if path_str in merged:
            continue
        path = Path(path_str)
        if not path.exists():
            continue
        try:
            content = path.read_text(encoding="utf-8")
        except (OSError, UnicodeDecodeError):
            continue
        title = next((line.lstrip("# ").strip() for line in content.splitlines() if line.strip()), path.stem)
        merged[path_str] = {
            "name": path.stem,
            "path": str(path.relative_to(KNOWLEDGE_DIR)),
            "title": title,
            "preview": clip(content, 420),
            "chars": len(content),
            "updated_at": datetime.fromtimestamp(path.stat().st_mtime, tz=timezone.utc).isoformat(),
            "score": 0,
            "__semantic": sim,
        }
    for item in merged.values():
        item["score"] = item.get("score", 0) + 5.0 * item.get("__semantic", 0.0) / max_sim
        item.pop("__semantic", None)
    ranked = sorted(merged.values(), key=lambda item: (item["score"], item["updated_at"]), reverse=True)
    return ranked[:limit]


def parse_obsidian_markdown(text: str, path: Path) -> dict[str, Any]:
    frontmatter: dict[str, Any] = {}
    body = text
    if text.startswith("---"):
        match = re.match(r"^---\s*\n(.*?)\n---\s*(?:\n|$)", text, flags=re.DOTALL)
        if match:
            for line in match.group(1).splitlines():
                key, separator, value = line.partition(":")
                if not separator:
                    continue
                key = key.strip()
                value = value.strip()
                if value.startswith("[") and value.endswith("]"):
                    value = [item.strip().strip("'\"") for item in value[1:-1].split(",") if item.strip()]
                elif value.lower() in {"true", "false"}:
                    value = value.lower() == "true"
                else:
                    value = value.strip("'\"")
                frontmatter[key] = value
            body = text[match.end():]
    title_match = re.search(r"^#\s+(.+?)\s*$", body, flags=re.MULTILINE)
    title = (title_match.group(1).strip() if title_match else path.stem).strip()
    links = []
    seen_links: set[str] = set()
    for raw in re.findall(r"\[\[([^\]|#]+)(?:#[^\]|]+)?(?:\|[^\]]+)?\]\]", body):
        target = raw.strip()
        if target and target not in seen_links:
            seen_links.add(target)
            links.append(target)
    tags = []
    frontmatter_tags = frontmatter.get("tags", [])
    if isinstance(frontmatter_tags, str):
        frontmatter_tags = [frontmatter_tags]
    for tag in [*(frontmatter_tags if isinstance(frontmatter_tags, list) else []), *re.findall(r"(?<![\w])#([\w\u4e00-\u9fff/-]+)", body)]:
        normalized = str(tag).strip().lstrip("#")
        if normalized and normalized not in tags:
            tags.append(normalized)
    preview = re.sub(r"\s+", " ", body).strip()
    return {
        "title": title[:240],
        "frontmatter": frontmatter,
        "links": links[:80],
        "tags": tags[:80],
        "preview": clip(preview, 420),
    }


def obsidian_note_paths() -> list[Path]:
    if not OBSIDIAN_VAULT_DIR.is_dir():
        return []
    paths = []
    for path in OBSIDIAN_VAULT_DIR.rglob("*.md"):
        if ".obsidian" in path.parts:
            continue
        try:
            resolved = path.resolve()
            resolved.relative_to(OBSIDIAN_VAULT_DIR.resolve())
        except (OSError, ValueError):
            continue
        paths.append(path)
    return sorted(paths, key=lambda item: item.stat().st_mtime, reverse=True)


def obsidian_note_row(row: sqlite3.Row) -> dict[str, Any]:
    note = {key: row[key] for key in row.keys()}
    note.pop("search_text", None)
    note["frontmatter"] = decode_json_column(note.pop("frontmatter_json", "{}"))
    note["links"] = json.loads(note.pop("links_json", "[]") or "[]")
    note["tags"] = json.loads(note.pop("tags_json", "[]") or "[]")
    note["updated_at"] = datetime.fromtimestamp(float(note.get("mtime") or 0), tz=timezone.utc).isoformat() if note.get("mtime") else ""
    note["vault_path"] = str(OBSIDIAN_VAULT_DIR)
    return note


def obsidian_backlink_count(path: str, title: str, rows: list[sqlite3.Row]) -> int:
    targets = {str(path), str(Path(path).with_suffix("")), str(Path(path).stem), str(title)}
    count = 0
    for row in rows:
        try:
            links = json.loads(row["links_json"] or "[]")
        except json.JSONDecodeError:
            links = []
        if any(str(link).strip() in targets or Path(str(link).strip()).stem in targets for link in links):
            count += 1
    return count


def obsidian_index_vault() -> dict[str, Any]:
    started = now_iso()
    paths = obsidian_note_paths()
    if not OBSIDIAN_VAULT_DIR.is_dir():
        return {"ok": False, "vault_path": str(OBSIDIAN_VAULT_DIR), "error": "Obsidian Vault 不存在或不可读取", "indexed": 0}
    indexed_paths: set[str] = set()
    changed = 0
    connection = db_connection()
    try:
        for path in paths:
            relative = str(path.relative_to(OBSIDIAN_VAULT_DIR))
            indexed_paths.add(relative)
            try:
                stat = path.stat()
                text = path.read_text(encoding="utf-8", errors="replace")
            except OSError:
                continue
            parsed = parse_obsidian_markdown(text, path)
            content_hash = hashlib.sha256(text.encode("utf-8", errors="replace")).hexdigest()
            previous = connection.execute("SELECT content_hash FROM obsidian_notes WHERE path = ?", (relative,)).fetchone()
            if not previous or previous["content_hash"] != content_hash:
                changed += 1
            connection.execute(
                """INSERT INTO obsidian_notes
                (path, title, folder, size, mtime, preview, search_text, frontmatter_json, links_json, tags_json, content_hash, indexed_at)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                ON CONFLICT(path) DO UPDATE SET title=excluded.title, folder=excluded.folder, size=excluded.size,
                mtime=excluded.mtime, preview=excluded.preview, search_text=excluded.search_text, frontmatter_json=excluded.frontmatter_json,
                links_json=excluded.links_json, tags_json=excluded.tags_json, content_hash=excluded.content_hash,
                indexed_at=excluded.indexed_at""",
                (relative, parsed["title"], str(Path(relative).parent) if Path(relative).parent != Path(".") else "", stat.st_size, stat.st_mtime, parsed["preview"], clip(text, 80_000), json.dumps(parsed["frontmatter"], ensure_ascii=False), json.dumps(parsed["links"], ensure_ascii=False), json.dumps(parsed["tags"], ensure_ascii=False), content_hash, started),
            )
        existing = {row["path"] for row in connection.execute("SELECT path FROM obsidian_notes").fetchall()}
        removed = existing - indexed_paths
        if removed:
            connection.executemany("DELETE FROM obsidian_notes WHERE path = ?", [(path,) for path in removed])
        summary = {"indexed": len(indexed_paths), "changed": changed, "removed": len(removed), "scanned_at": started}
        connection.execute("INSERT INTO obsidian_index_meta(key, value) VALUES('last_scan', ?) ON CONFLICT(key) DO UPDATE SET value=excluded.value", (json.dumps(summary, ensure_ascii=False),))
        connection.commit()
    finally:
        connection.close()
    return {"ok": True, "vault_path": str(OBSIDIAN_VAULT_DIR), **summary}


def obsidian_status() -> dict[str, Any]:
    connection = db_connection()
    try:
        count = int(connection.execute("SELECT COUNT(*) FROM obsidian_notes").fetchone()[0])
        latest = connection.execute("SELECT MAX(indexed_at) FROM obsidian_notes").fetchone()[0] or ""
        local_today = datetime.now().astimezone().replace(hour=0, minute=0, second=0, microsecond=0).timestamp()
        today_count = int(connection.execute("SELECT COUNT(*) FROM obsidian_notes WHERE mtime >= ?", (local_today,)).fetchone()[0])
        moc_count = int(connection.execute("SELECT COUNT(*) FROM obsidian_notes WHERE folder LIKE '03 MOC%' ").fetchone()[0])
        meta = connection.execute("SELECT value FROM obsidian_index_meta WHERE key = 'last_scan'").fetchone()
        last_scan = decode_json_column(meta[0]) if meta else {}
        return {"available": OBSIDIAN_VAULT_DIR.is_dir(), "vault_path": str(OBSIDIAN_VAULT_DIR), "note_count": count, "today_note_count": today_count, "moc_count": moc_count, "last_indexed_at": latest, "last_scan": last_scan}
    finally:
        connection.close()


def obsidian_index_rows() -> list[sqlite3.Row]:
    connection = db_connection()
    try:
        return connection.execute("SELECT * FROM obsidian_notes ORDER BY mtime DESC LIMIT 2000").fetchall()
    finally:
        connection.close()


def obsidian_search(query: str = "", limit: int = 40, since_timestamp: float = 0) -> list[dict[str, Any]]:
    rows = [row for row in obsidian_index_rows() if not since_timestamp or float(row["mtime"] or 0) >= since_timestamp]
    terms = [term for term in re.findall(r"[a-zA-Z0-9][a-zA-Z0-9_-]{1,}|[\u4e00-\u9fff]{2,}", (query or "").lower())]
    ranked: list[tuple[int, float, sqlite3.Row]] = []
    for row in rows:
        haystack = f"{row['title']}\n{row['path']}\n{row['preview']}\n{row['search_text']}\n{row['tags_json']}\n{row['links_json']}".lower()
        score = sum(haystack.count(term) for term in terms) if terms else 0
        if terms and not score:
            continue
        ranked.append((score, float(row["mtime"] or 0), row))
    ranked.sort(key=lambda item: (item[0], item[1]), reverse=True)
    all_rows = rows
    results = []
    for score, _, row in ranked[: max(1, min(limit, 100))]:
        note = obsidian_note_row(row)
        note["score"] = score
        note["backlinks"] = obsidian_backlink_count(note["path"], note["title"], all_rows)
        results.append(note)
    return results


def obsidian_related(path: str, limit: int = 8) -> list[dict[str, Any]]:
    rows = obsidian_index_rows()
    target_row = next((row for row in rows if str(row["path"]) == str(path)), None)
    if not target_row:
        return []
    target = obsidian_note_row(target_row)
    target_terms = set(re.findall(r"[a-zA-Z0-9][a-zA-Z0-9_-]{1,}|[\u4e00-\u9fff]{2,}", f"{target['title']} {target['preview']}".lower()))
    target_terms = {term for term in target_terms if len(term) >= 2}
    target_tags = {str(tag).lower() for tag in target.get("tags", [])}
    target_links = {str(link).strip() for link in target.get("links", [])}
    related: list[dict[str, Any]] = []
    for row in rows:
        if str(row["path"]) == str(path):
            continue
        note = obsidian_note_row(row)
        note_terms = set(re.findall(r"[a-zA-Z0-9][a-zA-Z0-9_-]{1,}|[\u4e00-\u9fff]{2,}", f"{note['title']} {note['preview']}".lower()))
        shared_tags = target_tags & {str(tag).lower() for tag in note.get("tags", [])}
        shared_terms = target_terms & note_terms
        link_match = any(
            str(link).strip() in {str(target["path"]), str(Path(target["path"]).with_suffix("")), str(Path(target["path"]).stem), str(target["title"])}
            for link in note.get("links", [])
        ) or any(str(link).strip() in {str(note["path"]), str(Path(note["path"]).with_suffix("")), str(Path(note["path"]).stem), str(note["title"])} for link in target_links)
        score = len(shared_tags) * 5 + min(len(shared_terms), 5) + (8 if link_match else 0)
        if score <= 0:
            continue
        reasons = []
        if link_match:
            reasons.append("已有双链")
        if shared_tags:
            reasons.append(f"共享标签 {', '.join(sorted(shared_tags)[:2])}")
        if shared_terms:
            reasons.append("主题词相近")
        note["relation_score"] = score
        note["relation_reason"] = " · ".join(reasons)
        note["backlinks"] = obsidian_backlink_count(note["path"], note["title"], rows)
        related.append(note)
    related.sort(key=lambda item: (item.get("relation_score", 0), item.get("backlinks", 0)), reverse=True)
    return related[: max(1, min(limit, 20))]


def obsidian_moc_suggestions() -> dict[str, Any]:
    rows = obsidian_index_rows()
    moc_notes = [row for row in rows if str(row["folder"] or "").startswith("03 MOC")]
    orphan_notes = []
    tag_counts: dict[str, int] = {}
    for row in rows:
        note = obsidian_note_row(row)
        for tag in note.get("tags", []):
            tag_counts[str(tag)] = tag_counts.get(str(tag), 0) + 1
        if not str(row["folder"] or "").startswith("03 MOC") and obsidian_backlink_count(note["path"], note["title"], rows) == 0:
            orphan_notes.append({"path": note["path"], "title": note["title"], "folder": note.get("folder", ""), "reason": "没有反向链接，可考虑补充到 MOC"})
    orphan_notes.sort(key=lambda item: item["title"])
    return {
        "moc_count": len(moc_notes),
        "orphan_count": len(orphan_notes),
        "orphan_notes": orphan_notes[:12],
        "top_tags": [{"tag": tag, "count": count} for tag, count in sorted(tag_counts.items(), key=lambda item: (-item[1], item[0]))[:12]],
    }


def knowledge_inbox_candidates() -> list[dict[str, Any]]:
    candidates = []
    allowed = {"note", "idea", "research", "document", "link"}
    for item in list_inbox("inbox"):
        classification = item.get("classification") or item.get("kind") or "note"
        if classification not in allowed and item.get("route_status") != "accepted":
            continue
        first_line = next((line.strip() for line in str(item.get("content", "")).splitlines() if line.strip()), "未命名内容")
        title = clip(first_line, 80)
        existing = knowledge_search(title)[:2] if len(title) >= 2 else []
        candidates.append({
            "id": item["id"],
            "content": item.get("content", ""),
            "title": title,
            "classification": classification,
            "priority": item.get("priority", "normal"),
            "priority_label": item.get("priority_label", "普通"),
            "created_at": item.get("created_at", ""),
            "due_at": item.get("due_at", ""),
            "is_overdue": item.get("is_overdue", False),
            "route_status": item.get("route_status", "none"),
            "existing_notes": [{"title": note.get("title"), "path": note.get("path")} for note in existing],
        })
    return candidates[:30]


def sync_inbox_to_obsidian(item_id: int, *, content: str = "", title_override: str = "") -> dict[str, Any]:
    item = get_inbox_record(item_id)
    if not item:
        raise HTTPException(404, "收件箱条目不存在")
    if not OBSIDIAN_VAULT_DIR.is_dir():
        raise HTTPException(409, "Obsidian Vault 不可用")
    for artifact in list_artifacts("knowledge"):
        metadata = artifact.get("metadata") if isinstance(artifact.get("metadata"), dict) else {}
        if artifact.get("kind") == "obsidian_inbox_note" and str(metadata.get("source_inbox_id")) == str(item_id):
            return {"synced": True, "already_exists": True, "artifact": artifact, "path": artifact.get("path", ""), "message": "这条收件箱内容已经写入 Obsidian Inbox。"}
    inbox_dir = OBSIDIAN_VAULT_DIR / "00 Inbox"
    inbox_dir.mkdir(parents=True, exist_ok=True)
    selected_content = str(content or item.get("content", "")).strip()
    if not selected_content:
        raise HTTPException(400, "写入内容不能为空")
    title = title_override.strip() or next((line.strip() for line in selected_content.splitlines() if line.strip()), f"Workbench 收件箱 {item_id}")
    title = clip(title, 70)
    filename = safe_filename(f"{title}-{item_id}", f"workbench-inbox-{item_id}") + ".md"
    path = inbox_dir / filename
    suffix = 2
    while path.exists():
        path = inbox_dir / f"{safe_filename(title, f'workbench-inbox-{item_id}')}-{item_id}-{suffix}.md"
        suffix += 1
    tags = [tag.strip().lstrip("#") for tag in re.split(r"[,，\s]+", item.get("tags", "")) if tag.strip()]
    tag_slugs = [re.sub(r"[^\w\u4e00-\u9fff/-]+", "-", tag).strip("-") for tag in ["workbench/inbox", *tags]]
    tag_lines = "\n".join(f"  - {slug}" for slug in tag_slugs)
    body = (
        "---\n"
        "source: workbench\n"
        f"source_inbox_id: {item_id}\n"
        f"captured_at: {item.get('created_at', now_iso())}\n"
        "tags:\n"
        f"{tag_lines}\n"
        "---\n\n"
        f"# {title}\n\n"
        f"> 来源：Workbench 快速收件箱 #{item_id}\n\n"
        f"{selected_content}\n"
    )
    path.write_text(body, encoding="utf-8")
    artifact = register_artifact_safely(
        project_id="knowledge",
        name=path.name,
        path=str(path),
        kind="obsidian_inbox_note",
        metadata={"title": title, "source_inbox_id": item_id, "confirmed_at": now_iso(), "vault_relative_path": str(path.relative_to(OBSIDIAN_VAULT_DIR))},
    )
    relation = create_relation_record(
        from_type="inbox",
        from_id=str(item_id),
        to_type="artifact",
        to_id=str(artifact.get("id")) if artifact else "",
        relation_type="synced_to_obsidian",
        metadata={"vault_path": str(path), "source_inbox_id": item_id},
    ) if artifact else None
    try:
        create_notification_record(
            title="已写入 Obsidian Inbox",
            body=f"收件箱 #{item_id} 已写入 {path.relative_to(OBSIDIAN_VAULT_DIR)}，原收件箱内容保留。",
            project_id="knowledge",
            kind="knowledge_sync",
            level="info",
            href="/projects/knowledge",
            event_key=f"obsidian-sync:{item_id}",
            dedupe_seconds=0,
        )
    except Exception:
        pass
    return {"synced": True, "already_exists": False, "path": str(path), "vault_relative_path": str(path.relative_to(OBSIDIAN_VAULT_DIR)), "artifact": artifact, "relation": relation, "message": "已写入 Obsidian Inbox，原收件箱内容仍保留。"}


def knowledge_draft_source_check(draft: dict[str, Any]) -> dict[str, Any]:
    """Verify that every recorded source is still readable and unchanged.

    Drafts remain safe to review when a source disappears, but writing them to
    the Vault must stop until the user can inspect the changed source.  Older
    drafts without hashes still receive the readability check and remain
    backwards compatible.
    """
    metadata = draft.get("metadata") if isinstance(draft.get("metadata"), dict) else {}
    expected_hashes = metadata.get("source_content_hashes") if isinstance(metadata.get("source_content_hashes"), dict) else {}
    checks: list[dict[str, Any]] = []
    failures: list[str] = []
    source_ids = [int(value) for value in metadata.get("source_artifact_ids", []) if str(value).isdigit()]
    for source_id in source_ids[:30]:
        source = get_artifact_record(source_id)
        if not source:
            checks.append({"type": "artifact", "artifact_id": source_id, "readable": False, "status": "missing", "message": "来源 Artifact 不存在"})
            failures.append(f"Artifact #{source_id} 不存在")
            continue
        source_text, source_error = read_artifact_source(source)
        current_hash = hashlib.sha256(source_text.encode("utf-8", errors="ignore")).hexdigest() if not source_error else ""
        expected = str(expected_hashes.get(str(source_id)) or expected_hashes.get(source_id) or "")
        changed = bool(expected and current_hash and expected != current_hash)
        status = "changed" if changed else "ok" if not source_error else "unreadable"
        checks.append({"type": "artifact", "artifact_id": source_id, "name": source.get("name", ""), "readable": not bool(source_error), "status": status, "expected_hash": expected, "current_hash": current_hash, "error": source_error})
        if source_error:
            failures.append(f"Artifact #{source_id} 当前不可读")
        elif changed:
            failures.append(f"Artifact #{source_id} 内容已变化")
    expected_note_hashes = metadata.get("source_note_hashes") if isinstance(metadata.get("source_note_hashes"), dict) else {}
    for source_note in [item for item in metadata.get("source_notes", []) if isinstance(item, dict)][:30]:
        relative = str(source_note.get("path") or "").strip()
        if not relative:
            continue
        note_path = (OBSIDIAN_VAULT_DIR / relative).resolve()
        try:
            note_path.relative_to(OBSIDIAN_VAULT_DIR.resolve())
        except ValueError:
            checks.append({"type": "obsidian_note", "path": relative, "readable": False, "status": "unsafe_path"})
            failures.append(f"来源笔记路径不安全：{relative}")
            continue
        try:
            note_text = note_path.read_text(encoding="utf-8", errors="ignore")
        except OSError as exc:
            checks.append({"type": "obsidian_note", "path": relative, "readable": False, "status": "unreadable", "error": str(exc)[:200]})
            failures.append(f"来源笔记不可读：{relative}")
            continue
        current_hash = hashlib.sha256(note_text.encode("utf-8", errors="ignore")).hexdigest()
        expected = str(expected_note_hashes.get(relative) or source_note.get("content_hash") or "")
        changed = bool(expected and expected != current_hash)
        checks.append({"type": "obsidian_note", "path": relative, "readable": True, "status": "changed" if changed else "ok", "expected_hash": expected, "current_hash": current_hash})
        if changed:
            failures.append(f"来源笔记内容已变化：{relative}")
    return {"blocked": bool(failures), "status": "blocked" if failures else "verified", "message": "；".join(failures) if failures else "所有已登记来源仍可读取且内容未变化", "checks": checks, "checked_at": now_iso()}


def sync_knowledge_draft_to_obsidian(artifact_id: int, *, conflict_action: str = "new") -> dict[str, Any]:
    """Copy an explicitly reviewed Workbench draft into Obsidian Inbox.

    Draft generation is intentionally separate from Vault writing.  This
    helper is the final, auditable boundary: it only accepts a registered
    knowledge Artifact, creates a backup before overwrite, and records the
    source/destination relation.  It never edits an existing Vault note by
    default.
    """
    artifact = get_artifact_record(artifact_id)
    if not artifact or artifact.get("project_id") != "knowledge":
        raise HTTPException(404, "知识库草稿 Artifact 不存在")
    allowed_kinds = {"source_review_draft", "paragraph_selection_draft", "knowledge_note", "inbox_handoff_note", "knowledge_conflict_merge_draft", "knowledge_conflict_paragraph_resolution"}
    if artifact.get("kind") not in allowed_kinds:
        raise HTTPException(409, "这份 Artifact 不是可写入 Obsidian 的知识库草稿")
    content, error = read_artifact_source(artifact)
    if error or not content.strip():
        raise HTTPException(409, error or "草稿没有可写入的正文")
    source_check = knowledge_draft_source_check(artifact)
    if source_check["blocked"]:
        raise HTTPException(409, f"写入前来源校验未通过：{source_check['message']}")
    if not OBSIDIAN_VAULT_DIR.is_dir():
        raise HTTPException(409, "Obsidian Vault 不可用")
    inbox_dir = OBSIDIAN_VAULT_DIR / "00 Inbox"
    inbox_dir.mkdir(parents=True, exist_ok=True)
    metadata = artifact.get("metadata") if isinstance(artifact.get("metadata"), dict) else {}
    title = str(metadata.get("title") or Path(str(artifact.get("name") or "Workbench 草稿")).stem or "Workbench 草稿").strip()
    base = safe_filename(title, f"workbench-draft-{artifact_id}")
    path = inbox_dir / f"{base}.md"
    backup = ""
    if path.exists():
        if conflict_action == "skip":
            return {"synced": False, "skipped": True, "path": str(path), "message": "目标笔记已存在，按选择跳过写入。", "source_artifact": artifact}
        if conflict_action == "overwrite":
            backup_path = path.with_suffix(path.suffix + f".workbench-{datetime.now().strftime('%Y%m%d-%H%M%S-%f')}.bak")
            backup_index = 2
            while backup_path.exists():
                backup_path = path.with_suffix(path.suffix + f".workbench-{datetime.now().strftime('%Y%m%d-%H%M%S-%f')}-{backup_index}.bak")
                backup_index += 1
            shutil.copy2(path, backup_path)
            backup = str(backup_path)
        else:
            suffix = 2
            while path.exists():
                path = inbox_dir / f"{base}-{suffix}.md"
                suffix += 1
    provenance = f"> 来源：Workbench 知识库草稿 Artifact #{artifact_id} · 原文件：{artifact.get('name', '未命名')}\n\n"
    body = content.strip()
    if provenance not in body:
        body = f"{provenance}{body}"
    path.write_text(body.rstrip() + "\n", encoding="utf-8")
    confirmed_at = now_iso()
    destination = register_artifact_safely(
        project_id="knowledge",
        name=path.name,
        path=str(path),
        kind="obsidian_reviewed_draft",
        metadata={"source_artifact_id": artifact_id, "confirmed_at": confirmed_at, "conflict_action": conflict_action, "backup": backup, "vault_relative_path": str(path.relative_to(OBSIDIAN_VAULT_DIR)), "source_check": source_check},
    )
    relation = create_relation_record(
        from_type="artifact", from_id=str(artifact_id), to_type="artifact", to_id=str(destination.get("id")) if destination else "", relation_type="draft_to_obsidian", metadata={"backup": backup, "conflict_action": conflict_action}
    ) if destination else None
    update_artifact_metadata(artifact_id, {"obsidian_sync": {"artifact_id": destination.get("id") if destination else None, "path": str(path), "confirmed_at": confirmed_at, "backup": backup, "source_check": source_check}})
    return {"synced": True, "skipped": False, "path": str(path), "vault_relative_path": str(path.relative_to(OBSIDIAN_VAULT_DIR)), "backup": backup, "artifact": destination, "relation": relation, "source_check": source_check, "confirmed_at": confirmed_at, "message": "草稿已写入 Obsidian Inbox，来源 Artifact、校验结果和备份已保留。"}


def knowledge_draft_replay(artifact_id: int) -> dict[str, Any]:
    """Return bounded source excerpts for a draft's citation replay UI."""
    draft = get_artifact_record(artifact_id)
    if not draft or draft.get("project_id") != "knowledge":
        raise HTTPException(404, "知识库草稿 Artifact 不存在")
    metadata = draft.get("metadata") if isinstance(draft.get("metadata"), dict) else {}
    source_ids = [int(value) for value in metadata.get("source_artifact_ids", []) if str(value).isdigit()]
    locators = [item for item in metadata.get("source_locators", []) if isinstance(item, dict)]
    sources: list[dict[str, Any]] = []
    for source_id in source_ids[:20]:
        source = get_artifact_record(source_id)
        if not source:
            sources.append({"id": source_id, "name": "来源 Artifact 不存在", "error": "来源已被移除或不可用"})
            continue
        content, error = read_artifact_source(source)
        if error:
            sources.append({"id": source_id, "name": source.get("name", "未命名来源"), "path": source.get("path", ""), "error": error})
            continue
        lines = content.splitlines()
        source_locators = [item for item in locators if int(item.get("artifact_id") or source_id) == source_id]
        ranges = []
        excerpts = []
        if source_locators:
            for locator in source_locators[:8]:
                start = max(1, int(locator.get("line_start") or 1))
                end = min(len(lines), max(start, int(locator.get("line_end") or start)))
                if lines:
                    ranges.append({"line_start": start, "line_end": end})
                    excerpts.append({"line_start": start, "line_end": end, "text": clip("\n".join(lines[start - 1:end]), 2_000)})
        else:
            end = min(len(lines), 24)
            excerpts.append({"line_start": 1, "line_end": end, "text": clip("\n".join(lines[:end]), 3_000)})
        source_metadata = source.get("metadata") if isinstance(source.get("metadata"), dict) else {}
        sources.append({
            "id": source_id,
            "name": source.get("name", "未命名来源"),
            "path": source.get("path", ""),
            "data_as_of": source_metadata.get("data_as_of") or source_metadata.get("checked_at") or source.get("created_at", ""),
            "ranges": ranges,
            "excerpts": excerpts,
        })
    for source_note in [item for item in metadata.get("source_notes", []) if isinstance(item, dict)][:20]:
        relative = str(source_note.get("path") or "").strip()
        note_path = (OBSIDIAN_VAULT_DIR / relative).resolve()
        try:
            note_path.relative_to(OBSIDIAN_VAULT_DIR.resolve())
        except ValueError:
            continue
        if not note_path.is_file():
            sources.append({"name": relative or "Obsidian 来源", "path": relative, "error": "来源笔记当前不可读取"})
            continue
        try:
            note_lines = note_path.read_text(encoding="utf-8", errors="ignore").splitlines()
        except OSError as exc:
            sources.append({"name": relative or "Obsidian 来源", "path": relative, "error": str(exc)[:200]})
            continue
        start = max(1, int(source_note.get("line_start") or 1))
        end = min(len(note_lines), max(start, int(source_note.get("line_end") or start)))
        sources.append({
            "name": relative or "Obsidian 来源",
            "path": relative,
            "excerpts": [{"line_start": start, "line_end": end, "text": clip("\n".join(note_lines[start - 1:end]), 2_000)}] if note_lines else [],
            "data_as_of": "",
        })
    return {
        "draft": {"id": artifact_id, "name": draft.get("name", ""), "kind": draft.get("kind", ""), "metadata": metadata},
        "sources": sources,
        "source_check": knowledge_draft_source_check(draft),
        "policy": "回放只读取已登记来源的有限片段和行号；不会改写来源，也不会把完整材料重新发送给外部服务。",
    }


def redact_agent_context(value: Any) -> Any:
    """Remove secrets before a project snapshot is included in an Agent prompt."""
    if isinstance(value, dict):
        redacted = {}
        for key, item in value.items():
            key_text = str(key).lower()
            if any(word in key_text for word in ("key", "token", "secret", "password", "cookie", "authorization")):
                redacted[key] = "[已隐藏]"
            else:
                redacted[key] = redact_agent_context(item)
        return redacted
    if isinstance(value, list):
        return [redact_agent_context(item) for item in value[:30]]
    return value


def agent_project_context(project_id: str) -> dict[str, Any]:
    """Build a small, read-only snapshot for a child Agent.

    This is deliberately assembled from existing project stores instead of
    asking the model to invent project state. Write actions remain separate
    APIs and are not performed by dispatch_agent_task.
    """
    context: dict[str, Any]
    if project_id == "inbox":
        context = {"source": "SQLite inbox", "pending": list_inbox("inbox")[:12]}
    elif project_id == "knowledge":
        context = {
            "source": str(KNOWLEDGE_DIR),
            "recent_notes": knowledge_search("")[:12],
            "obsidian": obsidian_status(),
            "obsidian_recent_notes": obsidian_search("", limit=12),
            "obsidian_today_notes": obsidian_search("", limit=20, since_timestamp=datetime.now().astimezone().replace(hour=0, minute=0, second=0, microsecond=0).timestamp()),
            "inbox_candidates": knowledge_inbox_candidates()[:12],
            "moc_suggestions": obsidian_moc_suggestions(),
        }
    elif project_id == "doc-factory":
        files = [path for path in OUTPUTS_DIR.iterdir() if path.is_file() and not path.name.startswith(".")]
        files.sort(key=lambda path: path.stat().st_mtime, reverse=True)
        context = {
            "source": str(OUTPUTS_DIR),
            "recent_outputs": [
                {"name": path.name, "size": path.stat().st_size, "updated_at": datetime.fromtimestamp(path.stat().st_mtime, tz=timezone.utc).isoformat()}
                for path in files[:12]
            ],
            "available_source_artifacts": document_factory_source_descriptors(limit=30),
            "source_policy": "只读工作台管理目录中的已登记 Artifact；生成结果保留来源 Relation，不覆盖旧产物。",
        }
    elif project_id == "sub2api":
        snapshot = load_sub2api_snapshot()
        context = {"source": str(SUB2API_SNAPSHOT_FILE), "snapshot": redact_agent_context(snapshot), "analysis": analyze_sub2api_snapshot(snapshot), "history": list_sub2api_history(limit=8)}
    elif project_id == "market":
        snapshot = load_market_snapshot()
        record_market_snapshot(snapshot)
        history = list_market_history(limit=12)
        analysis = analyze_market_snapshot(snapshot, history)
        context = {
            "source": str(MARKET_SNAPSHOT_FILE),
            "snapshot": redact_agent_context(snapshot),
            "analysis": analysis,
            "history": redact_agent_context(history),
            "open_observation_tasks": [
                item for item in list_work_items("all", "market")
                if item.get("source_project") == "market"
                and item.get("kind") == "research_observation"
                and item.get("status") in {"open", "running", "blocked"}
            ][:20],
        }
    elif project_id == "server":
        snapshot = load_server_monitor_snapshot()
        history = list_server_monitor_history(limit=12)
        context = {
            "source": str(SERVER_MONITOR_SNAPSHOT_FILE),
            "target": server_monitor_config()["server"],
            "snapshot": redact_agent_context(snapshot),
            "analysis": analyze_server_snapshot(snapshot, history),
            "history": redact_agent_context(history),
            "risk_boundary": "只读探测；重启、部署、配置修改和删除必须人工确认。",
        }
    elif project_id in {"crawl4ai", "web-research"}:
        durable_runs = list_agent_runs("crawl4ai", limit=12)
        recent_runs: list[dict[str, Any]] = []
        seen_run_ids: set[str] = set()

        # The in-memory object has the freshest logs while a crawl is active;
        # the SQLite row is the source of truth after a restart. Merge both so
        # the Agent never loses its research context just because the API was
        # restarted between two questions.
        for durable in durable_runs:
            run_id = str(durable.get("id") or "")
            if not run_id or run_id in seen_run_ids:
                continue
            runtime = runs.get(run_id) or runtime_crawl_from_agent_run(durable)
            result = durable.get("result") or {}
            documents = runtime.get("documents") or result.get("documents") or []
            recent_runs.append(
                {
                    "id": run_id,
                    "status": runtime.get("status") or durable.get("status"),
                    "status_label": durable.get("status_label"),
                    "task": runtime.get("task") or durable.get("request", {}).get("task", ""),
                    "urls": runtime.get("urls") or durable.get("request", {}).get("urls", []),
                    "documents": [
                        {
                            "url": item.get("url", ""),
                            "title": item.get("title", "未命名页面"),
                            "success": bool(item.get("success")),
                            "markdown_chars": item.get("markdown_chars", 0),
                        }
                        for item in documents[:12]
                    ],
                    "analysis_status": runtime.get("analysis_status") or result.get("analysis_status"),
                    "artifact_id": runtime.get("artifact_id") or result.get("artifact_id"),
                    "work_item_id": runtime.get("work_item_id") or result.get("work_item_id"),
                    "error": runtime.get("error") or durable.get("error", ""),
                    "created_at": durable.get("created_at"),
                    "updated_at": durable.get("updated_at"),
                }
            )
            seen_run_ids.add(run_id)

        # A newly queued run can exist in memory before the first durable
        # result snapshot has been written. Keep that state visible too.
        for runtime in sorted(runs.values(), key=lambda item: item.get("created_at", ""), reverse=True):
            run_id = str(runtime.get("id") or "")
            if not run_id or run_id in seen_run_ids:
                continue
            recent_runs.append(
                {
                    "id": run_id,
                    "status": runtime.get("status", "queued"),
                    "status_label": AGENT_RUN_STATUS_LABELS.get(runtime.get("status"), runtime.get("status", "未知")),
                    "task": runtime.get("task", ""),
                    "urls": runtime.get("urls", []),
                    "documents": [
                        {
                            "url": item.get("url", ""),
                            "title": item.get("title", "未命名页面"),
                            "success": bool(item.get("success")),
                            "markdown_chars": item.get("markdown_chars", 0),
                        }
                        for item in (runtime.get("documents") or [])[:12]
                    ],
                    "analysis_status": runtime.get("analysis_status"),
                    "artifact_id": runtime.get("artifact_id"),
                    "work_item_id": runtime.get("work_item_id"),
                    "error": runtime.get("error", ""),
                    "created_at": runtime.get("created_at"),
                    "updated_at": runtime.get("finished_at") or runtime.get("created_at"),
                }
            )
            seen_run_ids.add(run_id)

        context = {
            "source": "SQLite agent_runs + current crawl runtime",
            "runs": recent_runs[:12],
        }
    elif project_id == "aihot":
        snapshot = load_aihot_snapshot()
        context = {"source": "aihot.today", "fetched_at": snapshot.get("fetched_at"), "items": select_aihot_items(snapshot, "useful", limit=12)}
    elif project_id == "idea-analysis":
        context = {
            "source": "SQLite idea_sessions + incoming opportunity WorkItems",
            "recent_sessions": list_idea_sessions(limit=8),
            "incoming_opportunities": idea_opportunity_work_items(limit=12),
        }
    elif project_id == "product-manager":
        overview = product_manager_overview(limit=20)
        context = {
            "source": "SQLite product_feedback + product_requirements + product_decisions",
            "summary": overview.get("summary", {}),
            "feedback": overview.get("feedback", [])[:12],
            "requirements": overview.get("requirements", [])[:12],
            "decisions": overview.get("decisions", [])[:8],
            "priority_policy": "RICE = reach × impact × confidence / effort；分数只用于排序建议，最终优先级必须由产品经理确认。",
        }
    elif project_id == "workbench":
        context = {"source": "SQLite work_items", "open_work_items": list_work_items("open")[:12]}
    elif project_id == "cid-dashboard":
        context = {"source": "browser project context", "note": "看板明细由 CID 页面在调用子 Agent 时提供；后端不读取其浏览器 localStorage。"}
    else:
        context = {"source": "project registry", "note": "当前项目尚未注册可读取的数据源。"}

    links = project_link_summary(project_id)
    return {
        "project_context": context,
        "shared_context": {
            "project_id": project_id,
            "agent_name": agent_display_name(project_id),
            "inbound_links": links["inbound"],
            "outbound_links": links["outbound"],
            "open_work_items": list_work_items("open", project_id)[:12],
            "recent_artifacts": list_artifacts(project_id)[:12],
        },
    }


async def extract_upload_text(upload: UploadFile) -> tuple[str, str]:
    filename = upload.filename or "未命名文件"
    raw = await upload.read()
    try:
        # MinerU can run for minutes on a scanned PDF; never on the event loop.
        text = await asyncio.to_thread(extract_document_bytes, raw, filename)
        return text, filename
    except ValueError as exc:
        raise HTTPException(400, str(exc)) from exc


def write_knowledge_note(title: str, content: str, *, metadata: dict[str, Any] | None = None, artifact_kind: str = "knowledge_note") -> dict[str, Any]:
    filename = safe_filename(title, "未命名笔记") + ".md"
    path = KNOWLEDGE_DIR / filename
    if path.exists():
        filename = f"{safe_filename(title, '未命名笔记')}-{datetime.now().strftime('%H%M%S')}.md"
        path = KNOWLEDGE_DIR / filename
    body = content.strip()
    if not body.startswith("#"):
        body = f"# {title.strip() or '未命名笔记'}\n\n{body}"
    path.write_text(body.rstrip() + "\n", encoding="utf-8")
    artifact = register_artifact_safely(
        project_id="knowledge",
        name=path.name,
        path=str(path),
        kind=artifact_kind,
        metadata={"title": title.strip() or "未命名笔记", **(metadata or {})},
    )
    return {"name": path.stem, "path": str(path.relative_to(KNOWLEDGE_DIR)), "title": title, "artifact": artifact}


# ---------------------------------------------------------------------------
# ReAct 工具注册表：让总调度 Agent 真正"执行工具"，而不是只读资料写总结。
# 每个工具：name + description + parameters(JSON Schema) + 同步执行函数。
# 执行器直接调用现有业务函数，返回真实结果（脱敏后回传 LLM）。
# ---------------------------------------------------------------------------

def _react_server_status(_: dict[str, Any]) -> dict[str, Any]:
    """只读服务器状态：健康评分、磁盘/内存/负载、告警、容量趋势。"""
    try:
        snapshot = read_server_monitor()
        evaluation = evaluate_server_monitor(snapshot, create_records=False)
    except Exception as exc:
        return {"ok": False, "error": str(exc)}
    metrics = evaluation.get("metrics") or {}
    return {
        "ok": True,
        "status": evaluation.get("status"),
        "health_score": evaluation.get("health_score"),
        "metrics": {k: v for k, v in metrics.items() if v is not None},
        "alerts": [{"title": a.get("title"), "level": a.get("level")} for a in (evaluation.get("alerts") or [])][:6],
        "prediction": {k: (v or {}) for k, v in (evaluation.get("prediction") or {}).items()},
        "summary": evaluation.get("summary"),
    }


def _react_sub2api_status(_: dict[str, Any]) -> dict[str, Any]:
    """只读 Sub2API 额度：订阅、用量、预测、建议。"""
    try:
        snapshot = load_sub2api_snapshot()
        analysis = analyze_sub2api_snapshot(snapshot)
        prediction = sub2api_prediction(list_sub2api_history(limit=8))
    except Exception as exc:
        return {"ok": False, "error": str(exc)}
    sub = snapshot.get("subscription") or {}
    today = snapshot.get("today") or {}
    return {
        "ok": True,
        "balance": snapshot.get("balance"),
        "subscription": {"name": sub.get("name"), "provider": sub.get("provider"), "weekly_usage": sub.get("weekly_usage"), "remaining": sub.get("remaining"), "expires_at": sub.get("expires_at")},
        "today": {"cost": today.get("cost"), "requests": today.get("requests")},
        "prediction": {k: v for k, v in prediction.items() if k in {"available", "trend", "days_left", "remaining_pct", "note", "suggestions"}},
        "analysis": {k: v for k, v in analysis.items() if k in {"status", "status_label", "summary"}},
    }


def _react_knowledge_search(args: dict[str, Any]) -> dict[str, Any]:
    """搜索知识库：关键词 + 语义混合检索，返回命中的笔记标题与摘要。"""
    query = str(args.get("query") or "").strip()
    limit = int(args.get("limit") or 5)
    if not query:
        return {"ok": False, "error": "query 不能为空"}
    try:
        notes = knowledge_hybrid_search(query, limit=min(max(limit, 1), 10))
    except Exception as exc:
        return {"ok": False, "error": str(exc)}
    return {
        "ok": True,
        "count": len(notes),
        "results": [{"title": n.get("title") or n.get("name"), "path": n.get("path"), "preview": clip(n.get("preview") or n.get("content") or "", 300)} for n in notes[:limit]],
    }


def _react_inbox_read(args: dict[str, Any]) -> dict[str, Any]:
    """读取收件箱：未处理条目（可带 limit）。"""
    limit = int(args.get("limit") or 8)
    items = list_inbox("all")
    active = [i for i in items if i.get("status") == "inbox"]
    return {
        "ok": True,
        "count": len(active),
        "items": [{"id": i.get("id"), "content": clip(str(i.get("content") or ""), 120), "status": i.get("status"), "classification": i.get("classification"), "created_at": i.get("created_at")} for i in active[:limit]],
    }


def _react_inbox_capture(args: dict[str, Any]) -> dict[str, Any]:
    """写入收件箱：把一句话记录成收件箱条目（低风险本地动作）。"""
    content = str(args.get("content") or "").strip()
    if not content:
        return {"ok": False, "error": "content 不能为空"}
    try:
        record = create_inbox_record(content=content, kind=str(args.get("kind") or "note"), tags=str(args.get("tags") or ""))
    except Exception as exc:
        return {"ok": False, "error": str(exc)}
    return {"ok": True, "id": record.get("id"), "status": record.get("status")}


def _react_cloud_dev_generate(args: dict[str, Any]) -> dict[str, Any]:
    """云开发生成工坊：一句话生成可交付产物（网页原型/文档/脚本），存 outputs/cloudgen。

    handler 为同步执行器，内部用独立事件循环跑 LLM 生成。
    """
    requirement = str(args.get("requirement") or "").strip()
    kind = str(args.get("kind") or "webpage")
    if not requirement:
        return {"ok": False, "error": "请描述想生成的内容，例如：做一个理财记账网页。"}
    if kind not in {"webpage", "doc", "script"}:
        kind = "webpage"
    try:
        result = asyncio.run(execute_cloud_dev_generate(requirement, kind))
    except Exception as exc:
        return {"ok": False, "error": f"生成失败：{clip(str(exc), 500) or '未知错误'}"}
    if result.get("status") != "ok":
        return {"ok": False, "error": str(result.get("message") or result.get("status") or "生成失败")}
    return {
        "ok": True,
        "kind": result.get("kind"),
        "label": result.get("label"),
        "file": result.get("file"),
        "url": result.get("url"),
        "artifact_id": result.get("artifact_id"),
        "summary": str(result.get("summary") or "")[:300],
        "message": result.get("message"),
    }


def _react_cloud_dev_patch(args: dict[str, Any]) -> dict[str, Any]:
    """云端自动改：一句话修改工作台代码（前端/小模块）→ 生成编辑计划 → 进入审批。

    handler 为同步执行器，内部用独立事件循环跑 LLM 生成编辑计划。
    审批通过前不修改任何代码；批准后由审批执行链路应用并自动测试 + 回滚兜底。
    """
    requirement = str(args.get("requirement") or "").strip()
    if not requirement:
        return {"ok": False, "error": "请描述要改什么，例如：帮我把 AI 伴读的按钮改成蓝色。"}
    try:
        result = asyncio.run(execute_cloud_dev_patch(requirement, source="workbench"))
    except Exception as exc:
        return {"ok": False, "error": f"生成编辑计划失败：{clip(str(exc), 500) or '未知错误'}"}
    if result.get("status") != "approval_required":
        return {"ok": False, "error": str(result.get("message") or result.get("status") or "失败")}
    return {
        "ok": True,
        "action": "patch",
        "summary": str(result.get("summary") or "")[:200],
        "files": result.get("files") or [],
        "edits_count": result.get("edits_count") or 0,
        "approval_id": result.get("approval_id"),
        "message": f"已生成编辑计划，审批编号 {result.get('approval_id')}；审批通过前不会改动代码。",
    }


