@app.post("/api/integrations/{integration_id}/import")
async def import_integration_items(integration_id: str, request: IntegrationImportRequest) -> dict[str, Any]:
    require_integration(integration_id)
    items = await fetch_integration_items(integration_id, max(len(request.ids), 20))
    selected = {str(item_id) for item_id in request.ids}
    selected_items = [item for item in items if str(item.get("id") or "") in selected]
    if not selected_items:
        raise HTTPException(404, "没有找到可导入的远端条目；请先重新读取最新条目")

    known_ids: set[str] = set()
    connection = db_connection()
    try:
        rows = connection.execute("SELECT metadata_json FROM work_items WHERE kind IN ('integration_item', 'efficiency_observation') ORDER BY id DESC LIMIT 500").fetchall()
        for row in rows:
            metadata = decode_json_column(row["metadata_json"])
            if metadata.get("integration_id") == integration_id and metadata.get("integration_item_id"):
                known_ids.add(str(metadata["integration_item_id"]))
    finally:
        connection.close()

    target_project = (
        "knowledge" if integration_id in {"zotero", "paperless"}
        else "inbox" if integration_id == "github"
        else "inbox" if integration_id == "vikunja"
        else "workbench" if integration_id == "activitywatch"
        else "crawl4ai"
    )
    created: list[dict[str, Any]] = []
    skipped: list[str] = []
    for remote_item in selected_items:
        remote_id = str(remote_item.get("id") or "")
        if remote_id in known_ids:
            skipped.append(remote_id)
            continue
        source = str(remote_item.get("source") or INTEGRATION_DEFINITIONS[integration_id]["name"])
        description = "\n".join(filter(None, [
            str(remote_item.get("summary") or "").strip(),
            f"来源：{source}",
            f"链接：{remote_item.get('url')}" if remote_item.get("url") else "",
            "请在目标 Agent 中继续处理，并保留来源和下一步。",
        ]))
        item = create_work_item_record(
            title=f"{INTEGRATION_DEFINITIONS[integration_id]['name']}：{str(remote_item.get('title') or '未命名条目')[:220]}",
            description=description,
            kind="efficiency_observation" if integration_id == "activitywatch" else "integration_item",
            source_project="workbench",
            target_project=target_project,
            metadata={
                "integration_id": integration_id,
                "integration_item_id": remote_id,
                "source_id": remote_id,
                "source": source,
                "url": str(remote_item.get("url") or ""),
                "published_at": str(remote_item.get("published_at") or ""),
                "source_updated_at": str((remote_item.get("metadata") or {}).get("source_updated_at") or remote_item.get("published_at") or ""),
                "remote_metadata": remote_item.get("metadata") if isinstance(remote_item.get("metadata"), dict) else {},
                "target_project": target_project,
            },
        )
        relation = create_relation_record(
            from_type="integration_item",
            from_id=remote_id,
            to_type="work_item",
            to_id=str(item["id"]),
            relation_type="imported_to_work_item",
            metadata={
                "integration_id": integration_id,
                "target_project": target_project,
                "source_id": remote_id,
                "source_updated_at": str((remote_item.get("metadata") or {}).get("source_updated_at") or remote_item.get("published_at") or ""),
            },
        )
        created.append({"item": item, "relation": relation})
        known_ids.add(remote_id)
    return {"ok": True, "created": len(created), "skipped": skipped, "items": created, "target_project": target_project}


@app.post("/api/integrations/ntfy/notify")
async def notify_via_ntfy(request: IntegrationNotificationRequest) -> dict[str, Any]:
    require_integration("ntfy")
    try:
        result = await send_ntfy_message(title=request.title, body=request.body, href=request.href, priority=request.priority)
    except HTTPException as exc:
        update_integration_test("ntfy", "notify_failed", str(exc.detail))
        raise
    update_integration_test("ntfy", "notification_sent")
    return {"ok": True, "delivery": result, "message": "ntfy 通知已发送"}


@app.post("/api/github-tools/{tool_id}/trial")
async def create_github_tool_trial(tool_id: str) -> dict[str, Any]:
    catalog = await asyncio.to_thread(get_github_tools)
    tool = next((item for item in catalog["tools"] if item["id"] == tool_id), None)
    if not tool:
        raise HTTPException(404, "GitHub 工具不存在")
    item = create_work_item_record(title=f"试用 GitHub 工具：{tool['name']}", description=f"场景：{tool['scenario']}\n试用建议：{tool['trial']}\n仓库：{tool['url']}", kind="github_tool_trial", source_project="workbench", target_project="workbench", metadata={"tool": tool, "repo_path": ""})
    return {"ok": True, "item": item}


def set_docx_run_font(run: Any, name: str = "Hiragino Sans GB", size: float = 11, color: str = "1F2937", bold: bool | None = None) -> None:
    from docx.oxml.ns import qn
    from docx.shared import Pt, RGBColor

    run.font.name = name
    run._element.get_or_add_rPr().rFonts.set(qn("w:ascii"), name)
    run._element.get_or_add_rPr().rFonts.set(qn("w:hAnsi"), name)
    run._element.get_or_add_rPr().rFonts.set(qn("w:eastAsia"), name)
    run._element.get_or_add_rPr().rFonts.set(qn("w:cs"), name)
    run.font.size = Pt(size)
    run.font.color.rgb = RGBColor.from_string(color)
    if bold is not None:
        run.bold = bold


def set_docx_cell_shading(cell: Any, fill: str) -> None:
    from docx.oxml import OxmlElement
    from docx.oxml.ns import qn

    tc_pr = cell._tc.get_or_add_tcPr()
    shd = tc_pr.find(qn("w:shd"))
    if shd is None:
        shd = OxmlElement("w:shd")
        tc_pr.append(shd)
    shd.set(qn("w:fill"), fill)


def build_docx_delivery(title: str, text: str, target: Path) -> None:
    from docx import Document
    from docx.enum.section import WD_SECTION
    from docx.enum.table import WD_CELL_VERTICAL_ALIGNMENT
    from docx.enum.text import WD_ALIGN_PARAGRAPH
    from docx.oxml.ns import qn
    from docx.shared import Inches, Pt

    document = Document()
    section = document.sections[0]
    section.top_margin = Inches(1)
    section.bottom_margin = Inches(1)
    section.left_margin = Inches(1)
    section.right_margin = Inches(1)
    section.header_distance = Inches(0.492)
    section.footer_distance = Inches(0.492)
    normal = document.styles["Normal"]
    normal.font.name = "Hiragino Sans GB"
    normal.font.size = Pt(11)
    normal.paragraph_format.space_after = Pt(6)
    normal.paragraph_format.line_spacing = 1.1
    for name, size, color, before, after in (("Heading 1", 16, "2E74B5", 16, 8), ("Heading 2", 13, "2E74B5", 12, 6), ("Heading 3", 12, "1F4D78", 8, 4)):
        style = document.styles[name]
        style.font.name = "Hiragino Sans GB"
        style._element.get_or_add_rPr().rFonts.set(qn("w:ascii"), "Hiragino Sans GB")
        style._element.get_or_add_rPr().rFonts.set(qn("w:hAnsi"), "Hiragino Sans GB")
        style._element.get_or_add_rPr().rFonts.set(qn("w:eastAsia"), "Hiragino Sans GB")
        style._element.get_or_add_rPr().rFonts.set(qn("w:cs"), "Hiragino Sans GB")
        style.font.size = Pt(size)
        style.font.color.rgb = __import__("docx").shared.RGBColor.from_string(color)
        style.font.bold = True
        style.paragraph_format.space_before = Pt(before)
        style.paragraph_format.space_after = Pt(after)
        style.paragraph_format.line_spacing = 1.1
    header = section.header.paragraphs[0]
    header.text = "Workbench · 文档交付包"
    header.alignment = WD_ALIGN_PARAGRAPH.RIGHT
    for run in header.runs:
        set_docx_run_font(run, size=9, color="6B7280")
    footer = section.footer.paragraphs[0]
    footer.text = f"{WORKBENCH_VERSION} · 生成于 {datetime.now().astimezone().strftime('%Y-%m-%d %H:%M')}"
    footer.alignment = WD_ALIGN_PARAGRAPH.RIGHT
    for run in footer.runs:
        set_docx_run_font(run, size=8.5, color="6B7280")
    title_paragraph = document.add_paragraph()
    title_paragraph.paragraph_format.space_after = Pt(4)
    title_run = title_paragraph.add_run(title or "未命名文档")
    set_docx_run_font(title_run, size=23, color="0B2545", bold=True)
    meta = document.add_paragraph()
    meta.paragraph_format.space_after = Pt(14)
    meta_run = meta.add_run(f"Workbench 正式交付草稿 · 版本 {WORKBENCH_VERSION}")
    set_docx_run_font(meta_run, size=10, color="6B7280")
    rule = document.add_paragraph()
    rule.paragraph_format.space_after = Pt(12)
    p_pr = rule._p.get_or_add_pPr()
    from docx.oxml import OxmlElement
    p_bdr = OxmlElement("w:pBdr")
    bottom = OxmlElement("w:bottom")
    bottom.set(qn("w:val"), "single")
    bottom.set(qn("w:sz"), "8")
    bottom.set(qn("w:space"), "1")
    bottom.set(qn("w:color"), "D8DEE8")
    p_bdr.append(bottom)
    p_pr.append(p_bdr)

    def add_markdown_runs(paragraph: Any, content: str) -> None:
        """Render the small Markdown subset accepted by the document factory."""
        chunks = re.split(r"(\*\*.+?\*\*)", str(content or ""))
        for chunk in chunks:
            if not chunk:
                continue
            is_bold = chunk.startswith("**") and chunk.endswith("**") and len(chunk) >= 4
            value = chunk[2:-2] if is_bold else chunk
            run = paragraph.add_run(value)
            set_docx_run_font(run, bold=is_bold)

    for raw in str(text or "").splitlines():
        line = raw.strip()
        if not line:
            document.add_paragraph().paragraph_format.space_after = Pt(2)
            continue
        if line in {"*", "_"}:
            continue
        if line.startswith("### "):
            document.add_paragraph(line[4:], style="Heading 3")
        elif line.startswith("## "):
            document.add_paragraph(line[3:], style="Heading 2")
        elif line.startswith("# "):
            document.add_paragraph(line[2:], style="Heading 1")
        elif line.startswith(("- ", "* ")):
            paragraph = document.add_paragraph(style="List Bullet")
            paragraph.paragraph_format.left_indent = Inches(0.5)
            paragraph.paragraph_format.first_line_indent = Inches(-0.25)
            paragraph.paragraph_format.space_after = Pt(8)
            add_markdown_runs(paragraph, line[2:])
        elif re.match(r"^\d+[.)] ", line):
            paragraph = document.add_paragraph(style="List Number")
            paragraph.paragraph_format.left_indent = Inches(0.5)
            paragraph.paragraph_format.first_line_indent = Inches(-0.25)
            paragraph.paragraph_format.space_after = Pt(8)
            add_markdown_runs(paragraph, re.sub(r"^\d+[.)] ", "", line))
        else:
            paragraph = document.add_paragraph()
            paragraph.paragraph_format.space_after = Pt(6)
            paragraph.paragraph_format.line_spacing = 1.1
            add_markdown_runs(paragraph, line)
    document.save(target)


def convert_docx_to_pdf(docx_path: Path, pdf_path: Path) -> tuple[bool, str]:
    soffice = shutil.which("soffice") or shutil.which("libreoffice")
    if not soffice:
        return False, "未找到 LibreOffice/soffice"
    temp_dir = pdf_path.parent / f".pdf-convert-{uuid.uuid4().hex}"
    temp_dir.mkdir(parents=True, exist_ok=True)
    try:
        # The bundled headless LibreOffice build does not always inherit the
        # macOS font database, so Chinese TTC fonts can otherwise become
        # missing-glyph boxes.  Give fontconfig an explicit, per-conversion
        # search path.  WORKBENCH_DOCX_FONT_DIR is also supported for Linux
        # deployments where a CJK font package is mounted separately.
        font_dirs: list[Path] = []
        configured_font_dir = os.getenv("WORKBENCH_DOCX_FONT_DIR", "").strip()
        if configured_font_dir:
            font_dirs.append(Path(configured_font_dir).expanduser())
        font_dirs.extend(
            Path(path)
            for path in (
                "/System/Library/Fonts",
                "/System/Library/Fonts/Supplemental",
                "/Library/Fonts",
                str(Path.home() / "Library" / "Fonts"),
                "/usr/share/fonts",
                "/usr/local/share/fonts",
            )
        )
        font_dirs = [path for path in font_dirs if path.exists() and path.is_dir()]
        conversion_env = os.environ.copy()
        if font_dirs:
            fontconfig_path = temp_dir / "fontconfig.conf"
            fontconfig_dirs = "".join(f"    <dir>{str(path)}</dir>\n" for path in font_dirs)
            fontconfig_path.write_text(
                "<?xml version=\"1.0\"?>\n"
                "<!DOCTYPE fontconfig SYSTEM \"urn:fontconfig:fonts.dtd\">\n"
                "<fontconfig>\n"
                f"{fontconfig_dirs}"
                "    <dir prefix=\"xdg\">fonts</dir>\n"
                "    <dir>~/.fonts</dir>\n"
                "</fontconfig>\n",
                encoding="utf-8",
            )
            conversion_env["FONTCONFIG_FILE"] = str(fontconfig_path)
        result = subprocess.run(
            [soffice, "--headless", "--convert-to", "pdf", "--outdir", str(temp_dir), str(docx_path)],
            capture_output=True,
            text=True,
            timeout=60,
            check=False,
            env=conversion_env,
        )
        converted = temp_dir / f"{docx_path.stem}.pdf"
        if result.returncode != 0 or not converted.exists():
            return False, clip(result.stderr or result.stdout or "PDF 转换失败", 500)
        shutil.copy2(converted, pdf_path)
        return True, ""
    except (OSError, subprocess.SubprocessError) as exc:
        return False, str(exc)
    finally:
        shutil.rmtree(temp_dir, ignore_errors=True)


@app.post("/api/doc-factory/deliver")
def deliver_document_factory(request: DocumentDeliveryRequest) -> dict[str, Any]:
    artifact = get_artifact_record(request.artifact_id)
    if not artifact or artifact.get("project_id") != "doc-factory":
        raise HTTPException(404, "文档产物 Artifact 不存在")
    text, read_error = read_artifact_source(artifact)
    if read_error:
        raise HTTPException(409, f"无法读取文档产物：{read_error}")
    metadata = artifact.get("metadata") if isinstance(artifact.get("metadata"), dict) else {}
    parent_approval_id = str(request.parent_approval_id or "").strip()
    parent_payload: dict[str, Any] = {}
    parent_round = 0
    if parent_approval_id:
        connection = db_connection()
        try:
            parent_row = connection.execute("SELECT payload_json FROM approval_requests WHERE id = ? AND kind = 'document_delivery'", (parent_approval_id,)).fetchone()
        finally:
            connection.close()
        if parent_row:
            parent_payload = platform_decode_json(parent_row["payload_json"], {})
            try:
                parent_round = max(0, int(parent_payload.get("round") or 0))
            except (TypeError, ValueError):
                parent_round = 0
    approval_round = parent_round + 1 if parent_approval_id else max(1, int(metadata.get("approval_round") or 1))
    previous_artifact_id = metadata.get("revision_from_artifact_id")
    source_artifact_id = previous_artifact_id if parent_approval_id and previous_artifact_id else artifact.get("id")
    revision_artifact_id = artifact.get("id") if parent_approval_id and previous_artifact_id else None
    title = request.title.strip() or str(metadata.get("title") or artifact.get("name") or "Workbench 文档")
    base = safe_filename(title, "workbench-document")
    version = int(metadata.get("version") or 1)
    created: list[dict[str, Any]] = []
    formats = [value.lower().strip() for value in request.formats if value.lower().strip() in {"docx", "pdf"}]
    if not formats:
        raise HTTPException(400, "formats 只能是 docx 或 pdf")
    docx_path = OUTPUTS_DIR / f"{base}-v{version}.docx"
    if "docx" in formats or "pdf" in formats:
        build_docx_delivery(title, text, docx_path)
        docx_artifact = register_artifact_safely(project_id="doc-factory", name=docx_path.name, path=str(docx_path), kind="document_delivery_docx", metadata={"title": title, "version": version, "source_artifact_id": artifact.get("id"), "revision_artifact_id": revision_artifact_id, "format": "docx", "approval_status": "pending", "approval_round": approval_round, "parent_approval_id": parent_approval_id})
        created.append(docx_artifact or {"name": docx_path.name, "path": str(docx_path)})
        create_relation_record(from_type="artifact", from_id=str(artifact.get("id")), to_type="artifact", to_id=str((docx_artifact or {}).get("id", "")), relation_type="delivered_as_docx", metadata={"title": title, "version": version}) if docx_artifact else None
    if "pdf" in formats:
        pdf_path = OUTPUTS_DIR / f"{base}-v{version}.pdf"
        ok, conversion_error = convert_docx_to_pdf(docx_path, pdf_path)
        if not ok:
            raise HTTPException(503, f"PDF 交付需要 LibreOffice：{conversion_error}")
        pdf_artifact = register_artifact_safely(project_id="doc-factory", name=pdf_path.name, path=str(pdf_path), kind="document_delivery_pdf", metadata={"title": title, "version": version, "source_artifact_id": artifact.get("id"), "revision_artifact_id": revision_artifact_id, "format": "pdf", "approval_status": "pending", "approval_round": approval_round, "parent_approval_id": parent_approval_id})
        created.append(pdf_artifact or {"name": pdf_path.name, "path": str(pdf_path)})
        create_relation_record(from_type="artifact", from_id=str(artifact.get("id")), to_type="artifact", to_id=str((pdf_artifact or {}).get("id", "")), relation_type="delivered_as_pdf", metadata={"title": title, "version": version}) if pdf_artifact else None
    approval_payload = {
        "round": approval_round,
        "source_artifact_id": source_artifact_id,
        "current_artifact_id": artifact.get("id"),
        "revision_artifact_id": revision_artifact_id,
        "parent_approval_id": parent_approval_id,
        "delivery_artifacts": [item.get("id") for item in created if item.get("id")],
        "formats": formats,
        "title": title,
        "version": version,
    }
    approval = create_approval_request("doc-factory", "document_delivery", f"第 {approval_round} 轮审批：{title}", approval_payload)
    if parent_approval_id:
        create_relation_record(from_type="approval", from_id=parent_approval_id, to_type="approval", to_id=approval["id"], relation_type="approval_revised_as", metadata={"round": approval_round, "source_artifact_id": source_artifact_id, "revision_artifact_id": revision_artifact_id})
    create_notification_record(title="正式文档交付包待审批", body=f"{title} · {', '.join(formats).upper()} · 请在审批中心确认或提出修改意见。", project_id="doc-factory", kind="approval", level="warning", href="/projects/doc-factory", event_key=f"document-delivery:{approval['id']}", dedupe_seconds=0)
    return {"ok": True, "source": artifact, "deliveries": created, "approval": approval, "approval_context": {"round": approval_round, "parent_approval_id": parent_approval_id, "source_artifact_id": source_artifact_id, "revision_artifact_id": revision_artifact_id}, "message": f"第 {approval_round} 轮交付包已生成，当前状态为待审批。"}


def knowledge_tokens(value: str) -> set[str]:
    tokens = set(re.findall(r"[\u4e00-\u9fff]{2,}|[a-zA-Z0-9_]{2,}", str(value or "").lower()))
    expanded: set[str] = set(tokens)
    for token in tokens:
        if len(token) >= 4 and re.fullmatch(r"[\u4e00-\u9fff]+", token):
            expanded.update(token[index:index + 2] for index in range(len(token) - 1))
    return expanded


def knowledge_vector_features(value: str) -> set[str]:
    """Build dependency-free local features for a reproducible vector index.

    This is deliberately not marketed as a pretrained semantic model. It is a
    stable feature-hash vector that complements the existing IDF ranking with
    Chinese character n-grams and ASCII terms, so the index remains rebuildable
    offline and does not send Vault content to a remote embedding service.
    """
    text = str(value or "").lower()
    features = {f"t:{token}" for token in knowledge_tokens(text)}
    for block in re.findall(r"[\u4e00-\u9fff]+", text):
        features.update(f"c:{block[index:index + 2]}" for index in range(max(0, len(block) - 1)))
    return features


def knowledge_hash_vector(features: set[str], dimension: int = 192) -> list[float]:
    vector = [0.0] * dimension
    for feature in features:
        digest = hashlib.blake2b(feature.encode("utf-8", errors="replace"), digest_size=8).digest()
        index = int.from_bytes(digest[:4], "big") % dimension
        sign = 1.0 if digest[4] & 1 else -1.0
        vector[index] += sign
    magnitude = math.sqrt(sum(value * value for value in vector))
    return [value / magnitude for value in vector] if magnitude else vector


def knowledge_vector_similarity(left: list[float], right: list[float]) -> float:
    return max(0.0, min(1.0, sum(a * b for a, b in zip(left, right))))


def obsidian_semantic_results(query: str, limit: int = 20) -> list[dict[str, Any]]:
    query_tokens = knowledge_tokens(query)
    if not query_tokens:
        return obsidian_search("", limit=limit)
    rows = obsidian_index_rows()
    query_vector = knowledge_hash_vector(knowledge_vector_features(query))
    # 真语义向量：embedding 服务可用时，query 现场 embed、文档向量查
    # knowledge_vectors 表（复用工作区索引），替代词法哈希向量提升召回；
    # 服务不可用或文档未索引时自动回退哈希向量（保持原行为）。
    semantic_query_vector: list[float] | None = None
    semantic_vectors: dict[str, list[float]] = {}
    if embedding_available():
        query_vectors = embed_texts([query])
        if query_vectors:
            semantic_query_vector = query_vectors[0]
            _ensure_knowledge_vectors_table()
            connection = db_connection()
            try:
                for row in connection.execute("SELECT path, vector FROM knowledge_vectors").fetchall():
                    try:
                        semantic_vectors[str(row["path"])] = json.loads(row["vector"])
                    except (json.JSONDecodeError, TypeError):
                        continue
            finally:
                connection.close()
    # Local hybrid retrieval: BM25-like IDF + field boosts + a deterministic
    # feature-hash vector. It remains fully offline and reproducible; the
    # vector is explicitly a lexical feature index, not a cloud embedding.
    documents = []
    document_frequency: dict[str, int] = {}
    for row in rows:
        note = obsidian_note_row(row)
        text = f"{note.get('title', '')} {note.get('preview', '')} {' '.join(note.get('tags', []))} {' '.join(note.get('links', []))} {row['search_text']}".lower()
        tokens = knowledge_tokens(text)
        features = knowledge_vector_features(text)
        absolute = str(OBSIDIAN_VAULT_DIR / str(note.get("path") or ""))
        document_vector = semantic_vectors.get(absolute) if semantic_query_vector else None
        documents.append((row, note, text, tokens, features, knowledge_hash_vector(features), document_vector, absolute))
        for token in tokens:
            document_frequency[token] = document_frequency.get(token, 0) + 1
    total_documents = max(1, len(documents))
    scored = []
    for row, note, text, note_tokens, _features, document_vector, semantic_doc_vector, absolute in documents:
        overlap = query_tokens.intersection(note_tokens)
        if semantic_query_vector and semantic_doc_vector:
            vector_score = _cosine_similarity(semantic_query_vector, semantic_doc_vector)
        else:
            vector_score = knowledge_vector_similarity(query_vector, document_vector)
        if not overlap and vector_score < 0.08:
            continue
        bm25_score = 0.0
        title_text = str(note.get("title") or "").lower()
        tags_text = " ".join(str(tag) for tag in note.get("tags", [])).lower()
        for token in overlap:
            idf = 1 + math.log((total_documents + 1) / (document_frequency.get(token, 0) + 1))
            tf = min(4, text.count(token))
            boost = 2.4 if token in title_text else 1.5 if token in tags_text else 1.0
            bm25_score += idf * tf * boost
        bm25_score = bm25_score / max(1.0, math.sqrt(len(note_tokens)))
        # Keep the lexical score dominant; vector features only improve recall
        # for related wording and never override a strong exact match.
        semantic_score = bm25_score + vector_score * 1.25
        path = OBSIDIAN_VAULT_DIR / str(note.get("path") or "")
        locators = []
        try:
            lines = path.read_text(encoding="utf-8", errors="ignore").splitlines()
            for number, line in enumerate(lines, start=1):
                if any(token in line.lower() for token in query_tokens):
                    locators.append({"line": number, "text": clip(line.strip(), 180)})
                    if len(locators) >= 4:
                        break
        except OSError:
            pass
        scored.append({
            **note,
            "semantic_score": round(semantic_score, 4),
            "bm25_score": round(bm25_score, 4),
            "vector_score": round(vector_score, 4),
            "matched_tokens": sorted(overlap)[:12],
            "citations": locators,
            "retrieval": "local-hybrid-bm25+hash-vector",
        })
    return sorted(scored, key=lambda item: (-item["semantic_score"], -float(item.get("mtime") or 0)))[:limit]


def obsidian_conflict_key(left: dict[str, Any], right: dict[str, Any]) -> str:
    values = sorted(
        [
            f"{left.get('path', '')}|{left.get('content_hash', '')}",
            f"{right.get('path', '')}|{right.get('content_hash', '')}",
        ]
    )
    return hashlib.sha256("\n".join(values).encode("utf-8", errors="replace")).hexdigest()[:24]


def list_knowledge_conflict_resolutions() -> dict[str, dict[str, Any]]:
    connection = db_connection()
    try:
        rows = connection.execute("SELECT * FROM knowledge_conflict_resolutions ORDER BY updated_at DESC").fetchall()
        return {str(row["conflict_key"]): dict(row) for row in rows}
    finally:
        connection.close()


def obsidian_conflict_paragraph_key(conflict_key: str, paragraph: dict[str, Any]) -> str:
    """Return a stable ID for one pair of line-addressable conflict evidence."""
    left = paragraph.get("left") if isinstance(paragraph.get("left"), dict) else {}
    right = paragraph.get("right") if isinstance(paragraph.get("right"), dict) else {}
    material = {
        "conflict_key": str(conflict_key or ""),
        "left_path": str(left.get("path") or ""),
        "left_line_start": int(left.get("line_start") or 0),
        "left_line_end": int(left.get("line_end") or 0),
        "left_text": str(left.get("text") or ""),
        "right_path": str(right.get("path") or ""),
        "right_line_start": int(right.get("line_start") or 0),
        "right_line_end": int(right.get("line_end") or 0),
        "right_text": str(right.get("text") or ""),
    }
    encoded = json.dumps(material, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(encoded.encode("utf-8", errors="replace")).hexdigest()[:24]


def list_knowledge_conflict_paragraph_resolutions(conflict_key: str | None = None) -> dict[str, dict[str, Any]]:
    connection = db_connection()
    try:
        if conflict_key:
            rows = connection.execute(
                "SELECT * FROM knowledge_conflict_paragraph_resolutions WHERE conflict_key = ? ORDER BY updated_at DESC",
                (str(conflict_key),),
            ).fetchall()
            return {str(row["paragraph_key"]): dict(row) for row in rows}
        rows = connection.execute(
            "SELECT * FROM knowledge_conflict_paragraph_resolutions ORDER BY updated_at DESC"
        ).fetchall()
        return {f"{row['conflict_key']}:{row['paragraph_key']}": dict(row) for row in rows}
    finally:
        connection.close()


def save_knowledge_conflict_paragraph_resolution(
    conflict: dict[str, Any], paragraph: dict[str, Any], action: str, note: str = ""
) -> dict[str, Any]:
    """Persist a paragraph decision while keeping both Vault notes untouched."""
    if action not in {"keep_left", "keep_right", "merge", "dismiss"}:
        raise ValueError("不支持的段落处理动作")
    conflict_key = str(conflict.get("conflict_key") or "").strip()
    paragraph_key = str(paragraph.get("paragraph_key") or obsidian_conflict_paragraph_key(conflict_key, paragraph)).strip()
    left = paragraph.get("left") if isinstance(paragraph.get("left"), dict) else {}
    right = paragraph.get("right") if isinstance(paragraph.get("right"), dict) else {}
    timestamp = now_iso()
    connection = db_connection()
    try:
        connection.execute(
            """INSERT INTO knowledge_conflict_paragraph_resolutions
            (conflict_key, paragraph_key, action, note, left_path, right_path,
             left_line_start, left_line_end, right_line_start, right_line_end,
             left_text, right_text, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(conflict_key, paragraph_key) DO UPDATE SET action=excluded.action,
              note=excluded.note, left_path=excluded.left_path, right_path=excluded.right_path,
              left_line_start=excluded.left_line_start, left_line_end=excluded.left_line_end,
              right_line_start=excluded.right_line_start, right_line_end=excluded.right_line_end,
              left_text=excluded.left_text, right_text=excluded.right_text,
              updated_at=excluded.updated_at""",
            (
                conflict_key,
                paragraph_key,
                action,
                clip(note, 2_000),
                str(left.get("path") or ""),
                str(right.get("path") or ""),
                int(left.get("line_start") or 0),
                int(left.get("line_end") or 0),
                int(right.get("line_start") or 0),
                int(right.get("line_end") or 0),
                clip(str(left.get("text") or ""), 2_000),
                clip(str(right.get("text") or ""), 2_000),
                timestamp,
                timestamp,
            ),
        )
        connection.commit()
        row = connection.execute(
            "SELECT * FROM knowledge_conflict_paragraph_resolutions WHERE conflict_key = ? AND paragraph_key = ?",
            (conflict_key, paragraph_key),
        ).fetchone()
        return dict(row) if row else {"conflict_key": conflict_key, "paragraph_key": paragraph_key, "action": action, "note": note}
    finally:
        connection.close()


def save_knowledge_conflict_resolution(conflict: dict[str, Any], action: str, note: str = "") -> dict[str, Any]:
    """Persist a human decision while keeping the Vault itself untouched."""
    left = conflict.get("left") if isinstance(conflict.get("left"), dict) else {}
    right = conflict.get("right") if isinstance(conflict.get("right"), dict) else {}
    key = str(conflict.get("conflict_key") or "").strip()
    timestamp = now_iso()
    connection = db_connection()
    try:
        connection.execute(
            """INSERT INTO knowledge_conflict_resolutions
            (conflict_key, action, note, left_path, right_path, left_hash, right_hash, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(conflict_key) DO UPDATE SET action=excluded.action, note=excluded.note,
              left_path=excluded.left_path, right_path=excluded.right_path, left_hash=excluded.left_hash,
              right_hash=excluded.right_hash, updated_at=excluded.updated_at""",
            (key, action, clip(note, 2_000), str(left.get("path") or ""), str(right.get("path") or ""), str(left.get("content_hash") or ""), str(right.get("content_hash") or ""), timestamp, timestamp),
        )
        connection.commit()
        row = connection.execute("SELECT * FROM knowledge_conflict_resolutions WHERE conflict_key = ?", (key,)).fetchone()
        return dict(row) if row else {"conflict_key": key, "action": action, "note": note}
    finally:
        connection.close()


def knowledge_conflict_draft(conflict: dict[str, Any], resolution: dict[str, Any]) -> dict[str, Any] | None:
    """Create a local review draft for merge; never write it into Obsidian."""
    if resolution.get("action") != "merge":
        return None
    left = conflict.get("left") if isinstance(conflict.get("left"), dict) else {}
    right = conflict.get("right") if isinstance(conflict.get("right"), dict) else {}
    left_path = OBSIDIAN_VAULT_DIR / str(left.get("path") or "")
    right_path = OBSIDIAN_VAULT_DIR / str(right.get("path") or "")
    try:
        left_text = left_path.read_text(encoding="utf-8", errors="ignore")
        right_text = right_path.read_text(encoding="utf-8", errors="ignore")
    except OSError as exc:
        raise ValueError(f"无法读取冲突笔记：{exc}") from exc
    title = f"知识冲突合并草稿 · {left.get('title') or left.get('path') or '左侧'}"
    paragraph_lines = []
    for index, pair in enumerate(conflict.get("paragraph_conflicts") or [], start=1):
        left_locator = pair.get("left") if isinstance(pair.get("left"), dict) else {}
        right_locator = pair.get("right") if isinstance(pair.get("right"), dict) else {}
        paragraph_lines.extend([
            f"### 段落冲突 {index} · {pair.get('kind_label') or '需要人工判断'}",
            f"- 左侧第 {left_locator.get('line_start', '?')}–{left_locator.get('line_end', '?')} 行：{left_locator.get('text', '')}",
            f"- 右侧第 {right_locator.get('line_start', '?')}–{right_locator.get('line_end', '?')} 行：{right_locator.get('text', '')}",
            f"- 相似度：{pair.get('similarity', '—')} · 信号：{pair.get('signal') or '主题相近'}",
            "",
        ])
    paragraph_section = "## 段落级冲突定位\n\n" + "\n".join(paragraph_lines) if paragraph_lines else ""
    body = (
        f"# {title}\n\n"
        f"> 冲突 key：{conflict.get('conflict_key')}\n"
        f"> 这是人工审阅草稿，不会自动写回 Obsidian。请核对数据时间和适用范围后再合并。\n\n"
        f"{paragraph_section}"
        f"## 左侧：{left.get('path', '')}\n\n{left_text.strip()}\n\n"
        f"## 右侧：{right.get('path', '')}\n\n{right_text.strip()}\n\n"
        f"## 合并说明\n\n{resolution.get('note') or '请在此处记录保留依据、冲突处理和最终结论。'}\n"
    )
    path = OUTPUTS_DIR / f"{datetime.now().strftime('%Y%m%d-%H%M%S')}-{safe_filename(title, 'knowledge-conflict')}.md"
    path.write_text(body, encoding="utf-8")
    return register_artifact_safely(project_id="knowledge", name=path.name, path=str(path), kind="knowledge_conflict_merge_draft", metadata={"title": title, "review_required": True, "conflict_key": conflict.get("conflict_key"), "left_path": left.get("path", ""), "right_path": right.get("path", ""), "resolution": resolution, "source_notes": [{"path": left.get("path", ""), "line_start": 1, "line_end": min(24, len(left_text.splitlines())), "content_hash": hashlib.sha256(left_text.encode("utf-8", errors="ignore")).hexdigest()}, {"path": right.get("path", ""), "line_start": 1, "line_end": min(24, len(right_text.splitlines())), "content_hash": hashlib.sha256(right_text.encode("utf-8", errors="ignore")).hexdigest()}], "source_note_hashes": {str(left.get("path") or ""): hashlib.sha256(left_text.encode("utf-8", errors="ignore")).hexdigest(), str(right.get("path") or ""): hashlib.sha256(right_text.encode("utf-8", errors="ignore")).hexdigest()}})


def knowledge_conflict_paragraph_draft(conflict: dict[str, Any], paragraph: dict[str, Any], resolution: dict[str, Any]) -> dict[str, Any] | None:
    """Create an auditable paragraph decision draft; never write back to Vault."""
    if resolution.get("action") not in {"keep_left", "keep_right", "merge"}:
        return None
    left = paragraph.get("left") if isinstance(paragraph.get("left"), dict) else {}
    right = paragraph.get("right") if isinstance(paragraph.get("right"), dict) else {}
    action = str(resolution.get("action"))
    action_label = {"keep_left": "保留左侧", "keep_right": "保留右侧", "merge": "合并审阅"}[action]
    if action == "keep_left":
        selected = str(left.get("text") or "")
        decision = f"保留左侧：{left.get('path', '')} 第 {left.get('line_start', '?')}–{left.get('line_end', '?')} 行"
    elif action == "keep_right":
        selected = str(right.get("text") or "")
        decision = f"保留右侧：{right.get('path', '')} 第 {right.get('line_start', '?')}–{right.get('line_end', '?')} 行"
    else:
        selected = f"### 左侧候选\n\n{left.get('text', '')}\n\n### 右侧候选\n\n{right.get('text', '')}\n\n### 人工合并区\n\n请在确认写入前整理为一段最终表述。"
        decision = "保留左右证据，等待人工合并"
    title = f"知识冲突段落 · {action_label} · {conflict.get('conflict_key', '')}-{paragraph.get('paragraph_key', '')}"
    body = (
        f"# {title}\n\n"
        f"> 这是段落级人工审阅草稿，不会自动修改 Obsidian。\n"
        f"> 冲突 key：{conflict.get('conflict_key', '')}\n"
        f"> 段落 key：{paragraph.get('paragraph_key', '')}\n\n"
        f"## 处理决定\n\n{decision}\n\n"
        f"## 段落内容\n\n{selected.strip()}\n\n"
        f"## 处理说明\n\n{resolution.get('note') or '请补充适用范围、数据时间和最终取舍依据。'}\n\n"
        f"## 来源定位\n\n"
        f"- 左侧：`{left.get('path', '')}` 第 {left.get('line_start', '?')}–{left.get('line_end', '?')} 行\n"
        f"- 右侧：`{right.get('path', '')}` 第 {right.get('line_start', '?')}–{right.get('line_end', '?')} 行\n"
    )
    path = OUTPUTS_DIR / f"{datetime.now().strftime('%Y%m%d-%H%M%S-%f')}-{safe_filename(title, 'knowledge-conflict-paragraph')}.md"
    path.write_text(body, encoding="utf-8")
    return register_artifact_safely(
        project_id="knowledge",
        name=path.name,
        path=str(path),
        kind="knowledge_conflict_paragraph_resolution",
        metadata={
            "title": title,
            "review_required": True,
            "conflict_key": conflict.get("conflict_key"),
            "paragraph_key": paragraph.get("paragraph_key"),
            "resolution": resolution,
            "source_notes": [
                {"path": left.get("path", ""), "line_start": left.get("line_start", 0), "line_end": left.get("line_end", 0), "content_hash": (conflict.get("left") or {}).get("content_hash", "")},
                {"path": right.get("path", ""), "line_start": right.get("line_start", 0), "line_end": right.get("line_end", 0), "content_hash": (conflict.get("right") or {}).get("content_hash", "")},
            ],
            "source_note_hashes": {str((conflict.get("left") or {}).get("path") or ""): (conflict.get("left") or {}).get("content_hash", ""), str((conflict.get("right") or {}).get("path") or ""): (conflict.get("right") or {}).get("content_hash", "")},
        },
    )


def _obsidian_paragraph_blocks(note: dict[str, Any], limit: int = 24) -> list[dict[str, Any]]:
    """Return bounded, line-addressable paragraphs for human conflict review."""
    path = OBSIDIAN_VAULT_DIR / str(note.get("path") or "")
    try:
        lines = path.read_text(encoding="utf-8", errors="ignore").splitlines()
    except OSError:
        return []
    blocks: list[dict[str, Any]] = []
    start = 0
    buffer: list[str] = []

    def flush(end_line: int) -> None:
        nonlocal start, buffer
        text = "\n".join(buffer).strip()
        if text:
            blocks.append({"line_start": start, "line_end": max(start, end_line), "text": clip(text, 500)})
        start = 0
        buffer = []

    for line_number, line in enumerate(lines, start=1):
        if line.strip():
            if not start:
                start = line_number
            buffer.append(line)
        elif start:
            flush(line_number - 1)
        if len(blocks) >= limit:
            break
    if start and len(blocks) < limit:
        flush(len(lines))
    return blocks[:limit]


def obsidian_paragraph_conflicts(left: dict[str, Any], right: dict[str, Any], contradiction_pairs: tuple[tuple[str, str], ...], conflict_key: str | None = None) -> list[dict[str, Any]]:
    """Locate bounded paragraph evidence instead of asking users to compare whole notes."""
    left_blocks = _obsidian_paragraph_blocks(left)
    right_blocks = _obsidian_paragraph_blocks(right)
    matches: list[dict[str, Any]] = []
    for left_block in left_blocks:
        left_tokens = knowledge_tokens(left_block["text"])
        if len(left_tokens) < 3:
            continue
        left_text = left_block["text"].lower()
        for right_block in right_blocks:
            right_tokens = knowledge_tokens(right_block["text"])
            overlap = len(left_tokens.intersection(right_tokens)) / max(1, len(left_tokens.union(right_tokens)))
            right_text = right_block["text"].lower()
            contradiction = next((pair for pair in contradiction_pairs if (pair[0] in left_text and pair[1] in right_text) or (pair[1] in left_text and pair[0] in right_text)), None)
            if overlap < (0.35 if contradiction else 0.72):
                continue
            match = {
                "left": left_block,
                "right": right_block,
                "similarity": round(overlap, 3),
                "kind": "confirmed_conflict" if contradiction else "possible_conflict",
                "kind_label": "明确矛盾" if contradiction else "段落相近",
                "signal": " / ".join(contradiction) if contradiction else "关键词和语义主题相近",
            }
            match["paragraph_key"] = obsidian_conflict_paragraph_key(conflict_key or obsidian_conflict_key(left, right), match)
            matches.append(match)
    matches.sort(key=lambda item: (item["kind"] != "confirmed_conflict", -item["similarity"]))
    return matches[:4]


def obsidian_conflict_report() -> dict[str, Any]:
    notes = [obsidian_note_row(row) for row in obsidian_index_rows()]
    resolutions = list_knowledge_conflict_resolutions()
    exact: dict[str, list[dict[str, Any]]] = {}
    for note in notes:
        exact.setdefault(str(note.get("content_hash") or ""), []).append(note)
    duplicate_groups = [group for key, group in exact.items() if key and len(group) > 1]
    near_matches = []
    confirmed_conflicts = []
    contradiction_pairs = (("支持", "反对"), ("可以", "不能"), ("适合", "不适合"), ("有效", "无效"), ("should", "should not"), ("yes", "no"))
    for index, first in enumerate(notes):
        left = knowledge_tokens(f"{first.get('title')} {first.get('preview')}")
        if len(left) < 3:
            continue
        for second in notes[index + 1:]:
            right = knowledge_tokens(f"{second.get('title')} {second.get('preview')}")
            similarity = len(left.intersection(right)) / max(1, len(left.union(right)))
            if similarity >= 0.62 and first.get("content_hash") != second.get("content_hash"):
                left_text = f"{first.get('title', '')} {first.get('preview', '')}".lower()
                right_text = f"{second.get('title', '')} {second.get('preview', '')}".lower()
                contradiction = next((pair for pair in contradiction_pairs if (pair[0] in left_text and pair[1] in right_text) or (pair[1] in left_text and pair[0] in right_text)), None)
                key = obsidian_conflict_key(first, second)
                paragraph_conflicts = obsidian_paragraph_conflicts(first, second, contradiction_pairs, key)
                paragraph_resolutions = list_knowledge_conflict_paragraph_resolutions(key)
                for paragraph in paragraph_conflicts:
                    paragraph["resolution"] = paragraph_resolutions.get(str(paragraph.get("paragraph_key")))
                entry = {"conflict_key": key, "left": first, "right": second, "similarity": round(similarity, 3), "kind": "confirmed_conflict" if contradiction else "possible_conflict", "resolution": resolutions.get(key), "paragraph_conflicts": paragraph_conflicts, "conflict_scope": "paragraph" if paragraph_conflicts else "note"}
                entry["paragraph_resolved_count"] = sum(1 for paragraph in paragraph_conflicts if paragraph.get("resolution"))
                if contradiction:
                    entry["contradiction_signal"] = list(contradiction)
                    confirmed_conflicts.append(entry)
                else:
                    near_matches.append(entry)
    all_conflicts = [*near_matches, *confirmed_conflicts]
    resolved_count = sum(1 for item in all_conflicts if item.get("resolution"))
    paragraph_resolved_count = sum(int(item.get("paragraph_resolved_count") or 0) for item in all_conflicts)
    return {
        "exact_duplicates": duplicate_groups,
        "possible_conflicts": near_matches[:100],
        "confirmed_conflicts": confirmed_conflicts[:100],
        "counts": {"exact": len(duplicate_groups), "possible": len(near_matches), "confirmed": len(confirmed_conflicts), "resolved": resolved_count, "paragraph_resolved": paragraph_resolved_count},
        "policy": "只提示相似或矛盾候选；解决记录只保存人工选择和来源指针，不自动改写 Vault。",
    }


def obsidian_retrieval_evaluation(sample_limit: int = 30, top_k: int = 5) -> dict[str, Any]:
    """Measure whether the hybrid index can retrieve a note from its title.

    This is a lightweight self-recall benchmark, useful for deciding whether
    an external embedding service is actually needed. It is not a relevance
    judgement and is never used as a fact-confidence score.
    """
    rows = obsidian_index_rows()
    samples = []
    baseline_hits = 0
    hybrid_hits = 0
    skipped_count = 0
    requested_count = min(len(rows), max(1, min(sample_limit, 100)))
    for row in rows[: max(1, min(sample_limit, 100))]:
        note = obsidian_note_row(row)
        title = str(note.get("title") or "").strip()
        if len(knowledge_tokens(title)) < 1:
            skipped_count += 1
            continue
        target = str(note.get("path") or "")
        baseline = obsidian_search(title, limit=top_k)
        hybrid = obsidian_semantic_results(title, limit=top_k)
        baseline_hit = any(str(item.get("path")) == target for item in baseline)
        hybrid_hit = any(str(item.get("path")) == target for item in hybrid)
        baseline_hits += int(baseline_hit)
        hybrid_hits += int(hybrid_hit)
        samples.append({"query": title, "target": target, "baseline_hit": baseline_hit, "hybrid_hit": hybrid_hit})
    count = len(samples)
    minimum_samples = 10
    baseline_recall = round(baseline_hits / count, 3) if count else None
    hybrid_recall = round(hybrid_hits / count, 3) if count else None
    return {
        "mode": "self-recall",
        "requested_count": requested_count,
        "sample_count": count,
        "skipped_count": skipped_count,
        "top_k": top_k,
        "baseline_recall": baseline_recall,
        "hybrid_recall": hybrid_recall,
        "hybrid_gain": round(hybrid_recall - baseline_recall, 3) if baseline_recall is not None and hybrid_recall is not None else None,
        "minimum_samples": minimum_samples,
        "sample_status": "ready" if count >= minimum_samples else "insufficient",
        "samples": samples[:20],
        "policy": "仅用于评估本地检索是否有明显瓶颈；不把自检召回率当成语义正确率。",
    }


def obsidian_moc_preview() -> dict[str, Any]:
    status = obsidian_moc_suggestions()
    suggestions = status.get("orphan_notes") or []
    return {"moc_count": status.get("moc_count", 0), "suggestions": suggestions, "policy": "预览不会修改 Vault；确认后才写入 MOC。"}


def apply_obsidian_moc(note_paths: list[str]) -> dict[str, Any]:
    candidates = [Path(path).expanduser().resolve() for path in note_paths[:100]]
    safe = [path for path in candidates if OBSIDIAN_VAULT_DIR.resolve() in path.parents and path.is_file()]
    moc_paths = [path for path in obsidian_note_paths() if "moc" in path.stem.lower() or "moc" in str(path.parent).lower()]
    if not moc_paths:
        raise ValueError("没有找到可维护的 MOC 文件")
    target = moc_paths[0]
    backup = target.with_suffix(target.suffix + f".workbench-{datetime.now().strftime('%Y%m%d-%H%M%S')}.bak")
    shutil.copy2(target, backup)
    existing = target.read_text(encoding="utf-8")
    additions = []
    for path in safe:
        link = f"- [[{path.stem}]]"
        if link not in existing:
            additions.append(link)
    if additions:
        target.write_text(existing.rstrip() + "\n\n## Workbench 建议链接\n" + "\n".join(additions) + "\n", encoding="utf-8")
    return {"ok": True, "path": str(target), "backup": str(backup), "added": len(additions), "links": additions}


class ObsidianMocApplyRequest(BaseModel):
    confirmed: bool = False
    note_paths: list[str] = Field(default_factory=list, max_length=100)


class KnowledgeSourceDraftRequest(BaseModel):
    title: str = Field(min_length=1, max_length=240)
    artifact_ids: list[int] = Field(default_factory=list, max_length=30)
