@app.post("/api/obsidian/conflicts/{conflict_key}/resolve")
def resolve_obsidian_conflict(conflict_key: str, request: ObsidianConflictResolutionRequest) -> dict[str, Any]:
    if not request.confirmed:
        raise HTTPException(409, "记录冲突处理前需要明确确认")
    report = obsidian_conflict_report()
    conflict = next((item for item in [*report.get("possible_conflicts", []), *report.get("confirmed_conflicts", [])] if str(item.get("conflict_key")) == conflict_key), None)
    if not conflict:
        raise HTTPException(404, "冲突候选不存在，可能需要先重新索引 Vault")
    resolution = save_knowledge_conflict_resolution(conflict, request.action, request.note)
    artifact = register_artifact_safely(project_id="knowledge", name=f"知识冲突处理 · {conflict_key}", kind="knowledge_conflict_resolution", metadata={"conflict_key": conflict_key, "action": request.action, "note": request.note, "left_path": conflict.get("left", {}).get("path", ""), "right_path": conflict.get("right", {}).get("path", "")})
    relations = []
    if artifact:
        for side, label in ((conflict.get("left") or {}, "left"), (conflict.get("right") or {}, "right")):
            if side.get("path"):
                relations.append(create_relation_record(from_type="artifact", from_id=str(artifact.get("id")), to_type="obsidian_note", to_id=str(side.get("path")), relation_type="conflict_resolution_source", metadata={"side": label, "action": request.action, "conflict_key": conflict_key}))
    draft = knowledge_conflict_draft(conflict, resolution)
    if draft and artifact and draft.get("id"):
        relations.append(create_relation_record(from_type="artifact", from_id=str(artifact.get("id")), to_type="artifact", to_id=str(draft.get("id")), relation_type="conflict_to_merge_draft", metadata={"conflict_key": conflict_key}))
    return {"ok": True, "resolution": resolution, "artifact": artifact, "draft": draft, "relations": relations, "message": "已记录人工处理决定；原始 Obsidian 笔记未被改写。"}


@app.post("/api/obsidian/conflicts/{conflict_key}/paragraphs/{paragraph_key}/resolve")
def resolve_obsidian_conflict_paragraph(conflict_key: str, paragraph_key: str, request: ObsidianConflictParagraphResolutionRequest) -> dict[str, Any]:
    if not request.confirmed:
        raise HTTPException(409, "记录段落冲突处理前需要明确确认")
    report = obsidian_conflict_report()
    conflict = next((item for item in [*report.get("possible_conflicts", []), *report.get("confirmed_conflicts", [])] if str(item.get("conflict_key")) == conflict_key), None)
    if not conflict:
        raise HTTPException(404, "冲突候选不存在，可能需要先重新索引 Vault")
    paragraph = next((item for item in conflict.get("paragraph_conflicts", []) if str(item.get("paragraph_key")) == paragraph_key), None)
    if not paragraph:
        raise HTTPException(404, "段落冲突证据不存在，可能需要先重新索引 Vault")
    resolution = save_knowledge_conflict_paragraph_resolution(conflict, paragraph, request.action, request.note)
    artifact = register_artifact_safely(
        project_id="knowledge",
        name=f"知识冲突段落处理 · {paragraph_key}",
        kind="knowledge_conflict_paragraph_resolution_record",
        metadata={
            "title": f"知识冲突段落处理 · {paragraph_key}",
            "review_required": True,
            "conflict_key": conflict_key,
            "paragraph_key": paragraph_key,
            "action": request.action,
            "note": request.note,
            "source_notes": [
                {"path": (paragraph.get("left") or {}).get("path", ""), "line_start": (paragraph.get("left") or {}).get("line_start", 0), "line_end": (paragraph.get("left") or {}).get("line_end", 0)},
                {"path": (paragraph.get("right") or {}).get("path", ""), "line_start": (paragraph.get("right") or {}).get("line_start", 0), "line_end": (paragraph.get("right") or {}).get("line_end", 0)},
            ],
        },
    )
    draft = knowledge_conflict_paragraph_draft(conflict, paragraph, resolution)
    relations = []
    for side, label in ((paragraph.get("left") or {}, "left"), (paragraph.get("right") or {}, "right")):
        if side.get("path") and artifact:
            relations.append(create_relation_record(from_type="artifact", from_id=str(artifact.get("id")), to_type="obsidian_note", to_id=str(side.get("path")), relation_type="conflict_paragraph_source", metadata={"side": label, "action": request.action, "conflict_key": conflict_key, "paragraph_key": paragraph_key, "line_start": side.get("line_start"), "line_end": side.get("line_end")}))
    if draft and artifact and draft.get("id"):
        relations.append(create_relation_record(from_type="artifact", from_id=str(artifact.get("id")), to_type="artifact", to_id=str(draft.get("id")), relation_type="conflict_paragraph_to_review_draft", metadata={"conflict_key": conflict_key, "paragraph_key": paragraph_key, "action": request.action}))
    return {"ok": True, "resolution": resolution, "artifact": artifact, "draft": draft, "relations": relations, "message": "已记录段落处理决定；原始 Obsidian 笔记未被改写。" if not draft else "已记录段落处理决定并生成可审阅草稿；原始 Obsidian 笔记未被改写。"}


