@app.post("/api/market/research/{item_id}/conclude")
def conclude_market_research(item_id: int, request: MarketResearchConclusionRequest) -> dict[str, Any]:
    if not request.confirmed:
        raise HTTPException(409, "沉淀行情研究结论前需要明确确认")
    item = get_work_item_record(item_id)
    if not item or item.get("source_project") != "market" or item.get("kind") != "market_event_research":
        raise HTTPException(404, "行情研究任务不存在")
    metadata = item.get("metadata") if isinstance(item.get("metadata"), dict) else {}
    existing_id = metadata.get("conclusion_artifact_id")
    if str(existing_id).isdigit():
        existing_artifact = get_artifact_record(int(existing_id))
        if existing_artifact:
            return {"ok": True, "already_concluded": True, "item": item, "note": {"artifact": existing_artifact}, "message": "这条行情研究已经沉淀过结论。"}
    artifact_id = metadata.get("artifact_id")
    source = get_artifact_record(int(artifact_id)) if str(artifact_id).isdigit() else None
    title = clip(item.get("title") or "行情研究结论", 120)
    note = write_knowledge_note(f"行情研究结论｜{title}", f"> 来源工作项：行情 #{item_id}\n> 数据时间：{metadata.get('checked_at') or (source or {}).get('metadata', {}).get('checked_at') or '未记录'}\n\n## 结论\n\n{request.conclusion.strip()}\n\n## 风险边界\n\n本结论基于本地快照和人工补充，只作研究记录，不构成投资建议。", metadata={"source_market_work_item_id": item_id, "source_artifact_id": source.get("id") if source else None, "confirmed": request.confirmed}, artifact_kind="market_research_conclusion")
    relation = create_relation_record(from_type="work_item", from_id=str(item_id), to_type="artifact", to_id=str(note.get("artifact", {}).get("id", "")), relation_type="research_to_knowledge", metadata={"confirmed": request.confirmed}) if note.get("artifact") else None
    conclusion_artifact_id = note.get("artifact", {}).get("id") if note.get("artifact") else None
    updated_metadata = {**metadata, "conclusion_artifact_id": conclusion_artifact_id, "concluded_at": now_iso(), "conclusion": request.conclusion.strip()}
    updated = update_work_item_record(item_id, {"status": "done", "completed_at": now_iso(), "metadata_json": json.dumps(updated_metadata, ensure_ascii=False), "result_json": json.dumps({"knowledge_artifact_id": conclusion_artifact_id, "conclusion": request.conclusion.strip()}, ensure_ascii=False), "last_error": ""})
    return {"ok": True, "item": updated, "note": note, "relation": relation, "message": "研究结论已沉淀到工作区知识库。"}


SERVER_SAFE_ACTIONS = {"refresh": {"label": "重新执行只读检查", "risk": "low"}, "inspect_logs": {"label": "记录服务日志检查请求", "risk": "low"}, "restart": {"label": "申请重启 Workbench 服务", "risk": "high"}}


def _server_action_execution_payload(row: sqlite3.Row | dict[str, Any] | None) -> dict[str, Any] | None:
    if not row:
        return None
    item = dict(row)
    item["result"] = platform_decode_json(item.pop("result_json", "{}"), {})
    item["rollback"] = platform_decode_json(item.pop("rollback_json", "{}"), {})
    item["rollback_available"] = bool(item.get("rollback", {}).get("previous_snapshot")) and not item.get("rolled_back_at")
    return item


def latest_server_action_execution(approval_id: str) -> dict[str, Any] | None:
    connection = db_connection()
    try:
        row = connection.execute("SELECT * FROM server_action_executions WHERE approval_id = ? ORDER BY created_at DESC LIMIT 1", (approval_id,)).fetchone()
        return _server_action_execution_payload(row)
    finally:
        connection.close()


def list_server_action_executions(limit: int = 80) -> list[dict[str, Any]]:
    connection = db_connection()
    try:
        rows = connection.execute("SELECT * FROM server_action_executions ORDER BY created_at DESC LIMIT ?", (max(1, min(200, int(limit or 80))),)).fetchall()
        return [item for row in rows if (item := _server_action_execution_payload(row))]
    finally:
        connection.close()


def create_server_action_execution(approval_id: str, action: str) -> dict[str, Any]:
    execution_id = uuid.uuid4().hex
    timestamp = now_iso()
    connection = db_connection()
    try:
        connection.execute(
            "INSERT INTO server_action_executions(id, approval_id, action, status, created_at) VALUES (?, ?, ?, 'running', ?)",
            (execution_id, approval_id, action, timestamp),
        )
        connection.commit()
    finally:
        connection.close()
    return {"id": execution_id, "approval_id": approval_id, "action": action, "status": "running", "result": {}, "rollback": {}, "rollback_available": False, "created_at": timestamp, "finished_at": "", "rolled_back_at": ""}


def finish_server_action_execution(execution_id: str, *, status: str, result: dict[str, Any] | None = None, error: str = "", rollback: dict[str, Any] | None = None) -> dict[str, Any] | None:
    timestamp = now_iso()
    connection = db_connection()
    try:
        connection.execute(
            "UPDATE server_action_executions SET status = ?, result_json = ?, error = ?, rollback_json = ?, finished_at = ?, updated_at = ? WHERE id = ?",
            (status, json.dumps(result or {}, ensure_ascii=False), error, json.dumps(rollback or {}, ensure_ascii=False), timestamp, timestamp, execution_id),
        )
        connection.commit()
        row = connection.execute("SELECT * FROM server_action_executions WHERE id = ?", (execution_id,)).fetchone()
        return _server_action_execution_payload(row)
    finally:
        connection.close()


async def execute_approved_server_action(approval_id: str) -> dict[str, Any]:
    connection = db_connection()
    try:
        row = connection.execute("SELECT * FROM approval_requests WHERE id = ?", (approval_id,)).fetchone()
    finally:
        connection.close()
    if not row:
        raise HTTPException(404, "审批请求不存在")
    if row["kind"] != "server_action":
        raise HTTPException(409, "这不是服务器动作审批")
    if row["status"] != "approved":
        raise HTTPException(409, "服务器动作必须先审批通过")
    payload = platform_decode_json(row["payload_json"], {})
    action = str(payload.get("action") or "").strip()
    definition = SERVER_SAFE_ACTIONS.get(action)
    if not definition:
        raise HTTPException(400, "审批中的服务器动作已不在安全白名单")
    existing = latest_server_action_execution(approval_id)
    if existing and existing.get("status") in {"succeeded", "manual_required"} and not existing.get("rolled_back_at"):
        return {"ok": existing.get("status") == "succeeded", "execution": existing, "message": "这条审批已经执行过，避免重复执行。"}
    execution = create_server_action_execution(approval_id, action)
    run = create_agent_run_record(
        project_id="server",
        kind="server_action_execution",
        title=f"执行服务器动作：{definition['label']}",
        request={"approval_id": approval_id, "action": action, "risk": definition["risk"]},
        max_attempts=1,
    )
    update_agent_run_record(run["id"], status="running")
    add_agent_run_event(run["id"], "execution_started", f"已按审批执行：{definition['label']}。", metadata={"approval_id": approval_id, "execution_id": execution["id"]})
    try:
        if action == "refresh":
            previous_snapshot = load_server_monitor_snapshot()
            result = await refresh_server_monitor(ServerMonitorRequest(refresh=True))
            finished = finish_server_action_execution(
                execution["id"],
                status="succeeded",
                result={"message": "只读服务器检查已完成", "response": {"status": result.get("server", {}).get("status"), "checked_at": result.get("server", {}).get("checked_at"), "artifact_id": (result.get("artifact") or {}).get("id")}},
                rollback={"previous_snapshot": previous_snapshot, "note": "回退只恢复工作台中的上一份监控快照，不会回退服务器外部状态。"},
            )
            update_agent_run_record(run["id"], status="succeeded", result={"approval_id": approval_id, "execution_id": execution["id"], "action": action})
            add_agent_run_event(run["id"], "execution_succeeded", "只读服务器检查已完成，可按需回退本地快照。", level="success", metadata={"execution_id": execution["id"]})
            return {"ok": True, "execution": finished, "run": get_agent_run(run["id"]), "message": "只读服务器检查已完成。"}
        message = "日志读取需要服务器侧人工查看；本次已记录执行边界。" if action == "inspect_logs" else "重启属于高风险动作，仍需服务器侧人工执行；本次仅记录审批和执行边界。"
        finished = finish_server_action_execution(execution["id"], status="manual_required", result={"message": message, "execution_policy": "不通过 Workbench 自动运行 shell 或重启命令。"})
        update_agent_run_record(run["id"], status="succeeded", result={"approval_id": approval_id, "execution_id": execution["id"], "action": action, "manual_required": True})
        add_agent_run_event(run["id"], "manual_required", message, level="warning", metadata={"execution_id": execution["id"]})
        return {"ok": False, "execution": finished, "run": get_agent_run(run["id"]), "message": message}
    except Exception as exc:
        error = clip(str(exc), 800)
        finish_server_action_execution(execution["id"], status="failed", error=error)
        update_agent_run_record(run["id"], status="failed", error=error)
        add_agent_run_event(run["id"], "execution_failed", error, level="error", metadata={"execution_id": execution["id"]})
        raise HTTPException(502, f"服务器动作执行失败：{error}") from exc


def rollback_server_action_execution(execution_id: str) -> dict[str, Any]:
    connection = db_connection()
    try:
        row = connection.execute("SELECT * FROM server_action_executions WHERE id = ?", (execution_id,)).fetchone()
    finally:
        connection.close()
    execution = _server_action_execution_payload(row)
    if not execution:
        raise HTTPException(404, "服务器动作执行记录不存在")
    if execution.get("action") != "refresh" or execution.get("status") != "succeeded":
        raise HTTPException(409, "只有成功的只读检查可以回退本地监控快照")
    previous_snapshot = execution.get("rollback", {}).get("previous_snapshot")
    if not isinstance(previous_snapshot, dict):
        raise HTTPException(409, "没有可回退的上一份监控快照")
    save_server_monitor_snapshot(previous_snapshot)
    record_server_monitor_snapshot(previous_snapshot)
    timestamp = now_iso()
    connection = db_connection()
    try:
        connection.execute("UPDATE server_action_executions SET status = 'rolled_back', rolled_back_at = ?, updated_at = ? WHERE id = ?", (timestamp, timestamp, execution_id))
        connection.commit()
        row = connection.execute("SELECT * FROM server_action_executions WHERE id = ?", (execution_id,)).fetchone()
    finally:
        connection.close()
    return {"ok": True, "execution": _server_action_execution_payload(row), "message": "已回退工作台中的上一份监控快照；不影响服务器外部状态。"}


@app.post("/api/server/actions/request")
def request_server_action(request: ServerActionRequest) -> dict[str, Any]:
    action = request.action.strip()
    definition = SERVER_SAFE_ACTIONS.get(action)
    if not definition:
        raise HTTPException(400, "不支持的服务器动作")
    if not request.confirmed:
        raise HTTPException(409, "服务器动作需要明确确认")
    approval = create_approval_request("server", "server_action", f"服务器动作审批：{definition['label']}", {"action": action, "reason": request.reason.strip(), "risk": definition["risk"], "execution_policy": "仅允许白名单只读动作；restart 仍需服务器侧人工执行"})
    item = create_work_item_record(title=definition["label"], description=request.reason.strip() or "请在审批后按安全边界处理服务器动作。", kind="server_action", status="blocked", priority="high" if definition["risk"] == "high" else "normal", source_project="server", target_project="server", metadata={"approval_id": approval["id"], "action": action, "risk": definition["risk"]})
    relation = create_relation_record(from_type="approval", from_id=approval["id"], to_type="work_item", to_id=str(item["id"]), relation_type="approval_to_server_action", metadata={"action": action})
    create_notification_record(title="服务器动作已进入审批", body=f"{definition['label']} · 请先在审批中心处理。", project_id="server", kind="approval", level="warning", href="/approvals", event_key=f"server-action:{approval['id']}", dedupe_seconds=0)
    return {"ok": True, "approval": approval, "work_item": item, "relation": relation, "message": "已建立审批和执行日志；不会直接改动服务器。"}


@app.get("/api/server/actions/executions")
def get_server_action_executions(limit: int = 80) -> dict[str, Any]:
    return {"executions": list_server_action_executions(limit), "policy": "只读检查可在批准后执行；日志查看和重启保留服务器侧人工边界。"}


@app.post("/api/server/actions/{approval_id}/execute")
async def execute_server_action(approval_id: str) -> dict[str, Any]:
    return await execute_approved_server_action(approval_id)


@app.post("/api/server/actions/executions/{execution_id}/rollback")
def rollback_server_action(execution_id: str) -> dict[str, Any]:
    return rollback_server_action_execution(execution_id)


# ═══════════════ 量化 2.0：研究卡 / ETF 轮动 / 可转债 / 估值百分位 / 组合体检 / AI 一眼看 ═══════════════

async def _tencent_kline(symbol: str, days: int = 40) -> list[dict[str, Any]]:
    """腾讯日 K 线（前复权）：symbol 如 sh510300 / sz159915；返回 [{date, close}] 升序。"""
    try:
        url = f"https://web.ifzq.gtimg.cn/appstock/app/fqkline/get?param={symbol},day,,,{days + 10},qfq"
        async with httpx.AsyncClient(timeout=10, trust_env=False, headers={"User-Agent": "Mozilla/5.0"}) as client:
            response = await client.get(url)
            response.raise_for_status()
            payload = response.json()
        node = ((payload or {}).get("data") or {}).get(symbol) or {}
        klines = node.get("qfqday") or node.get("day") or []
        rows = []
        for parts in klines:
            if len(parts) >= 3:
                close = parse_market_number(parts[2])
                if close and close > 0:
                    rows.append({"date": str(parts[0]), "close": close})
        return rows[-days:]
    except Exception:
        return []


async def market_etf_rotation() -> dict[str, Any]:
    """宽基 ETF 动量轮动：候选池 20 日动量排序 + 绝对动量过滤建议。"""
    pool = [
        {"symbol": "sh510300", "name": "沪深300ETF"},
        {"symbol": "sh510500", "name": "中证500ETF"},
        {"symbol": "sz159915", "name": "创业板ETF"},
        {"symbol": "sh588000", "name": "科创50ETF"},
    ]
    results = []
    for item in pool:
        klines = await _tencent_kline(item["symbol"], 30)
        if len(klines) < 2:
            results.append({**item, "momentum_20d": None, "latest": None, "ok": False, "note": "行情不足"})
            continue
        latest = klines[-1]["close"]
        base = klines[0]["close"]
        momentum = round((latest - base) / base * 100, 2)
        results.append({**item, "momentum_20d": momentum, "latest": latest, "ok": True, "note": ""})
    ranked = [r for r in results if r.get("ok") and r.get("momentum_20d") is not None]
    ranked.sort(key=lambda r: r["momentum_20d"], reverse=True)
    top = ranked[0] if ranked else None
    suggestion = ""
    if top:
        if top["momentum_20d"] <= 0:
            suggestion = f"{top['name']} 动量 {top['momentum_20d']}% 仍为负，按绝对动量过滤建议空仓观望（或转债券/货币）。"
        else:
            suggestion = f"建议关注 {top['name']}（20 日动量 {top['momentum_20d']}% 最强）；跌破其 20 日均线或动量转负再换仓。"
    return {
        "pool": results,
        "suggestion": suggestion,
        "note": "动量 = 近 20 个交易日涨幅；只作研究参考，不构成投资建议。",
    }


async def _tencent_convertible_quotes(codes: list[str]) -> dict[str, dict[str, Any]]:
    """腾讯行情批量查询可转债现价/涨跌幅/溢价（GBK 编码需转码）。

    返回 {code: {"price", "change_pct", "premium"}}；失败字段为 None。
    """
    if not codes:
        return {}
    result: dict[str, dict[str, Any]] = {}
    try:
        url = "https://qt.gtimg.cn/q=" + ",".join(codes)
        async with httpx.AsyncClient(timeout=10, trust_env=False, headers={"User-Agent": "Mozilla/5.0"}) as client:
            response = await client.get(url)
            response.raise_for_status()
            text = response.content.decode("gbk", errors="replace")
        for line in text.splitlines():
            line = line.strip()
            if not line or "=" not in line:
                continue
            body = line.split("=", 1)[1].strip().strip(";").strip('"')
            fields = body.split("~")
            if len(fields) < 40:
                continue
            code = str(fields[2] or "").strip()
            price = parse_market_number(fields[3])
            change_pct = parse_market_number(fields[32] if len(fields) > 32 else None)
            # 转股溢价率在部分代码段不返回，尽力而为
            premium = parse_market_number(fields[47] if len(fields) > 47 else None)
            result[code] = {
                "price": price,
                "change_pct": change_pct,
                "premium": premium,
            }
    except Exception:
        pass
    return result


async def market_convertible_bonds(limit: int = 30) -> dict[str, Any]:
    """可转债低价/双低筛选：东财数据中心取存续转债静态信息（评级/到期/转股价），腾讯行情补实时价与溢价。

    溢价率字段不稳定时降级为低价优先（诚实标注）。只作研究参考。
    """
    try:
        today = datetime.now().strftime("%Y-%m-%d")
        url = (
            "https://datacenter.eastmoney.com/securities/api/data/v1/get?reportName=RPT_BOND_CB_LIST"
            "&columns=ALL&pageSize=300&pageNumber=1&sortColumns=EXPIRE_DATE&sortTypes=1"
            f"&filter=(EXPIRE_DATE%3E%3D%27{today}%27)"
        )
        async with httpx.AsyncClient(timeout=12, trust_env=False, headers={"User-Agent": "Mozilla/5.0", "Referer": "https://data.eastmoney.com/"}) as client:
            response = await client.get(url)
            response.raise_for_status()
            payload = response.json()
        rows = (((payload or {}).get("result") or {}).get("data")) or []
        rows = rows[:200]
        # 腾讯行情批量补实时价（一次最多 60 个代码）
        premium_available = False
        bonds: list[dict[str, Any]] = []
        for i in range(0, len(rows), 60):
            chunk = rows[i : i + 60]
            code_prefix = {
                str(item.get("SECURITY_CODE") or "").strip(): ("sh" if str(item.get("SECUCODE") or "").endswith(".SH") else "sz")
                for item in chunk
            }
            tencent_codes = [prefix + code for code, prefix in code_prefix.items() if code]
            quotes = await _tencent_convertible_quotes(tencent_codes)
            for item in chunk:
                code = str(item.get("SECURITY_CODE") or "").strip()
                quote = quotes.get(code_prefix.get(code, "") + code) if code else None
                price = (quote or {}).get("price")
                if price is None or price <= 0:
                    continue
                premium = (quote or {}).get("premium")
                if premium is not None:
                    premium_available = True
                double_low = round(price + (premium or 0), 2)
                bonds.append({
                    "symbol": code,
                    "name": str(item.get("SECURITY_NAME_ABBR") or f"{code}转债"),
                    "price": price,
                    "change_pct": (quote or {}).get("change_pct"),
                    "premium": premium,
                    "double_low": double_low,
                    "rating": str(item.get("RATING") or ""),
                    "expire_date": str(item.get("EXPIRE_DATE") or "")[:10],
                    "convert_stock": str(item.get("CONVERT_STOCK_CODE") or ""),
                    "is_redeem": str(item.get("IS_REDEEM") or ""),
                })
        bonds = [b for b in bonds if b["price"] < 130]
        bonds.sort(key=lambda b: (b["premium"] is not None, b["double_low"] if b["premium"] is not None else b["price"]))
        return {
            "bonds": bonds[:limit],
            "premium_available": premium_available,
            "note": "双低 = 价格 + 转股溢价率（越低性价比越高）；溢价率不可用时按低价筛选。评级/到期来自交易所数据。只作研究参考。",
        }
    except Exception as exc:
        return {"bonds": [], "premium_available": False, "note": f"可转债数据读取失败：{clip(str(exc), 200)}"}


async def market_valuation_percentile() -> dict[str, Any]:
    """宽基指数估值百分位（蛋卷公开估值接口）：pe/pb 历史分位 + 估值区间标签。"""
    try:
        async with httpx.AsyncClient(timeout=10, trust_env=False, headers={"User-Agent": "Mozilla/5.0"}) as client:
            response = await client.get("https://danjuanfunds.com/djapi/index_eva/dj")
            response.raise_for_status()
            payload = response.json()
        items = ((payload or {}).get("data") or {}).get("items") or []
        wanted = ["沪深300", "中证500", "创业板", "科创50", "上证50"]
        result = []
        for item in items:
            name = str(item.get("name") or "")
            if not any(k in name for k in wanted):
                continue
            pe_pct = item.get("pe_percentile")
            pb_pct = item.get("pb_percentile")
            eva = str(item.get("eva_type") or "")
            label = {"low": "低估", "normal": "适中", "high": "偏高"}.get(eva, eva or "未知")
            result.append({
                "name": name,
                "index_code": item.get("index_code"),
                "pe": round(float(item.get("pe") or 0), 2) if item.get("pe") else None,
                "pb": round(float(item.get("pb") or 0), 2) if item.get("pb") else None,
                "pe_percentile": round(float(pe_pct or 0), 3) if pe_pct else None,
                "pb_percentile": round(float(pb_pct or 0), 3) if pb_pct else None,
                "roe": round(float(item.get("roe") or 0), 3) if item.get("roe") else None,
                "eva_label": label,
            })
        return {"indices": result, "note": "百分位 = 当前 PE/PB 处于历史什么位置；>0.8 偏贵、<0.2 偏便宜（用于定投/仓位参考）。"}
    except Exception as exc:
        return {"indices": [], "note": f"指数估值读取失败：{clip(str(exc), 200)}"}


async def market_portfolio_check() -> dict[str, Any]:
    """组合体检：基于自选行情与历史快照，给出集中度/相关性/波动观察。"""
    snapshot = load_market_snapshot()
    watchlist = snapshot.get("watchlist") or []
    quotes = snapshot.get("quotes") or []
    if not watchlist:
        return {"ok": False, "note": "还没有自选股票，先添加自选再看组合体检。"}
    def _pos(value):
        try:
            return isinstance(value, (int, float)) and float(value) > 0
        except (TypeError, ValueError):
            return False
    up = [q for q in quotes if _pos(q.get("change_pct"))]
    down = [q for q in quotes if (lambda v: isinstance(v, (int, float)) and float(v) < 0)(q.get("change_pct"))]
    trends = {str(q.get("symbol") or "").lower(): [p.get("p") for p in (q.get("trend") or []) if isinstance(p.get("p"), (int, float))] for q in quotes}
    return {
        "ok": True,
        "count": len(watchlist),
        "up_count": len(up),
        "down_count": len(down),
        "symbols": [str(q.get("symbol") or "").upper() for q in quotes],
        "trend_points": {k: len(v) for k, v in trends.items() if v},
        "note": "相关性计算需要每个标的至少 5 个历史快照点；样本不足的标的会标注。只作研究参考。",
    }


async def market_research_card(symbol: str) -> dict[str, Any]:
    """个股研究卡（三块合一）：行情 + 估值 + 量化回测/样本外 + 价值清单。"""
    symbol = str(symbol or "").strip().lower()
    if not symbol:
        return {"ok": False, "message": "请先填写股票代码。"}
    norm = normalize_market_symbol(symbol)
    if not norm:
        return {"ok": False, "message": "代码格式无效，例如 600519 或 sh600519。"}
    quote = None
    try:
        quotes = await fetch_market_quotes([norm])
        quote = quotes[0] if quotes else None
    except Exception:
        quote = None
    backtests = {}
    walkforward = {}
    for strategy in ("momentum", "mean_reversion"):
        try:
            body = await asyncio.to_thread(market_backtest, symbol, strategy, 20, 10, 5, None)
            backtests[strategy] = {
                "status": body.get("status"),
                "net_return_pct": body.get("net_return_pct"),
                "benchmark_return_pct": body.get("benchmark_return_pct"),
                "max_drawdown_pct": body.get("max_drawdown_pct"),
                "sample_count": body.get("sample_count"),
                "message": body.get("message"),
            }
        except Exception:
            backtests[strategy] = {"status": "error", "message": "回测失败"}
    try:
        wf = await asyncio.to_thread(
            market_walk_forward, symbol, "momentum", 20, 30, 5, 5, 8, 10, 5
        )
        walkforward = {
            "status": wf.get("status"),
            "out_of_sample_return_pct": wf.get("out_of_sample_return_pct"),
            "fold_count": wf.get("fold_count"),
            "positive_fold_rate": wf.get("out_of_sample_positive_fold_rate"),
            "message": wf.get("message"),
        }
    except Exception:
        walkforward = {"status": "error", "message": "样本外验证失败"}
    return {
        "ok": True,
        "symbol": norm,
        "quote": quote,
        "backtests": backtests,
        "walkforward": walkforward,
        "warnings": [],
        "note": "价值清单（护城河/ROE/负债率/自由现金流）需要人工核对后填写；量化部分基于本地历史快照，只作研究参考。",
    }


async def market_ai_scan(question: str = "") -> dict[str, Any]:
    """AI 一眼看：基于自选行情与观察信号生成人话总结；可带追问问题。"""
    snapshot = load_market_snapshot()
    watchlist = snapshot.get("watchlist") or []
    quotes = snapshot.get("quotes") or []
    if not quotes:
        return {"ok": False, "answer": "还没有行情数据。先添加自选并刷新行情，再让我看一眼。"}
    lines = []
    for q in quotes[:12]:
        change = q.get("change_pct")
        change_text = ("+" + str(change) + "%") if isinstance(change, (int, float)) and float(change) > 0 else (str(change) + "%") if isinstance(change, (int, float)) else "—"
        lines.append(f"{q.get('name') or q.get('symbol')}({str(q.get('symbol') or '').upper()}): {q.get('price')} {change_text}")
    summary_text = "；".join(lines)
    question = str(question or "").strip()
    prompt = (
        "你是量化研究助手。下面是用户自选股的最新行情快照（时间、来源以快照为准）：\n"
        f"{summary_text}\n"
    )
    if question:
        prompt += f"用户追问：{question}\n请结合快照数据回答，区分事实与判断，缺数据就明说。"
    else:
        prompt += "请用 3-5 句话总结今天值得注意的点：整体强弱、最值得关注的标的及原因、需要警惕的信号。区分事实与判断，不构成投资建议。"
    try:
        answer = await call_llm(
            [{"role": "system", "content": "你是量化研究助手，说话要有人味、结论要带数据时间和依据，缺数据就明说，不构成投资建议。"}, {"role": "user", "content": prompt}],
            max_tokens=1200,
            temperature=0.3,
            purpose="market_ai_scan",
        )
    except Exception as exc:
        return {"ok": False, "answer": f"AI 一眼看暂时不可用：{clip(str(exc), 300)}"}
    return {"ok": True, "answer": answer}


